(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("philo-the-special-laws-i-e", [{"sp": "HDR", "t": "Περὶ τῶν ἐν μέρει διαταγμάτων Α"}, {"sp": "N", "t": "Τὰ μὲν γένη τῶν ἐν εἴδει νόμων, οἱ προσαγορευόμενοι δέκα λόγοι, διὰ τῆς προτέρας ἠκρίβωνται συντάξεως, τὰ δ’ ἐν μέρει διατάγματα κατὰ τὴν τῆς γραφῆς ἀκολουθίαν νῦν ἐπισκεπτέον. ἄρξομαι δ’ ἀπὸ τοῦ γελωμένου παρὰ τοῖς πολλοῖς.", "st": "1"}, {"sp": "N", "t": "γελᾶται δὲ ἡ τῶν γεννητικῶν περιτομή, πρᾶγμα σπουδαζόμενον οὐ μετρίως καὶ παρ’ ἑτέροις ἔθνεσι καὶ μάλιστα τῷ Αἰγυπτιακῷ, ὃ καὶ πολυανθρωπότατον καὶ ἀρχαιότατον καὶ φιλοσοφώτατον εἶναι δοκεῖ.", "st": "2"}, {"sp": "N", "t": "παρὸ καὶ προσῆκον ἦν παιδικὴν χλεύην μεθεμένους φρονιμώτερον καὶ σεμνότερον ἀναζητῆσαι τὰς αἰτίας, ὧν χάριν ἐκράτησε τὸ ἔθος, καὶ μὴ προεξαναστάντας καταγινώσκειν μεγάλων ἐθνῶν εὐχέρειαν, λογιζομένους, ὡς εἰκός, τοσαύτας μυριάδας καθ’ ἑκάστην γενεὰν ἀποτέμνεσθαι, μετὰ χαλεπῶν ἀλγηδόνων ἀκρωτηριαζούσας τά τε ἑαυτῶν καὶ τῶν οἰκειοτάτων σώματα, πολλὰ δ’ εἶναι τὰ προτρέποντα τὴν εἰσήγησιν τῶν παλαιῶν διατηρεῖν καὶ ἐπιτελεῖν, τὰ δ’ ἀνωτάτω τέτταρα·", "st": "3"}, {"sp": "N", "t": "ἓν μὲν χαλεπῆς νόσου καὶ δυσιάτου, ποσθένης, ἀπαλλαγήν, ἣν ἄνθρακα καλοῦσιν, ἀπὸ τοῦ καίειν ἐντυφόμενον, ὡς οἶμαι, ταύτης τῆς προσηγορίας τυχόντα, ὅπερ εὐκολώτερον τοῖς ἀκροποσθίας ἔχουσιν ἐγγίνεται·", "st": "4"}, {"sp": "N", "t": "δεύτερον δὲ τὴν δι’ ὅλου τοῦ σώματος καθαριότητα πρὸς τὸ ἁρμόττον τάξει ἱερωμένῃ, παρὸ καὶ ξυρῶνται τὰ σώματα προσυπερβάλλοντες οἱ ἐν Αἰγύπτῳ τῶν ἱερέων·", "st": "5"}, {"sp": "N", "t": "ὑποσυλλέγεται γὰρ καὶ ὑποστέλλει καὶ θριξὶ καὶ ποσθίαις ἔνια τῶν ὀφειλόντων καθαίρεσθαι· τρίτον δὲ τὴν πρὸς καρδίαν ὁμοιότητα τοῦ περιτμηθέντος μέρους· πρὸς γὰρ γένεσιν ἄμφω παρεσκεύασται, τὸ μὲν ἐγκάρδιον πνεῦμα νοημάτων, τὸ δὲ γόνιμον ὄργανον ζῴων· ἐδικαίωσαν γὰρ οἱ πρῶτοι τῷ ἀφανεῖ καὶ κρείττονι, δι’ οὗ τὰ νοητὰ συνίσταται, τὸ ἐμφανὲς καὶ ὁρατόν, ᾧ τὰ αἰσθητὰ γεννᾶσθαι πέφυκεν, ἐξομοιῶσαι·", "st": "6"}, {"sp": "N", "t": "τέταρτον δὲ καὶ ἀναγκαιότατον τὴν πρὸς πολυγονίαν παρασκευήν· λέγεται γὰρ ὡς εὐοδεῖ τὸ σπέρμα μήτε σκιδνάμενον μήτε περιρρέον εἰς τοὺς τῆς ποσθίας κόλπους· ὅθεν καὶ τὰ περιτεμνόμενα τῶν ἐθνῶν πολυγονώτατα καὶ πολυανθρωπότατα εἶναι δοκεῖ.", "st": "7"}, {"sp": "N", "t": "Ταῦτα μὲν οὖν εἰς ἀκοὰς ἦλθε τὰς ἡμετέρας, ἀρχαιολογούμενα παρὰ θεσπεσίοις ἀνδράσιν, οἳ τὰ Μωυσέως οὐ παρέργως διηρεύνησαν. ἐγὼ δὲ πρὸς τοῖς εἰρημένοις καὶ σύμβολον ἡγοῦμαι τὴν περιτομὴν δυοῖν εἶναι τοῖν ἀναγκαιοτάτοιν·", "st": "8"}, {"sp": "N", "t": "ἑνὸς μὲν ἡδονῶν ἐκτομῆς, αἳ καταγοητεύουσι διάνοιαν· ἐπειδὴ γὰρ τὰ νικητήρια φέρεται τῶν ἐν ἡδοναῖς φίλτρων ἡ ἀνδρὸς πρὸς γυναῖκα συνουσία, τὸ ὑπηρετοῦν ταῖς τοιαύταις ὁμιλίαις ὄργανον ἀκρωτηριάζειν ἔδοξε τοῖς νομοθέταις, αἰνιττομένοις περιτομὴν περιττῆς ἐκτομὴν καὶ πλεοναζούσης ἡδονῆς, οὐ μιᾶς, ἀλλὰ διὰ μιᾶς τῆς βιαστικωτάτης καὶ τῶν ἄλλων ἁπασῶν·", "st": "9"}, {"sp": "N", "t": "ἑτέρου δὲ τοῦ γνῶναί τινα ἑαυτὸν καὶ τὴν βαρεῖαν νόσον, οἴησιν, ψυχῆς ἀπώσασθαι· ἔνιοι γὰρ ὡς ἀγαθοὶ ζῳοπλάσται ζῴων τὸ κάλλιστον, ἄνθρωπον, ηὔχησαν δύνασθαι δημιουργεῖν καὶ φυσηθέντες ὑπ’ ἀλαζονείας ἑαυτοὺς ἐξεθείωσαν, τὸν ὡς ἀληθῶς αἴτιον γενέσεως ὄντα θεὸν παρακαλυψάμενοι, καίτοι γε ἐκ τῶν συνήθων ἐπανορθώσασθαι τὴν ἀπάτην δυνάμενοι·", "st": "10"}, {"sp": "N", "t": "πολλοὶ μὲν γὰρ παρ’ αὐτοῖς εἰσιν ἄνδρες ἄγονοι, πολλαὶ δὲ στεῖραι γυναῖκες, ὧν ἀτελεῖς αἱ ὁμιλίαι καταγηρασάντων ἐν ἀπαιδίᾳ. πονηρὰν οὖν δόξαν ἐκτμητέον τῆς διανοίας καὶ τὰς ἄλλας ὅσαι μὴ φιλόθεοι.", "st": "11"}, {"sp": "N", "t": "τούτων μὲν δὴ πέρι τοσαῦτα· τρεπτέον δ’ ἐπὶ τοὺς κατὰ μέρος ἤδη νόμους καὶ πρώτους, ἀφ’ ὧν ἄρχεσθαι καλόν, τοὺς περὶ μοναρχίας ὁρισθέντας.", "st": "12"}, {"sp": "N", "t": "Τινὲς ἥλιον καὶ σελήνην καὶ τοὺς ἄλλους ἀστέρας ὑπέλαβον εἶναι θεοὺς αὐτοκράτορας, οἷς τὰς τῶν γινομένων ἁπάντων αἰτίας ἀνέθεσαν. Μωυσεῖ δ’ ὁ κόσμος ἔδοξεν εἶναι καὶ γενητὸς καὶ καθάπερ πόλις ἡ μεγίστη, ἄρχοντας ἔχουσα καὶ ὑπηκόους, ἄρχοντας μὲν τοὺς ἐν οὐρανῷ πάντας ὅσοι πλάνητες καὶ ἀπλανεῖς ἀστέρες, ὑπηκόους δὲ τὰς μετὰ σελήνην ἐν ἀέρι καὶ περιγείους φύσεις·", "st": "13"}, {"sp": "N", "t": "τοὺς δὲ λεχθέντας ἄρχοντας οὐκ αὐτεξουσίους, ἀλλ’ ἑνὸς τοῦ πάντων πατρὸς ὑπάρχους, οὗ μιμουμένους τὴν ἐπιστασίαν κατορθοῦν πρυτανεύοντος κατὰ δίκην καὶ νόμον ἕκαστον τῶν γεγονότων· τοὺς δὲ μὴ βλέποντας τὸν ἐπιβεβηκότα ἡνίοχον τοῖς ὑπεζευγμένοις ὡς αὐτουργοῖς τῶν ἐν τῷ κόσμῳ γινομένων ἀνάψαι τὰς αἰτίας.", "st": "14"}, {"sp": "N", "t": "ὧν τὴν ἄγνοιαν ὁ ἱερώτατος νομοθέτης εἰς ἐπιστήμην μεθαρμόζεται λέγων ὧδε· “μὴ ἰδὼν τὸν ἥλιον καὶ τὴν σελήνην καὶ τοὺς ἀστέρας καὶ πάντα τὸν κόσμον τοῦ οὐρανοῦ πλανηθεὶς προσκυνήσῃς αὐτοῖς”. εὐθυβόλως πάνυ καὶ καλῶς πλάνον εἶπε τὴν τῶν εἰρημένων ὡς θεῶν ἀποδοχήν.", "st": "15"}, {"sp": "N", "t": "οἱ γὰρ ἰδόντες ἡλίου μὲν προσόδοις καὶ ἀναχωρήσεσι τὰς ἐτησίους ὥρας συνισταμένας, ἐν αἷς αἱ ζῴων καὶ φυτῶν καὶ καρπῶν γενέσεις ὡρισμέναις χρόνων περιόδοις τελεσφοροῦνται, σελήνην δ’ ὑπηρέτιν καὶ διάδοχον ἡλίου νύκτωρ τὴν ἐπιμέλειαν καὶ προστασίαν ἀνειληφυῖαν ὧν μεθ’ ἡμέραν ἥλιος, καὶ τοὺς ἄλλους ἀστέρας κατὰ τὴν πρὸς τὰ ἐπίγεια συμπάθειαν μυρία τῶν ἐπὶ διαμονῇ τοῦ παντὸς ἐνεργοῦντάς τε καὶ δρῶντας, πλάνον ἐπλανήθησαν ἀνήνυτον μόνους εἶναι τούτους θεοὺς ὑποτοπήσαντες.", "st": "16"}, {"sp": "N", "t": "εἰ δ’ ἐσπούδασαν διὰ τῆς ἀπλανοῦς βαδίζειν ὁδοῦ, κἂν εὐθὺς ἔγνωσαν ὅτι, καθάπερ αἴσθησις ὑποδιάκονος νοῦ γέγονε, τὸν αὐτὸν τρόπον καὶ οἱ αἰσθητοὶ πάντες ὑπηρέται τοῦ νοητοῦ κατέστησαν, ἀγαπήσαντες εἰ δευτερείων ἐφίξονται.", "st": "17"}, {"sp": "N", "t": "παγγέλοιον γὰρ οἴεσθαι, ὅτι ὁ μὲν νοῦς ὁ ἐν ἡμῖν βραχύτατος ὢν καὶ ἀόρατος ἡγεμὼν τῶν αἰσθητικῶν ὀργάνων ἐστίν, ὁ δὲ τοῦ παντὸς ὁ μέγιστος καὶ τελειότατος οὐχὶ βασιλεὺς βασιλέων εἶναι πέφυκε, βλεπομένων οὐ βλεπόμενος.", "st": "18"}, {"sp": "N", "t": "πάντας οὖν τοὺς κατ’ οὐρανὸν οὓς αἴσθησις ἐπισκοπεῖ θεοὺς οὐκ αὐτοκρατεῖς νομιστέον, τὴν ὑπάρχων τάξιν εἰληφότας, ὑπευθύνους μὲν φύσει γεγονότας, ἕνεκα δ’ ἀρετῆς εὐθύνας οὐχ ὑφέξοντας.", "st": "19"}, {"sp": "N", "t": "ὥσθ’ ὑπερβάντες τῷ λογισμῷ πᾶσαν τὴν ὁρατὴν οὐσίαν ἐπὶ τὴν τοῦ ἀειδοῦς καὶ ἀοράτου καὶ μόνῃ διανοίᾳ καταληπτοῦ τιμὴν ἴωμεν, ὃς οὐ μόνον θεὸς θεῶν ἐστι νοητῶν τε καὶ αἰσθητῶν ἀλλὰ καὶ πάντων δημιουργός. ἐὰν δέ τις τὴν τοῦ ἀιδίου καὶ ποιητοῦ θεραπείαν ἄλλῳ προσνέμῃ νεωτέρῳ καὶ γενητῷ, φρενοβλαβὴς ἀναγεγράφθω καὶ ἔνοχος ἀσεβείᾳ τῇ μεγίστῃ.", "st": "20"}, {"sp": "N", "t": "Εἰσὶ δέ τινες οἳ χρυσὸν καὶ ἄργυρον ἀνδριαντοποιοῖς ὡς θεοπλαστεῖν ἱκανοῖς παρέδοσαν· οἱ δὲ λαβόντες ἀργὴν ὕλην θνητῷ παραδείγματι προσχρησάμενοι, τὸ παραλογώτατον, θεοὺς ὅσα τῷ δοκεῖν ἐμόρφωσαν· καὶ νεὼς κατασκευάσαντες καὶ ἱδρυσάμενοι βωμοὺς ἐδείμαντο θυσίαις τε καὶ πομπαῖς καὶ ταῖς ἄλλαις ἱερουργίαις τε καὶ ἁγιστείαις ἐπιμελῶς πάνυ καὶ πεφροντισμένως γεραίρουσιν, ἱερέων τε καὶ ἱερειῶν τὸν περὶ ταῦτα τῦφον ὡς ἔνι μάλιστα σεμνοποιούντων.", "st": "21"}, {"sp": "N", "t": "οἷς ὁ τῶν ὅλων πατὴρ προαγορεύει λέγων· “οὐ ποιήσετε μετ’ ἐμοῦ θεοὺς ἀργυροῦς καὶ χρυσοῦς”, μόνον οὐκ ἄντικρυς ἀναδιδάσκων, ὅτι οὐδ’ ἐξ ἑτέρας ὕλης χειρόκμητον οὐδὲν τὸ παράπαν θεοπλαστήσετε διακωλυθέντες ἐκ τῶν ἀρίστων· ἄργυρος γὰρ καὶ χρυσὸς τὰ πρωτεῖα τῶν ἐν ὕλαις φέρονται.", "st": "22"}, {"sp": "N", "t": "δίχα δὲ τῆς ῥητῆς ἀπαγορεύσεως καὶ ἕτερον αἰνίττεσθαί μοι δοκεῖ τῶν πρὸς ἠθοποιΐαν μάλιστα συντεινόντων, διελέγχων οὐ μετρίως τοὺς φιλοχρημάτους, οἳ πανταχόθεν μὲν ἀργύριον καὶ χρυσίον ἐκπορίζουσι, τὸ δὲ πορισθὲν ὡς ἄγαλμα θεῖον ἐν ἀδύτοις θησαυροφυλακοῦσιν, ἀγαθῶν αἴτιον καὶ τῆς συμπάσης εὐδαιμονίας τοῦτ’ εἶναι νομίζοντες.", "st": "23"}, {"sp": "N", "t": "καὶ ὅσοι μέντοι τῶν ἀπόρων κεκράτηνται χαλεπῇ νόσῳ, φιλαργυρίᾳ, οὐκ ἔχοντες ἴδιον πλοῦτον, ὃν θεραπείας ἀξιώσουσι, τὸν τῶν πλησίον τεθηπότες καὶ προσκυνοῦντες ἕωθεν εἰς τὰς τῶν περιουσιαζόντων οἰκίας ἀφικνοῦνται καθάπερ εἰς ἱερὰ μέγιστα, προσευξόμενοι καὶ τἀγαθὰ παρὰ τῶν δεσποτῶν ὡς θεῶν αἰτησόμενοι.", "st": "24"}, {"sp": "N", "t": "πρὸς οὓς καὶ ἐν ἑτέροις φησίν· “οὐκ ἐπακολουθήσετε εἰδώλοις καὶ θεοὺς χωνευτοὺς οὐ ποιήσετε”, διὰ συμβόλων ἀναδιδάσκων, ὅτι πλούτῳ τιμὰς ἰσοθέους ἀπονέμειν οὐ προσήκει· πλούτου γὰρ αἱ περιβόητοι ὗλαι χρυσὸς καὶ ἄργυρος εἶναι πεφύκασιν, αἷς ἀκολουθοῦσιν οἱ πολλοὶ τὰ τοῦ λεγομένου τυφλοῦ πλούτου μόνα ἢ μάλιστα εὐδαιμονίας αἴτια νομίζοντες.", "st": "25"}, {"sp": "N", "t": "τάδ’ ἐστὶν ἅ φησιν “εἴδωλα”, σκιαῖς ἐοικότα καὶ φάσμασιν, οὐδενὸς ἠρτημένα ἰσχυροῦ καὶ βεβαίου· φέρεται γὰρ πνεύματος τρόπον ἀστάτου τροπὰς καὶ μεταβολὰς παντοίας ἐνδεχόμενα. σημεῖον δ’ ἐστὶ τούτων ἐναργές· μὴ προλαβόντων ἐξαπιναίως ἔστιν ὅτε προσέπτη, παγίως ἐνειλῆφθαι νομιζόντων πάλιν ἀπεπήδησε, καὶ ὅτε μέντοι πάρεστι, καθάπερ τὰ διὰ τῶν κατόπτρων εἴδωλα φαντάζεται τὴν αἴσθησιν ἀπατῶντα καὶ καταγοητεύοντα καὶ ὡς ἂν ὑφεστηκότα τὰ μὴ ὑπομένοντα.", "st": "26"}, {"sp": "N", "t": "καὶ τί δεῖ τὸν ἀνθρώπινον πλοῦτον ἢ τῦφον, ὃν ἀναζωγραφοῦσιν αἱ κεναὶ δόξαι, δηλοῦν ὡς ἔστιν ἀβέβαιος; ἤδη γάρ τινες καὶ τὰ ἄλλα πάντα ζῷα καὶ φυτά, ὧν γένεσίς ἐστι καὶ φθορά, συνεχῶς μὲν καὶ ἀπαύστως φασὶ ῥεῖσθαι, τῆς δ’ ἀπορροίας ἀδηλοτέραν αἴσθησιν εἶναι, ἀεὶ νικώσης τῆς περὶ τὴν ῥύσιν ὀξύτητος τὴν δι’ ὄψεως ἀκριβῆ προσβολήν.", "st": "27"}, {"sp": "N", "t": "Ἀλλ’ οὐ μόνον πλοῦτος καὶ δόξα καὶ τὰ τοιαῦτα εἴδωλα καὶ ἀμενηναὶ σκιαί, ἀλλὰ καὶ πάντες, οὓς οἱ μυθογράφοι διαπλάσαντες ἐξετύφωσαν ἐπιτειχίσαντες τὰς ψευδεῖς δόξας κατὰ τῆς ἀληθείας, θεοὺς καινοὺς ὥσπερ ἀπὸ μηχανῆς εἰσαγαγόντες ἕνεκα τοῦ τὸν ἀίδιον καὶ ὄντα ὄντως θεὸν λήθῃ παραδοθῆναι. πρὸς δὲ τὸ εὐπαράγωγον μέλεσι καὶ ῥυθμοῖς καὶ μέτροις ἐνηρμόσαντο τὸ ψεῦδος, νομίζοντες ῥᾳδίως καταγοητεύσειν τοὺς ἐντυγχάνοντας.", "st": "28"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ πλαστικὴν καὶ ζωγραφίαν συνεργοὺς τῆς ἀπάτης προσπαρέλαβον, ἵνα χρωμάτων καὶ σχημάτων καὶ ποιοτήτων εὖ δεδημιουργημέναις ἰδέαις ὑπαγάγωνται τοὺς ὁρῶντας καὶ τὰς ἡγεμονίδας αἰσθήσεις ὄψιν καὶ ἀκοὴν δελεάσαντες, τὴν μὲν ἀψύχοις εὐμορφίαις, τὴν δ’ εὐφωνίᾳ ποιητικῇ, συναρπάσωσι τὴν ψυχὴν ἀβέβαιον καὶ ἀνίδρυτον αὐτὴν ἀπεργασάμενοι.", "st": "29"}, {"sp": "N", "t": "διὰ τοῦτ’ ἐπιστάμενος ἐπὶ μέγα δυνάμεως προεληλυθότα τὸν τῦφον καὶ δορυφορούμενον ὑπὸ τοῦ πλείστου γένους ἀνθρώπων οὐκ ἐξ ἀνάγκης ἀλλ’ ἑκουσίοις γνώμαις, εὐλαβηθεὶς μή ποτε καὶ οἱ ζηλωταὶ τῆς ἀδεκάστου καὶ ἀληθοῦς εὐσεβείας καθάπερ ὑπὸ χειμάρρου παρασυρῶσιν, ἐνσφραγίζεται βαθεῖς τύπους ταῖς διανοίαις ἐγχαράττων ὁσιότητος, ὑπὲρ τοῦ μὴ συγχυθέντας ἢ ἐπιλεανθέντας ἀμαυρωθῆναί ποτε χρόνῳ, καὶ συνεχῶς ἐπᾴδει ποτὲ μὲν λέγων ὅτι θεὸς εἷς ἐστι καὶ κτίστης καὶ ποιητὴς τῶν ὅλων, ποτὲ δὲ ὅτι κύριος τῶν γεγονότων, ἐπειδὴ τὸ βέβαιον καὶ πάγιον καὶ τὸ κῦρος ὡς ἀληθῶς περὶ αὐτὸν μόνον πέφυκε.", "st": "30"}, {"sp": "N", "t": "λέλεκται δ’ ὅτι “οἱ προσκείμενοι τῷ ὄντι θεῷ ζῶσι πάντες”. ἆρ’ οὐχ οὗτός ἐστιν ὁ τρισμακάριος καὶ τρισευδαίμων βίος, ἀγαπητικῶς ἔχεσθαι τῆς θεραπείας τοῦ πρεσβυτάτου πάντων αἰτίου καὶ μὴ τοὺς ὑποδιακόνους καὶ πυλωροὺς πρὸ τοῦ βασιλέως θεραπεύειν ἀξιοῦν; ἀθάνατος ἥδε ἡ ζωὴ καὶ μακραίων ἐν ταῖς τῆς φύσεως στήλαις ἀναγέγραπται· ταυτὶ δὲ τὰ γράμματα τῷ κόσμῳ συνδιαιωνίζειν ἀναγκαῖον.", "st": "31"}, {"sp": "N", "t": "Δυστόπαστος μὲν οὖν καὶ δυσκατάληπτος ὁ πατὴρ καὶ ἡγεμὼν τῶν συμπάντων ἐστίν, ἀλλ’ οὐ διὰ τοῦτ’ ἀποκνητέον τὴν ζήτησιν αὐτοῦ. δύο δ’ ἐν ταῖς περὶ θεοῦ ζητήσεσι τὰ ἀνωτάτω ταῦτ’ ἐπαπορεῖ ἡ διάνοια τοῦ φιλοσοφοῦντος ἀνόθως· ἓν μὲν εἰ ἔστι τὸ θεῖον, ἕνεκα τῶν ἐπιτηδευσάντων ἀθεότητα, κακιῶν τὴν μεγίστην· ἕτερον δὲ τὸ τί ἐστι κατὰ τὴν οὐσίαν. τὸ μὲν οὖν πρότερον οὐ πολὺς πόνος ἰδεῖν, τὸ δὲ δεύτερον οὐ χαλεπὸν μόνον ἀλλὰ καὶ ἴσως ἀδύνατον. ἐπισκεπτέον δ’ ἑκάτερον.", "st": "32"}, {"sp": "N", "t": "ἀεὶ τοίνυν γνωρίσματα τῶν δημιουργῶν πέφυκέ πως εἶναι τὰ δημιουργηθέντα· τίς γὰρ ἀνδριάντας ἢ γραφὰς θεασάμενος οὐκ εὐθὺς ἐνενόησεν ἀνδριαντοποιὸν ἢ ζωγράφον; τίς δὲ ἐσθῆτας ἢ ναῦς ἢ οἰκίας ἰδὼν οὐκ ἔννοιαν ἔλαβεν ὑφάντου καὶ ναυπηγοῦ καὶ οἰκοδόμου; παρελθὼν δέ τις εἰς πόλιν εὔνομον, ἐν ᾗ τὰ τῆς πολιτείας σφόδρα καλῶς διακεκόσμηται, τί ἕτερον ὑπολήψεται ἢ ὅτι ἐπιστατεῖται ἥδε ἡ πόλις ὑπ’ ἀρχόντων ἀγαθῶν;", "st": "33"}, {"sp": "N", "t": "τὸν οὖν ἀφικόμενον εἰς τὴν ὡς ἀληθῶς μεγαλόπολιν, τόνδε τὸν κόσμον, καὶ θεασάμενον τὴν ὀρεινὴν καὶ πεδιάδα βρίθουσαν ζῴων καὶ φυτῶν καὶ ποταμῶν αὐθιγενῶν καὶ χειμάρρων φορὰς καὶ πελαγῶν ἀναχύσεις καὶ εὐκρασίας ἀέρος καὶ τῶν ἐτησίων ὡρῶν τροπάς, εἶτα ἥλιον καὶ σελήνην, τοὺς ἡμέρας καὶ νυκτὸς ἡγεμόνας, καὶ τὰς τῶν ἄλλων πλανήτων τε καὶ ἀπλανῶν καὶ τοῦ σύμπαντος οὐρανοῦ περιπολήσεις καὶ χορείας, οὐκ εἰκότως, μᾶλλον δὲ ἀναγκαίως, ἔννοιαν λήψεσθαι δεῖ τοῦ ποιητοῦ καὶ πατρὸς καὶ προσέτι ἡγεμόνος;", "st": "34"}, {"sp": "N", "t": "οὐδὲν γὰρ τῶν τεχνικῶν ἔργων ἀπαυτοματίζεται· τεχνικώτατον δὲ καὶ ἐπιστημονικώτατον ὅδε ὁ κόσμος, ὡς ὑπό τινος τὴν ἐπιστήμην ἀγαθοῦ καὶ τελειοτάτου πάντως δεδημιουργῆσθαι. τοῦτον τὸν τρόπον ἔννοιαν ἐλάβομεν ὑπάρξεως θεοῦ.", "st": "35"}, {"sp": "N", "t": "Τὴν δ’ οὐσίαν, εἰ καὶ δυσθήρατον καὶ δυσκατάληπτον εἶναι συμβέβηκεν, ὅμως καθ’ ὅσον ἐνδέχεται διερευνητέον. ἄμεινον γὰρ οὐδὲν τοῦ ζητεῖν τὸν ἀληθῆ θεόν, κἂν ἡ εὕρεσις αὐτοῦ διαφεύγῃ δύναμιν ἀνθρωπίνην, ἐπειδὴ καὶ ἡ περὶ τὸ βούλεσθαι μαθεῖν σπουδὴ καθ’ αὑτὴν ἀλέκτους ἡδονὰς καὶ εὐφροσύνας ἐργάζεται.", "st": "36"}, {"sp": "N", "t": "μάρτυρες δὲ οἱ μὴ χείλεσιν ἄκροις γευσάμενοι φιλοσοφίας, ἀλλὰ τῶν λόγων καὶ δογμάτων αὐτῆς ἐπὶ πλέον ἑστιαθέντες· τούτων γὰρ ὁ λογισμὸς ἀπὸ γῆς ἄνω μετέωρος ἀρθεὶς αἰθεροβατεῖ καὶ συμπεριπολῶν ἡλίῳ καὶ σελήνῃ καὶ τῷ σύμπαντι οὐρανῷ, τἀκεῖ πάντα γλιχόμενος ἰδεῖν, ἀμυδροτέραις χρῆται ταῖς προσβολαῖς, ἀκράτου καὶ πολλοῦ φέγγους ἐκχεομένου, ὡς τὸ τῆς ψυχῆς ὄμμα ταῖς μαρμαρυγαῖς σκοτοδινιᾶν.", "st": "37"}, {"sp": "N", "t": "ἀλλ’ οὐ διὰ τοῦτο προκαμὼν ἀπαγορεύει, γνώμῃ δ’ ἀηττήτῳ πρὸς τὴν ἐνδεχομένην θέαν ἵεται, καθάπερ ἐν ἄθλοις δευτερείων μεταποιούμενος, ἐπειδὴ τῶν πρώτων ἐσφάλη. φαντασίας δ’ ἀληθοῦς δεύτερά ἐστιν εἰκασία καὶ στοχασμὸς καὶ ὅσα εἰς τὴν τῶν εὐλόγων καὶ πιθανῶν ἰδέαν ἀνάγεται.", "st": "38"}, {"sp": "N", "t": "καθάπερ οὖν οἷός ἐστι τῶν ἀστέρων ἕκαστος κατὰ τὴν οὐσίαν εἱλικρινῶς οὔτ’ εἰδότες οὔτε δυνάμενοι σαφῶς διαγνῶναι ζητεῖν ὅμως προθυμούμεθα, τερπόμενοι τοῖς εἰκόσι λόγοις ἕνεκα τοῦ φύσει φιλομαθοῦς, τὸν αὐτὸν τρόπον,", "st": "39"}, {"sp": "N", "t": "εἰ καὶ τῆς κατὰ τὸν ὄντως ὄντα θεὸν ἐναργοῦς φαντασίας ἀμοιροῦμεν, ὀφείλομεν μὴ ἀπολείπεσθαι τῆς ζητήσεως αὐτοῦ, διὰ τὸ τὴν σκέψιν καὶ ἄνευ τῆς εὑρέσεως καθ’ αὑτὴν τριπόθητον εἶναι, ἐπεὶ καὶ τοὺς τοῦ σώματος ὀφθαλμοὺς οὐδεὶς αἰτιᾶται, παρόσον ἥλιον αὐτὸν ἰδεῖν ἀδυνατοῦντες τὴν φερομένην ἀπόρροιαν τῶν ἀκτίνων ἐπὶ γῆν ὁρῶσιν, ἡλιακῶν αὐγῶν ἔσχατον", "st": "40"}, {"sp": "N", "t": "φέγγος. εἰς ἅπερ ἀπιδὼν ὁ ἱεροφάντης καὶ θεοφιλέστατος Μωυσῆς ἱκετεύει τὸν θεὸν λέγων· “ἐμφάνισόν μοι σαυτόν”, μόνον οὐ κατασχεθεὶς καὶ ἐκβοῶν ἄντικρυς, ὅτι “τοῦ μὲν εἶναί σε καὶ ὑπάρχειν διδάσκαλος καὶ ὑφηγητής μοι γέγονεν ὅδε ὁ κόσμος, καὶ ὡς υἱὸς ἀναδιδάξας με περὶ τοῦ πατρὸς καὶ ὡς ἔργον περὶ τοῦ τεχνίτου· τίς δὲ κατὰ τὴν οὐσίαν τυγχάνεις ὢν διαγνῶναι ποθῶν οὐδένα τούτου τοῦ μαθήματος ὑφηγητὴν ἐν οὐδενὶ τῶν τοῦ παντὸς μερῶν ἀνευρίσκω.", "st": "41"}, {"sp": "N", "t": "διὸ δὴ δέομαι καὶ ποτνιῶμαι προσέσθαι τὴν ἱκεσίαν ἀνδρὸς ἱκέτου καὶ φιλοθέου καὶ μόνον σὲ θεραπεύειν ἀξιοῦντος· ὡς γὰρ τὸ φῶς ὑφ’ ἑτέρου μὴ γνωριζόμενον αὐτὸ ἑαυτοῦ γνώρισμά ἐστιν, οὕτως καὶ σὺ σεαυτὸν μόνος ἂν φῆναι δύναιο. διὸ συγγνώμης ἀξιῶ τυχεῖν, εἰ σπάνει τοῦ διδάξοντος ἐπὶ σὲ καταφυγεῖν ἐθάρρησα περὶ σοῦ σπεύδων μαθεῖν”.", "st": "42"}, {"sp": "N", "t": "ὁ δὲ “τὴν μὲν προθυμίαν” φησίν “ἐπαινετὴν οὖσαν ἀποδέχομαι, τὸ δ’ αἴτημα οὐδενὶ τῶν εἰς γένεσιν ἡκόντων ἐφαρμόζει. χαρίζομαι δ’ ἐγὼ τὰ οἰκεῖα τῷ ληψομένῳ· οὐ γὰρ ὅσα μοι δοῦναι ῥᾴδιον καὶ ἀνθρώπῳ λαβεῖν δυνατόν· ὅθεν ὀρέγω τῷ χάριτος ἀξίῳ πάσας ὅσας ἂν οἷός τε ᾖ δέξασθαι δωρεάς.", "st": "43"}, {"sp": "N", "t": "τὴν δ’ ἐμὴν κατάληψιν οὐχ οἷον ἀνθρώπου φύσις ἀλλ’ οὐδ’ ὁ σύμπας οὐρανός τε καὶ κόσμος δυνήσεται χωρῆσαι. γνῶθι δὴ σαυτὸν καὶ μὴ συνεκφέρου ταῖς ὑπὲρ δύναμιν ὁρμαῖς καὶ ἐπιθυμίαις, μηδέ σε τῶν ἀνεφίκτων ἔρως αἰρέτω καὶ μετεωριζέτω· τῶν γὰρ ἐφικτῶν οὐδενὸς ἀμοιρήσεις”.", "st": "44"}, {"sp": "N", "t": "ταῦτα ἀκούσας ἐπὶ δευτέραν ἱκεσίαν ἦλθε καί φησι· “πέπεισμαι μὲν ταῖς σαῖς ὑφηγήσεσιν, ὅτι οὐκ ἂν ἴσχυσα δέξασθαι τὸ τῆς σῆς φαντασίας ἐναργὲς εἶδος. ἱκετεύω δὲ τὴν γοῦν περὶ σὲ δόξαν θεάσασθαι· δόξαν δὲ σὴν εἶναι νομίζω τὰς περὶ σὲ δορυφορούσας δυνάμεις, ὧν διαφεύγουσα ἡ κατάληψις ἄχρι τοῦ παρόντος οὐ μικρὸν ἐνεργάζεταί μοι πόθον τῆς διαγνώσεως”.", "st": "45"}, {"sp": "N", "t": "ὁ δὲ ἀμείβεται καί φησιν· “ἃς ἐπιζητεῖς δυνάμεις εἰσὶν ἀόρατοι καὶ νοηταὶ πάντως ἐμοῦ τοῦ ἀοράτου καὶ νοητοῦ· λέγω δὲ νοητὰς οὐχὶ τὰς ἤδη ὑπὸ νοῦ καταλαμβανομένας, ἀλλ’ ὅτι εἰ καταλαμβάνεσθαι οἷαί τε εἶεν, οὐκ ἂν αἴσθησις αὐτὰς ἀλλ’ ἀκραιφνέστατος νοῦς καταλαμβάνοι.", "st": "46"}, {"sp": "N", "t": "πεφυκυῖαι δ’ ἀκατάληπτοι κατὰ τὴν οὐσίαν ὅμως παραφαίνουσιν ἐκμαγεῖόν τι καὶ ἀπεικόνισμα τῆς ἑαυτῶν ἐνεργείας· οἷαι αἱ παρ’ ὑμῖν σφραγῖδες — ὅταν γὰρ προσενεχθῇ κηρὸς ἤ τις ὁμοιότροπος ὕλη, μυρίους ὅσους τύπους ἐναπομάττονται, μηδὲν ἀκρωτηριασθεῖσαι μέρος, ἀλλ’ ἐν ὁμοίῳ μένουσαι —, τοιαύτας ὑποληπτέον καὶ τὰς περὶ ἐμὲ δυνάμεις περιποιούσας ἀποίοις ποιότητας καὶ μορφὰς ἀμόρφοις καὶ μηδὲν τῆς ἀιδίου φύσεως μήτ’ ἀλλαττομένας μήτε μειουμένας.", "st": "47"}, {"sp": "N", "t": "ὀνομάζουσι δ’ αὐτὰς οὐκ ἀπὸ σκοποῦ τινες τῶν παρ’ ὑμῖν ἰδέας, ἐπειδὴ ἕκαστα τῶν ὄντων εἰδοποιοῦσι τὰ ἄτακτα τάττουσαι καὶ τὰ ἄπειρα καὶ ἀόριστα καὶ ἀσχημάτιστα περατοῦσαι καὶ περιορίζουσαι καὶ σχηματίζουσαι καὶ συνόλως τὸ χεῖρον εἰς τὸ ἄμεινον μεθαρμοζόμεναι.", "st": "48"}, {"sp": "N", "t": "μήτ’ οὖν ἐμὲ μήτε τινὰ τῶν ἐμῶν δυνάμεων κατὰ τὴν οὐσίαν ἐλπίσῃς ποτὲ δυνήσεσθαι καταλαβεῖν. τῶν δ’ ἐφικτῶν, ὡς εἶπον, ἑτοίμως καὶ προθύμως μεταδίδωμι· ταῦτα δ’ ἐστὶν ἐπὶ τὴν τοῦ κόσμου καὶ τῶν ἐν αὐτῷ καλέσαι θέαν, ἣν οὐ σώματος ὀφθαλμοῖς ἀλλὰ τοῖς διανοίας ἀκοιμήτοις ὄμμασι συμβαίνει καταλαμβάνεσθαι.", "st": "49"}, {"sp": "N", "t": "μόνον ὁ σοφίας ἵμερος συνεχὴς ἔστω καὶ πυκνός, ἣ δογμάτων ἀοιδίμων καὶ περικαλλεστάτων ἀναπίμπλησι τοὺς φοιτητὰς καὶ γνωρίμους αὐτῆς”. ταῦτα ἀκούσας οὐκ ἐπαύσατο τῆς ἐπιθυμίας, ἀλλ’ ἔτι τὸν ἐπὶ τοῖς ἀοράτοις πόθον ἐζωπύρει.", "st": "50"}, {"sp": "N", "t": "Καὶ πάντας τοὺς ὁμοιοτρόπους εἴτ’ οὖν φύντας ἐξ ἀρχῆς εἴτε καὶ ἐκ τοῦ μεταβάλλεσθαι πρὸς τὴν ἀμείνω τάξιν κρείττους γεγονότας ἀποδέχεται, τοὺς μὲν ὅτι τὴν εὐγένειαν οὐ κατέλυσαν, τοὺς δ’ ὅτι πρὸς εὐσέβειαν ἠξίωσαν μεθορμίσασθαι — τούτους δὲ καλεῖ προσηλύτους ἀπὸ τοῦ προσεληλυθέναι καινῇ καὶ φιλοθέῳ πολιτείᾳ —, οἳ μυθικῶν μὲν ἀλογοῦσι πλασμάτων, περιέχονται δὲ ἀκραιφνοῦς ἀληθείας.", "st": "51"}, {"sp": "N", "t": "ἰσοτιμίαν γοῦν ἅπασιν ἐπηλύταις διδοὺς καὶ χαρισάμενος ὅσα καὶ τοῖς αὐτόχθοσι παραινεῖ τοῖς εὐπατρίδαις, μὴ μόνον αὐτοὺς τιμαῖς γεραίρειν ἀλλὰ καὶ ἐξαιρέτῳ φιλίᾳ καὶ εὐνοίᾳ περιττῇ. καὶ μήποτ’ εἰκότως· “ἀπολελοιπότες” φησί “πατρίδα καὶ φίλους καὶ συγγενεῖς δι’ ἀρετὴν καὶ ὁσιότητα μὴ ἀμοιρείτωσαν ἑτέρων πόλεων καὶ οἰκείων καὶ φίλων, ἀλλ’ ἔστωσαν ἔφεδροι καταφυγαὶ τοῖς πρὸς εὐσέβειαν αὐτομολοῦσι· φίλτρον γὰρ ἀνυσιμώτατον καὶ δεσμὸς ἄλυτος εὐνοίας ἑνωτικῆς ἡ τοῦ ἑνὸς θεοῦ τιμή”.", "st": "52"}, {"sp": "N", "t": "προστάττει δὲ μή, παρόσον αὐτοῖς ἰσονομίαν καὶ ἰσοτέλειαν [ἐπηλύταις] παρέχει κατεγνωκόσι τοῦ πατρῴου καὶ προγονικοῦ τύφου, στομαργίᾳ χρήσασθαι καὶ ἀχαλίνῳ γλώσσῃ βλασφημοῦντας οὓς ἕτεροι νομίζουσι θεούς, ἵνα μὴ κἀκεῖνοι διακινηθέντες ἃ μὴ θέμις φθέγξωνται κατὰ τοῦ ὄντως ὄντος· ἀγνοίᾳ γὰρ τῆς διαφορᾶς, ἅτε τὸ ψεῦδος ὡς ἀληθὲς προμαθόντες ἐκ παίδων καὶ σύντροφον ἔχοντες, ἐξαμαρτήσονται.", "st": "53"}, {"sp": "N", "t": "Τῶν δ’ ἀπὸ τοῦ ἔθνους εἴ τινες καθυφίενται τὴν τοῦ ἑνὸς τιμήν, ὡς λιπόντες τὴν ἀναγκαιοτάτην τάξιν εὐσεβείας καὶ ὁσιότητος ταῖς ἀνωτάτω τιμωρίαις ὀφείλουσι κολάζεσθαι, σκότος αἱρούμενοι πρὸ αὐγοειδεστάτου φωτὸς καὶ τυφλὴν ἀπεργαζόμενοι διάνοιαν ὀξὺ καθορᾶν δυναμένην.", "st": "54"}, {"sp": "N", "t": "καὶ ἐπιτετράφθαι δὲ καλὸν ἅπασι τοῖς ζῆλον ἔχουσιν ἀρετῆς ἐκ χειρὸς ἀναπράττειν ἀνυπερθέτως τὰς τιμωρίας, μήτ’ εἰς δικαστήριον μήτ’ εἰς βουλευτήριον μήτε συνόλως ἐπ’ ἀρχὴν ἄγοντας, ἀλλὰ τῷ παραστάντι μισοπονήρῳ πάθει καὶ φιλοθέῳ καταχρῆσθαι πρὸς τὰς τῶν ἀσεβῶν ἀπαραιτήτους κολάσεις, νομίσαντας αὐτοὺς ὑπὸ τοῦ καιροῦ τὰ πάντα γεγενῆσθαι, βουλευτάς, δικαστάς, στρατηγούς, ἐκκλησιαστάς, κατηγόρους, μάρτυρας, νόμους, δῆμον, ἵνα μηδενὸς ὄντος ἐμποδὼν ἄφοβοι σὺν ἀδείᾳ πολλῇ προαγωνίζωνται", "st": "55"}, {"sp": "N", "t": "ὁσιότητος. ἀναγέγραπταί τις ἐν τοῖς νόμοις τὸ καλὸν τοῦτο τόλμημα τολμήσας. ἐπειδὴ γὰρ ἐθεάσατό τινας ἀλλοφύλοις συνόντας γυναιξὶ καὶ ἕνεκα τῶν πρὸς αὐτὰς φίλτρων ἀλογοῦντας μὲν τῶν πατρίων, τελουμένους δὲ τὰς μυθικὰς τελετάς, ἕνα τὸν ἔξαρχον καὶ ἡγεμόνα τῆς παρανομίας καταθαρροῦντα ἤδη παρεπιδείκνυσθαι δημοσίᾳ τὸ ἀνοσιούργημα καὶ θυσίας ἀγάλμασι καὶ ξοάνοις ἀθύτους φανερῶς ἐπιτελοῦντα παρόντος ἅπαντος τοῦ πλήθους ἐνθουσιῶν, ἀνείρξας τοὺς παρ’ ἑκάτερα ἐπὶ τὴν θέαν ἠθροισμένους, οὐδὲν εὐλαβηθεὶς ἀναιρεῖ σὺν τῇ γυναικί, τὸν μὲν ἕνεκα τῆς εὐμαθείας τῶν ἃ λυσιτελὲς ἀπομανθάνειν, τὴν δ’ ὅτι διδάσκαλος κακῶν ἐγένετο.", "st": "56"}, {"sp": "N", "t": "τουτὶ τὸ ἔργον ἐξαίφνης δρασθὲν ἐν θερμῷ παραστήματι μυρίους ἐνουθέτησε τῶν ἐπὶ ταῦτα παρασκευαζομένων. ἐπαινέσας οὖν ὁ θεὸς τὴν ἀριστείαν αὐτοκελεύστῳ καὶ ἐθελουργῷ σπουδῇ γενομένην διτταῖς αὐτὸν ἀναστέφει δωρεαῖς, εἰρήνῃ καὶ ἱερωσύνῃ, τῇ μὲν κρίνας ἄξιον ἀπολέμου μεταποιεῖσθαι βίου τὸν ἀράμενον τοὺς ὑπὲρ θεοῦ τιμῆς ἀγῶνας, τῇ δ’ ὅτι γέρας οἰκειότατον εὐσεβοῦς ἀνδρὸς ἱερωσύνη θεραπείαν ἐπαγγελλομένη τοῦ πατρός, ᾧ τὸ δουλεύειν οὐκ ἐλευθερίας μόνον ἀλλὰ καὶ βασιλείας ἄμεινον.", "st": "57"}, {"sp": "N", "t": "ἔνιοι δὲ τοσαύτῃ κέχρηνται μανίας ὑπερβολῇ, ὥστ’ οὐδ’ ἀναχώρησιν αὑτοῖς εἰς μετάνοιαν ἀπολείποντες ἵενται πρὸς δουλείαν τῶν χειροκμήτων, γράμμασιν αὐτὴν ὁμολογοῦντες, οὐκ ἐν χαρτιδίοις, ἀλλ’, ὡς ἐπὶ τῶν ἀνδραπόδων ἔθος, [ἀλλ’] ἐν τοῖς σώμασι καταστίζοντες αὐτὰ σιδήρῳ πεπυρωμένῳ πρὸς ἀνεξάλειπτον μονήν· οὐδὲ γὰρ χρόνῳ ταῦτα ἀμαυροῦται.", "st": "58"}, {"sp": "N", "t": "Τὴν δ’ ὁμοίαν προαίρεσιν ὁ ἱερώτατος Μωυσῆς καὶ ἐπὶ τῶν ἄλλων ἅπαξ ἁπάντων σῴζειν ἔοικεν ἀληθείας ἐραστὴς ὢν καὶ διδάσκαλος, ἣν καὶ πᾶσι τοῖς γνωρίμοις ἐγχαράττειν καὶ ἐνσφραγίζεσθαι ποθεῖ τὰς ψευδεῖς δόξας μακρὰν τῆς διανοίας αὐτῶν ἀποικίζων.", "st": "59"}, {"sp": "N", "t": "ἐπιστάμενος γοῦν τῷ πλάνῳ τῶν πολλῶν βίῳ συμπράττουσαν οὐ μετρίως εἰς ἀνοδίαν μαντικήν, οὐδενὶ τῶν εἰδῶν αὐτῆς ἐᾷ χρῆσθαι, πάντας δὲ τοὺς κολακεύοντας αὐτὴν ἐλαύνει τῆς ἰδίου πολιτείας, θύτας, καθαρτάς, οἰωνοσκόπους, τερατοσκόπους, ἐπᾴδοντας, κλῃδόσιν ἐπανέχοντας.", "st": "60"}, {"sp": "N", "t": "στοχασταὶ γὰρ πάντες οὗτοι πιθανῶν καὶ εἰκότων, ἄλλοτε ἄλλας ἀπὸ τῶν αὐτῶν φαντασίας λαμβάνοντες, διὰ τὸ μήτε τὰ ὑποκείμενα φύσιν ἔχειν πάγιον μήτε τὴν διάνοιαν ἀκριβῆ βάσανον περιπεποιῆσθαι, ᾗ βασανισθήσεται τὰ δόκιμα. παρασκευαὶ δὲ πάντα ταῦτ’ εἰσὶν ἀσεβείας· διὰ τί;", "st": "61"}, {"sp": "N", "t": "ὅτι ὁ προσέχων καὶ πειθόμενος αὐτοῖς ἀλογεῖ τοῦ πάντων αἰτίου μόνα ταῦθ’ ὑπολαμβάνων ἀγαθῶν εἶναι καὶ κακῶν αἴτια, καὶ οὐκ αἰσθάνεται τὰς τοῦ βίου φροντίδας ἐξάπτων ἀβεβαιοτάτων πεισμάτων, ὀρνίθων καὶ πτερῶν καὶ φορᾶς ἐν ἀέρι τῆς ὧδε κἀκεῖσε καὶ χαμαιζήλων ἑρπετῶν, ἃ τῶν φωλεῶν ἀνέρπει πρὸς ζήτησιν τροφῆς, ἔτι δὲ σπλάγχνων καὶ αἵματος καὶ νεκρῶν σωμάτων, ἃ στερόμενα ψυχῆς εὐθὺς ἐπισυμπίπτει καὶ συγχεῖται καὶ ἑτεροιούμενα τὰς οἰκείας φύσεις ἐξαλλάττει πρὸς τὴν χείρω μεταβολήν.", "st": "62"}, {"sp": "N", "t": "ἀξιοῖ γὰρ τὸν ἐγγραφόμενον τῇ κατὰ τοὺς νόμους πολιτείᾳ “τέλειον” εἶναι, μὴ ἐν οἷς οἱ πολλοὶ πεπαιδοτρίβηνται, μαντείαις καὶ κλῃδόσι καὶ πιθαναῖς εἰκασίαις, ἀλλ’ ἐν τοῖς πρὸς θεὸν οὐδὲν ἔχουσιν ἐπαμφοτερίζον ἢ ἀμφίβολον ἀλλ’ ἀνενδοίαστον καὶ γυμνὴν ἀλήθειαν.", "st": "63"}, {"sp": "N", "t": "ἐπεὶ δὲ πᾶσιν ἀνθρώποις ἔρως τῆς τῶν μελλόντων ἐπιστήμης ἐνίδρυται καὶ διὰ τὸν ἔρωτα τοῦτον ἐπὶ θυτικὴν καὶ τὰ ἄλλα εἴδη τρέπονται μαντικῆς, ὡς δι’ αὐτῶν τὸ σαφὲς ἀνευρήσοντες, τὰ δ’ ἀσαφείας γέμει πολλῆς καὶ ἐξ ἑαυτῶν ἀεὶ διελέγχεται, τούτοις μὲν σφόδρα εὐτόνως ἐπακολουθεῖν ἀπαγορεύει, φησὶ δ’ ὅτι, ἐὰν ἀκλινῶς εὐσεβῶσιν, οὐκ ἀμοιρήσουσι τῆς τῶν μελλόντων ἐπιγνώσεως,", "st": "64"}, {"sp": "N", "t": "ἀλλά τις ἐπιφανεὶς ἐξαπιναίως προφήτης θεοφόρητος θεσπιεῖ καὶ προφητεύσει, λέγων μὲν οἰκεῖον οὐδέν — οὐδὲ γάρ, εἰ λέγει, δύναται καταλαβεῖν ὅ γε κατεχόμενος ὄντως καὶ ἐνθουσιῶν —, ὅσα δ’ ἐνηχεῖται, διελεύσεται καθάπερ ὑποβάλλοντος ἑτέρου· ἑρμηνεῖς γάρ εἰσιν οἱ προφῆται θεοῦ καταχρωμένου τοῖς ἐκείνων ὀργάνοις πρὸς δήλωσιν ὧν ἂν ἐθελήσῃ. ταῦτα καὶ τὰ τούτοις παραπλήσια περὶ τῆς τοῦ ἑνὸς θεοῦ καὶ ὄντως ὄντος ἐννοίας ὑπειπών, ὃν χρὴ τρόπον ἀπονέμειν αὐτῷ τὰς τιμὰς ἑξῆς ὑπογράφει.", "st": "65"}, {"sp": "N", "t": "Τὸ μὲν ἀνωτάτω καὶ πρὸς ἀλήθειαν ἱερὸν θεοῦ νομίζειν τὸν σύμπαντα χρὴ κόσμον εἶναι, νεὼ μὲν ἔχοντα τὸ ἁγιώτατον τῆς τῶν ὄντων οὐσίας μέρος, οὐρανόν, ἀναθήματα δὲ τοὺς ἀστέρας, ἱερέας δὲ τοὺς ὑποδιακόνους αὐτοῦ τῶν δυνάμεων ἀγγέλους, ἀσωμάτους ψυχάς, οὐ κράματα ἐκ λογικῆς καὶ ἀλόγου φύσεως, οἵας τὰς ἡμετέρας εἶναι συμβέβηκεν, ἀλλ’ ἐκτετμημένας τὸ ἄλογον, ὅλας δι’ ὅλων νοεράς, λογισμοὺς ἀκραιφνεῖς, μονάδι ὁμοιουμένας.", "st": "66"}, {"sp": "N", "t": "τὸ δὲ χειρόκμητον· ἔδει γὰρ ὁρμὰς ἀνθρώπων μὴ ἀνακόψαι φορὰς τὰς εἰς εὐσέβειαν συντελούντων καὶ θυσίαις βουλομένων ἢ ἐπὶ τοῖς συμβαίνουσιν ἀγαθοῖς εὐχαριστεῖν ἢ ἐφ’ οἷς ἂν ἁμαρτάνωσι συγγνώμην καὶ παραίτησιν αἰτεῖσθαι. προὐνόησε δ’ ὡς οὔτε πολλαχόθι οὔτ’ ἐν ταὐτῷ πολλὰ κατασκευασθήσεται ἱερά, δικαιώσας, ἐπειδὴ εἷς ἐστιν ὁ θεός, καὶ ἱερὸν ἓν εἶναι μόνον.", "st": "67"}, {"sp": "N", "t": "εἶτα τοῖς βουλομένοις ἐν ταῖς οἰκίαις αὐτῶν ἱερουργεῖν οὐκ ἐφίησιν, ἀλλ’ ἀνισταμένους ἀπὸ περάτων γῆς εἰς τοῦτ’ ἀφικνεῖσθαι κελεύει, ἅμα καὶ τῶν τρόπων ἀναγκαιοτάτην λαμβάνων βάσανον· ὁ γὰρ μὴ μέλλων θύειν εὐαγῶς οὐκ ἂν ὑπομείναι ποτὲ πατρίδα καὶ φίλους καὶ συγγενεῖς ἀπολιπὼν ξενιτεύειν, ἀλλ’ ἔοικεν ὑπὸ δυνατωτέρας ὁλκῆς ἀγόμενος τῆς πρὸς εὐσέβειαν ὑπομένειν τῶν συνηθεστάτων καὶ φιλτάτων ὥσπερ τινῶν ἡνωμένων μερῶν ἀπαρτᾶσθαι.", "st": "68"}, {"sp": "N", "t": "καὶ τοῦδε σαφεστάτη πίστις τὰ γινόμενα· μυρίοι γὰρ ἀπὸ μυρίων ὅσων πόλεων, οἱ μὲν διὰ γῆς, οἱ δὲ διὰ θαλάττης, ἐξ ἀνατολῆς καὶ δύσεως καὶ ἄρκτου καὶ μεσημβρίας καθ’ ἑκάστην ἑορτὴν εἰς τὸ ἱερὸν καταίρουσιν οἷά τινα κοινὸν ὑπόδρομον καὶ καταγωγὴν ἀσφαλῆ πολυπράγμονος καὶ ταραχωδεστάτου βίου, ζητοῦντες εὐδίαν εὑρεῖν καὶ φροντίδων ἀνεθέντες, αἷς ἐκ πρώτης ἡλικίας καταζεύγνυνται καὶ πιέζονται, βραχύν τινα διαπνεύσαντες χρόνον ἐν ἱλαραῖς διάγειν εὐθυμίαις·", "st": "69"}, {"sp": "N", "t": "ἐλπίδων τε χρηστῶν γεμισθέντες σχολάζουσι τὴν ἀναγκαιοτάτην σχολὴν ὁσιότητι καὶ τιμῇ θεοῦ, φιλίαν καὶ πρὸς τοὺς τέως ἀγνοουμένους συντιθέμενοι καὶ κρᾶσιν ἠθῶν ἐπὶ θυσιῶν καὶ σπονδῶν εἰς βεβαιοτάτην πίστιν ὁμονοίας ποιούμενοι.", "st": "70"}, {"sp": "N", "t": "Τούτου τοῦ ἱεροῦ ὁ μὲν ἐξωτάτω περίβολος καὶ μήκει καὶ πλάτει μέγιστος ὢν τέσσαρσι στοαῖς εἰς πολυτέλειαν ἠσκημέναις ὠχύρωται· διπλῆ δ’ ἐστὶν αὐτῶν ἑκάστη, ξύλων καὶ λίθων ὕλαις καὶ χορηγίαις ἀφθόνοις καὶ δημιουργῶν ἐμπειρίαις καὶ τῶν ἐφεστηκότων ἐπιμελείαις κατεσκευασμένη, τελειότατον ἔργον· οἱ δ’ εἴσω βραχύτεροι μέν, αὐστηροτέραν δ’ ἔχοντες τὴν κατασκευήν.", "st": "71"}, {"sp": "N", "t": "κατὰ δὲ τὸ μεσαίτατον αὐτὸς ὁ νεὼς παντὸς λόγου κρείττων, ὡς ἐκ τῶν φαινομένων ἔστι τεκμήρασθαι· τὰ γὰρ ἔνδον ἀόρατα παντί τῳ πλὴν ἑνὶ τῷ ἀρχιερεῖ, καὶ τούτῳ μέντοι, δι’ ἔτους ἐπιτετραμμένον ἅπαξ εἰσιέναι, πάντ’ ἐστὶν ἀθέατα· πυρεῖον γὰρ ἀνθράκων πλῆρες καὶ θυμιαμάτων εἰσκομίζει, πολλῆς δ’ ἀναδιδομένης ὡς εἰκὸς ἀτμίδος κατέχεται τἀν κύκλῳ πάντα καὶ ἡ ὄψις ἐπισκιάζεται καὶ ἀνακοπὴν ἴσχει πρόσω χωρεῖν ἀδυνατοῦσα.", "st": "72"}, {"sp": "N", "t": "μέγιστος δὲ ὢν καὶ ὑψηλότατος, καίτοι ἐν χθαμαλωτέρῳ κείμενος, τῶν περιμηκεστάτων ὀρῶν οὐδενὸς ἀποδεῖ. τὰ μὲν οὖν ἐν οἰκοδομίαις ὑπερβολὰς ἔχοντα περίβλεπτά τ’ ἐστὶ καὶ θαυμάζεται πρὸς τῶν ὁρώντων καὶ μάλιστα τῶν ἐπιφοιτώντων ξένων, οἳ συγκρίνοντες ταῖς οἰκιῶν δημοσίων κατασκευαῖς ἐκπλήττονται τό τε κάλλος ὁμοῦ καὶ τὴν πολυτέλειαν.", "st": "73"}, {"sp": "N", "t": "ἄλσος δὲ οὐδέν ἐστιν ἐν τῷ περιβόλῳ προστάξει νόμου, διὰ πολλά· πρῶτον μὲν ὅτι οὐχ ἡδονὴν καὶ τέρψιν εὐδιάγωγον ἐπιζητεῖ τὸ πρὸς ἀλήθειαν ἱερὸν ἀλλ’ αὐστηρὰν ἁγιστείαν· δεύτερον δ’ ὅτι τὰ συντείνοντα πρὸς τὴν τῶν δένδρων χλόην οὐ θέμις εἰσκομίζεσθαι, τὰ δ’ ἐστὶν ἀνθρώπων καὶ ζῴων ἀλόγων περιττώματα· τρίτον δ’ ὅτι τὰ μὲν τῆς ἀγρίας ὕλης πρὸς οὐδὲν ὄφελος, “ἄχθος” δ’ ὡς οἱ ποιηταί φασι “γῆς”, τὰ δὲ τῆς ἡμέρου, καρπῶν ἡμέρων οἰστικά, μεθέλξει τοὺς ὀλιγόφρονας ἀπὸ τῆς περὶ τὴν ἱερουργίαν σεμνότητος.", "st": "74"}, {"sp": "N", "t": "πρὸς δὲ τούτοις λάσια χωρία καὶ δρυμοὶ βαθεῖς κακούργων εἰσὶν ἐνδιαιτήματα τὴν ἐκ τοῦ συσκιάζεσθαι ποριζομένων ἀσφάλειαν καὶ τὰς ἐξ ἐνέδρας καθ’ ὧν ἂν ἐθελήσωσιν αἰφνιδίους ἐπιθέσεις. αἱ δ’ εὐρυχωρίαι καὶ τὸ ἀναπεπταμένον καὶ τὸ ἀνειμένον πάντῃ, μηδενὸς τὰς ὄψεις ἐμποδίζοντος, πρὸς τὴν τῶν εἰσιόντων καὶ ἐνδιατριβόντων ἀκριβῆ θέαν ἱερῷ πρεπωδέστατον.", "st": "75"}, {"sp": "N", "t": "Προσόδους δ’ ἔχει τὸ ἱερὸν οὐ μόνον ἀποτομὰς γῆς ἀλλὰ καὶ πολὺ μείζους ἑτέρας, αἳ μηδενὶ χρόνῳ φθαρήσονται· ἐφ’ ὅσον γὰρ τὸ ἀνθρώπων γένος διαμενεῖ — διαμενεῖ δ’ εἰς ἀεί —, καὶ αἱ πρόσοδοι τοῦ ἱεροῦ φυλαχθήσονται συνδιαιωνίζουσαι παντὶ τῷ κόσμῳ.", "st": "76"}, {"sp": "N", "t": "προστέτακται γὰρ ἕκαστον ἀνὰ πᾶν ἔτος ἀπαρχὰς εἰσφέρειν ἀπὸ εἰκοσαετίας ἀρξάμενον. αἱ δ’ εἰσφοραὶ “λύτρα” προσονομάζονται· διὸ καὶ προθυμότατα ποιοῦνται τὰς ἀπαρχάς, φαιδροὶ καὶ γεγηθότες, ὡς ἅμα τῇ καταθέσει μέλλοντες ἢ δουλείας ἀπαλλαγὴν ἢ νόσων ἄκεσιν εὑρίσκεσθαι καὶ βεβαιοτάτην ἐλευθερίαν ὁμοῦ καὶ σωτηρίαν εἰς ἅπαν καρποῦσθαι.", "st": "77"}, {"sp": "N", "t": "πολυανθρωποτάτου δ’ ἔθνους ὡς εἰκὸς καὶ τὰς ἀπαρχὰς ἀφθονωτάτας εἶναι συμβέβηκε· σχεδὸν γοῦν ἀνὰ πᾶσαν πόλιν ταμεῖα τῶν ἱερῶν χρημάτων ἐστίν, εἰς ἃ παραγινομένοις ἔθος ἀπάρχεσθαι· καὶ χρόνοις ὡρισμένοις ἱεροπομποὶ τῶν χρημάτων ἀριστίνδην ἐπικριθέντες, ἐξ ἑκάστης οἱ δοκιμώτατοι, χειροτονοῦνται, σώους τὰς ἐλπίδας ἑκάστων παραπέμψοντες· ἐν γὰρ ταῖς νομίμοις ἀπαρχαῖς αἱ τῶν εὐσεβούντων ἐλπίδες εἰσίν.", "st": "78"}, {"sp": "N", "t": "Φυλαὶ μέν εἰσι τοῦ ἔθνους δώδεκα, μία δ’ ἐκ πασῶν ἀριστίνδην ἐπικριθεῖσα ἱερᾶται, γέρας ἀνδραγαθίας καὶ φιλοθέου σπουδῆς τουτὶ λαβοῦσα, καθ’ ὃν καιρὸν ἔδοξεν ἡ πληθὺς ἁμαρτεῖν ἐπακολουθήσασα γνώμαις ἐνίων ἀγνώμοσιν, οἳ τὴν Αἰγυπτιακὴν ἔπεισαν ζηλοῦν ἠλιθιότητα καὶ τὸν ἐγχώριον τῦφον, ὃν ἐπ’ ἀλόγοις ζῴοις καὶ μάλιστα ταύροις μυθοπλαστοῦσι· τοὺς γὰρ ἡγεμόνας τῆς ἀπονοίας ἅπαντας ἡβηδὸν αὐτοκέλευστοι κατακτείναντες εὐαγὲς ἔδοξαν ἔργον εἰργάσθαι, τοὺς ὑπὲρ εὐσεβείας ἀγῶνας διαθλήσαντες.", "st": "79"}, {"sp": "N", "t": "Νόμοι δὲ ἱερέων εἰσὶν οἵδε. παντελῆ καὶ ὁλόκληρον εἶναι τὸν ἱερέα προστέτακται, μηδεμίαν ἐν τῷ σώματι λώβην ἔχοντα, μήτε κατ’ ἔνδειαν ἐπιλείποντος ἢ ἀκρωτηριασθέντος μέρους μήτε κατὰ πλεονασμὸν ἅμα τῇ γενέσει περιττεύσαντος ἢ ὕστερον ἐκ νόσου προσφύντος μήτε τῆς χρόας μεταβαλούσης εἰς λέπραν ἢ λειχῆνας ἀγρίους ἢ μυρμηκίας ἤ τινας ἄλλας ἐξανθημάτων ἐκφύσεις· ἅ μοι δοκεῖ πάντα σύμβολα τῆς περὶ ψυχὴν εἶναι τελειότητος.", "st": "80"}, {"sp": "N", "t": "εἰ γὰρ τὸ φύσει θνητὸν σῶμα τοῦ ἱερέως ἐπισκεπτέον, ἵνα περὶ μηδὲν ἀτύχημα κηραίνῃ, πολὺ πλέον ψυχὴν τὴν ἀθάνατον, ἥν φασι τυπωθῆναι κατὰ τὴν εἰκόνα τοῦ ὄντος· λόγος δ’ ἐστὶν εἰκὼν θεοῦ, δι’ οὗ σύμπας ὁ κόσμος ἐδημιουργεῖτο.", "st": "81"}, {"sp": "N", "t": "Μετὰ δὲ τὴν ἐξ εὐπατριδῶν εὐγένειαν καὶ παντέλειαν τὴν ἔν τε σώμασι καὶ ψυχαῖς περὶ ἐσθῆτος, ἣν ἀναλαμβάνειν χρὴ τὸν ἱερέα μέλλοντα λειτουργεῖν τὰς ἱερὰς λειτουργίας, νενομοθέτηται.", "st": "82"}, {"sp": "N", "t": "ἡ δ’ ἐσθής ἐστι χιτὼν λινοῦς καὶ περίζωμα, τὸ μὲν εἰς αἰδοίων σκέπην, ἃ μὴ πρὸς τῷ θυσιαστηρίῳ γυμνοῦσθαι θέμις, ὁ δὲ χιτὼν ἕνεκα τῆς πρὸς τὴν ὑπηρεσίαν ὀξύτητος· ἀνείμονες γὰρ ἐν μόνοις χιτωνίσκοις τά τε ἱερεῖα καὶ τὰς εὐχὰς καὶ τὰς σπονδὰς καὶ ὅσα ἄλλα θυσίαις χρήσιμα προσάγουσιν εἰς ἀνυπέρθετον τάχος ἠσκημένοι.", "st": "83"}, {"sp": "N", "t": "τῷ δ’ ἀρχιερεῖ διείρηται μὲν τὴν παραπλησίαν ἐσθῆτα ἀναλαμβάνειν, ἡνίκα ἂν εἰς τὰ ἄδυτα ἐπιθυμιάσων εἰσίῃ, διὰ τὸ τὴν ὀθόνην ἐκ μηδενὸς τῶν ἀποθνῃσκόντων ὥσπερ τὰ ἔρια γεννᾶσθαι, προστέτακται δὲ καὶ ἑτέρᾳ χρῆσθαι πάνυ ποικίλην ἐχούσῃ κατασκευήν, ὡς ἀπεικόνισμα καὶ μίμημα τοῦ κόσμου δοκεῖν εἶναι. σαφὴς δὲ πίστις ἡ κατασκευή.", "st": "84"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἔνδυμα περιφερές ἐστιν, ὅλον δι’ ὅλων ὑακίνθινον, ποδήρης χιτών, ἀέρος σύμβολον, ἐπειδήπερ ὁ ἀὴρ καὶ φύσει μέλας ἐστὶ καὶ τρόπον τινὰ ποδήρης, ἄνωθεν ἀπὸ τῶν μετὰ σελήνην τόπων ταθεὶς ἄχρι τῶν κατωτάτω γῆς μυχῶν.", "st": "85"}, {"sp": "N", "t": "εἶθ’ ὕφασμα θωρακοειδὲς ἐπὶ τούτῳ, σύμβολον οὐρανοῦ· δύο τε γὰρ ἐπὶ τῶν ἀκρωμίων λίθοι σμαράγδου τῆς τιμαλφεστάτης ὕλης εἰσίν, ὁ μὲν ἔνθεν, ὁ δ’ ἔνθεν, εἷς ἑκατέρωθεν, περιφερεῖς, δείγματα τῶν ἡμισφαιρίων, ὧν τὸ μὲν ὑπὲρ γῆν τὸ δ’ ὑπὸ γῆν ἐστιν.", "st": "86"}, {"sp": "N", "t": "εἶτα πρὸς τοῖς στέρνοις δώδεκα λίθοι πολυτελεῖς τὰς χρόας διαφέροντες, ἐκ τριῶν τεταγμένοι τετραστοιχεί, πρὸς παράδειγμα τοῦ ζῳδιακοῦ τυπωθέντες· καὶ γὰρ ἐκεῖνος ἐκ δώδεκα συνεστὼς ζῳδίων τὰς ἐτησίους τέτταρας ὥρας ἀποτελεῖ τρία νείμας εἰς ἑκάστην.", "st": "87"}, {"sp": "N", "t": "σύμπας δ’ ὁ τόπος καλεῖται λογεῖον ἐτύμως, ἐπειδὴ τὰ ἐν οὐρανῷ πάντα λόγοις καὶ ἀναλογίαις δεδημιούργηται καὶ συντέτακται· τῶν γὰρ ἐκεῖ τὸ παράπαν ἄλογον οὐδέν. ἐπὶ δὲ τοῦ λογείου διττὰ ὑφάσματα καταποικίλλει προσαγορεύων τὸ μὲν δήλωσιν, τὸ δὲ ἀλήθειαν.", "st": "88"}, {"sp": "N", "t": "αἰνίττεται δὲ διὰ μὲν τῆς ἀληθείας, ὅτι οὐρανοῦ τὸ παράπαν ψεῦδος ἐπιβαίνειν οὐ θεμιτόν, ἀλλὰ τοῦθ’ ἅπαν εἰς τὸν περίγειον πεφυγάδευται χῶρον ψυχαῖς ἐναγῶν ἀνθρώπων εἰσοικιζόμενον, διὰ δὲ τῆς δηλώσεως, ὅτι αἱ κατ’ οὐρανὸν φύσεις ἕκαστα δηλοῦσι τῶν παρ’ ἡμῖν, ἃ καθ’ αὑτὰ πάντως ἂν ἦν ἄγνωστα.", "st": "89"}, {"sp": "N", "t": "σημεῖον δ’ ἐναργέστατον· εἰ μὴ φῶς, ἡλίου ἥλιος, ἀνέλαμψε, πῶς ἂν αἱ τῶν σωμάτων ἀμύθητοι ποιότητες διεφάνησαν, πῶς δ’ ἂν αἱ πολύμορφοι τῶν χρωμάτων καὶ σχημάτων ἰδέαι; ἡμέρας δὲ καὶ νύκτας μῆνάς τε καὶ ἐνιαυτοὺς καὶ συνόλως χρόνον τίς ἀνέδειξεν ὅτι μὴ σελήνης καὶ ἡλίου καὶ τῶν ἄλλων ἀστέρων αἱ ἐναρμόνιοι καὶ παντὸς λόγου κρείττους περιφοραί;", "st": "90"}, {"sp": "N", "t": "τίς δὲ τὴν ἀριθμοῦ φύσιν εἰ μὴ τὰ λεχθέντα κατὰ τὰς τῶν μερῶν τοῦ χρόνου συνθέσεις; τίς δὲ τὰς ἐν θαλάσσῃ καὶ τοσούτοις πελάγεσιν ὁδοὺς ἀνέτεμε καὶ διέδειξε πλωτῆρσιν εἰ μὴ αἱ τῶν ἀστέρων στροφαὶ καὶ περίοδοι;", "st": "91"}, {"sp": "N", "t": "σοφοὶ δ’ ἄνδρες καὶ μυρία ἄλλα παρατηρήσαντες ἀνέγραψαν, ἐκ τῶν οὐρανίων σημειωσάμενοι νηνεμίας καὶ βίας πνευμάτων, φορὰς καὶ ἀφορίας καρπῶν, ἀνειμένα καὶ φλογωδέστατα θέρη, χειμῶνας ἐξαισίους καὶ ἐαρίζοντας, αὐχμοὺς καὶ ἐπομβρίας, εὐγονίας ζῴων καὶ φυτῶν καὶ τοὐναντίον ἑκατέρων ἀγονίας καὶ ὅσα τοιουτότροπα· πάντων γὰρ ἐστηλίτευται τῶν ἐπὶ γῆς ἐν οὐρανῷ τὰ σημεῖα.", "st": "92"}, {"sp": "N", "t": "πρὸς δὲ τοῖς κατωτάτω μέρεσι τοῦ ποδήρους ἀπῃώρηνται χρυσοῖ ῥοΐσκοι κώδωνές τε καὶ ἄνθινα· τὰ δ’ ἐστὶ σύμβολα γῆς καὶ ὕδατος, γῆς μὲν τὰ ἄνθινα, παρόσον βλαστάνει καὶ ἀνθεῖ πάντα ἐκ ταύτης, ὕδατος δὲ οἱ ῥοΐσκοι λεχθέντες ἐτύμως παρὰ τὴν ῥύσιν, τὴν δ’ ἁρμονίαν καὶ συμφωνίαν καὶ συνήχησιν τῶν τοῦ κόσμου μερῶν οἱ κώδωνες ἐμφαίνουσιν.", "st": "93"}, {"sp": "N", "t": "εὖ δ’ ἔχει καὶ ἡ θέσις· ἀνωτάτω μέν, ἐν ᾧ οἱ λίθοι, τὸ καλούμενον περιστήθιον, οὐρανοῦ μίμημα, διότι καὶ ὁ οὐρανὸς ἀνωτάτω, ὁ δὲ ποδήρης ὑπ’ αὐτῷ, ὅλος δι’ ὅλων ὑακίνθινος, ἐπειδὴ καὶ ὁ ἀὴρ μέλας ὢν τὴν μετ’ οὐρανὸν δευτέραν τάξιν κεκλήρωται, τὰ δ’ ἄνθινα καὶ οἱ ῥοΐσκοι πρὸς τοῖς ἐσχάτοις, διότι γῆ καὶ ὕδωρ τὴν κατωτάτω τοῦ παντὸς μοῖραν ἔλαχον.", "st": "94"}, {"sp": "N", "t": "ἥδ’ ἐστὶν ἡ τῆς ἱερᾶς ἐσθῆτος κατασκευή, μίμημα τοῦ παντός, θαυμάσιον ἔργον καὶ ὀφθῆναι καὶ νοηθῆναι· καὶ γὰρ ὄψιν ἔχει καταπληκτικωτάτην οἵαν οὐδὲν ὕφασμα τῶν παρ’ ἡμῖν ἕνεκα ποικιλίας ὁμοῦ καὶ πολυτελείας καὶ νόησιν τὴν περὶ τῶν αὐτῆς μερῶν φιλόσοφον.", "st": "95"}, {"sp": "N", "t": "βούλεται γὰρ τὸν ἀρχιερέα πρῶτον μὲν εἰκόνα τοῦ παντὸς ἔχειν ἐμφανῆ περὶ ἑαυτόν, ἵν’ ἐκ τῆς συνεχοῦς θέας ἄξιον παρέχῃ τὸν ἴδιον βίον τῆς τῶν ὅλων φύσεως, ἔπειθ’ ὅπως ἐν ταῖς ἱερουργίαις συλλειτουργῇ πᾶς ὁ κόσμος αὐτῷ· πρεπωδέστατον δὲ τὸ τὸν ἱερώμενον τῷ τοῦ κόσμου πατρὶ καὶ τὸν υἱόν, τὸ πᾶν, ἐπάγεσθαι πρὸς θεραπείαν τοῦ δεδημιουργηκότος καὶ γεγεννηκότος.", "st": "96"}, {"sp": "N", "t": "ἔστι δὲ καὶ τρίτον τι τῆς ἱερᾶς ἐσθῆτος σύμβολον ἀναγκαῖον μὴ ἡσυχασθῆναι· τῶν μὲν γὰρ ἄλλων οἱ ἱερεῖς ὑπὲρ οἰκείων καὶ φίλων καὶ πολιτῶν αὐτὸ μόνον εἰώθασι τάς τε εὐχὰς καὶ θυσίας ἐπιτελεῖν, ὁ δὲ τῶν Ἰουδαίων ἀρχιερεὺς οὐ μόνον ὑπὲρ ἅπαντος ἀνθρώπων γένους ἀλλὰ καὶ ὑπὲρ τῶν τῆς φύσεως μερῶν, γῆς, ὕδατος, ἀέρος, πυρός, τάς τε εὐχὰς καὶ τὰς εὐχαριστίας ποιεῖται, τὸν κόσμον, ὅπερ ἐστὶ ταῖς ἀληθείαις, ἑαυτοῦ πατρίδα εἶναι νομίζων, ὑπὲρ ἧς ἱκεσίαις καὶ λιταῖς εἴωθεν ἐξευμενίζεσθαι τὸν ἡγεμόνα ποτνιώμενος τῆς ἐπιεικοῦς καὶ ἵλεω φύσεως αὐτοῦ μεταδιδόναι τῷ γενομένῳ.", "st": "97"}, {"sp": "N", "t": "Ταῦθ’ ὑπειπὼν προσνομοθετεῖ κελεύων τὸν προσιόντα τῷ βωμῷ καὶ ψαύοντα θυσιῶν, ἐν ᾧ χρόνῳ τέτακται τὰς ἱερὰς λειτουργίας ἐπιτελεῖν, μήτ’ οἶνον μήτε τι ἄλλο μέθυσμα πίνειν, τεττάρων ἕνεκα τῶν ἀναγκαιοτάτων, ὄκνου καὶ λήθης καὶ ὕπνου καὶ ἀφροσύνης.", "st": "98"}, {"sp": "N", "t": "ἄκρατος γὰρ τὰς μὲν τοῦ σώματος δυνάμεις ἀνιεὶς δυσκινητότερα τὰ μέλη ποιεῖ καὶ ὀκνηροτέρους ἀπεργάζεται καὶ βίᾳ καταδαρθάνειν ἀναγκάζει, τοὺς δὲ τῆς ψυχῆς τόνους ἐπιχαλῶν λήθης ὁμοῦ καὶ ἀφροσύνης αἴτιος γίνεται· νήφοντος δὲ τά τε μέρη τοῦ σώματος ἐπελαφριζόμενα εὐκινητότερα αἵ τε αἰσθήσεις καθαρώτεραι καὶ εἱλικρινέστεραι ὅ τε νοῦς ὀξυωπέστερος, ὡς καὶ προϊδέσθαι πράγματα δύνασθαι καὶ ἃ πρότερον εἶδεν ἀπομνημονεῦσαι.", "st": "99"}, {"sp": "N", "t": "συνόλως μὲν οὖν τὴν οἴνου χρῆσιν ἅπασι τοῖς κατὰ τὸν βίον ἀλυσιτελεστάτην ὑποληπτέον, ψυχῆς πιεζομένης, αἰσθήσεων ἀμαυρουμένων, βαρυνομένου σώματος — ἐλεύθερον γὰρ καὶ ἄφετον οὐδὲν ἐᾷ τῶν παρ’ ἡμῖν, ἀλλ’ ἑκάστῳ πρὸς ὃ πέφυκεν ἐμπόδιός ἐστιν —, ἐν δὲ ταῖς ἁγιστείαις καὶ ἱερουργίαις τὸ βλάβος ἀργαλεώτερον, ὅσῳ καὶ τὸ περὶ θεὸν ἐξαμαρτεῖν τοῦ περὶ ἄνθρωπον ἀφορητότερον. ὅθεν εἰκότως προστέτακται νηφαλίους θύειν, “εἰς διαστολὴν καὶ διάκρισιν ἁγίων καὶ βεβήλων καὶ καθαρῶν καὶ ἀκαθάρτων” καὶ νομίμων καὶ παρανόμων.", "st": "100"}, {"sp": "N", "t": "Ἐπεὶ δ’ ὁ ἱερεὺς πολὺ πρότερον ἀνήρ ἐστι καὶ ταῖς πρὸς συνουσίαν ὁρμαῖς ἐξ ἀνάγκης ὀφείλει χρῆσθαι, γάμον αὐτῷ μνᾶται παρθένου καθαρᾶς καὶ ἐκ καθαρῶν γονέων καὶ πάππων καὶ προγόνων εἴς τε καλοκἀγαθίαν καὶ εὐγένειαν ἀριστίνδην ἐπικριθέντων.", "st": "101"}, {"sp": "N", "t": "πόρνῃ μὲν γὰρ καὶ βεβήλῳ σῶμα καὶ ψυχὴν οὐδὲ προσελθεῖν ἐᾷ, κἂν τὴν ἐργασίαν ἀποθεμένη σχῆμα κόσμιον καὶ σῶφρον ὑποδύηται, διὰ τὸ τὴν ἀρχαίαν προαίρεσιν ἀνίερον αὐτῇ γενέσθαι. αὕτη δὲ πρὸς μὲν τὰ ἄλλα ἐπιτιμίαν ἐχέτω σπουδάσασα μιασμάτων καθαρεῦσαι· μετάνοια γὰρ ἀδικημάτων ἐπαινετόν· καὶ μηδεὶς ἕτερος αὐτὴν ἄγεσθαι κεκωλύσθω, ἱερεῖ δὲ μὴ προσίτω· τὰ γὰρ ἱερωσύνης ἐξαίρετα δίκαια συμφωνίαν ἐπιζητούσης τὴν ἀπὸ γενέσεως [ἀρχῆς] ἄχρι τελευτῆς ἀνυπαίτιον.", "st": "102"}, {"sp": "N", "t": "εὔηθες γὰρ διὰ μὲν τὰς ἐκ τῶν τραυμάτων ἐπιγενομένας οὐλὰς ἐν τοῖς σώμασιν εἴργεσθαί τινας ἱερωσύνης, αἳ σύμβολον ἀτυχίας, οὐ μοχθηρίας, εἰσί, τὰς δὲ μὴ κατ’ ἀνάγκην μόνον ἀλλ’ ἔστιν ὅτε καὶ ἑκουσίοις γνώμαις πεπρακυίας τὴν ἰδίαν ὥραν, ἐπειδήπερ ὀψὲ καὶ μόλις μετέγνωσαν, εὐθὺς ἀπὸ ἐραστῶν ἱερεῦσιν ἁρμόζεσθαι καὶ ἀπὸ χαμαιτυπείων εἰς ἱερὰ χωρία μετοικίζεσθαι· μένουσι γὰρ οὐδὲν ἧττον ἐν ταῖς ψυχαῖς τῶν μετανοούντων οὐλαὶ καὶ τύποι τῶν ἀρχαίων ἀδικημάτων.", "st": "103"}, {"sp": "N", "t": "εὖ καὶ παγκάλως ἐν ἑτέροις διείρηται “μηδὲ μίσθωμα πόρνης εἰσκομίζειν εἰς τὸ ἱερόν”· καίτοι τό γε νόμισμα καθ’ αὑτὸ οὐκ ἔνοχον, ἀλλὰ διὰ τὴν λαβοῦσαν καὶ τὴν πρᾶξιν ἐφ’ ᾗ δέδοται. σχολῇ γ’ ἂν ἔτι προσοῖτό τις εἰς κοινωνίαν ἱερέων γυναῖκας, ὧν καὶ τὰ χρήματα βέβηλα καὶ παράσημα, εἰ καὶ ταῖς ὕλαις καὶ τοῖς χαρακτῆρσι δόκιμα.", "st": "104"}, {"sp": "N", "t": "Τὰ μὲν οὖν περὶ γάμον οὕτως ἠκρίβωται τῷ ἀρχιερεῖ, ὥστ’ οὐδὲ χήραν ἐφεῖται γαμεῖν αὐτῷ, οὔτε τετελευτηκότος ἀνδρὸς μονωθεῖσαν οὔτε ἀπηλλαγμένην ἔτι ζῶντος, ἵνα πρῶτον μὲν εἰς ἄβατον καὶ καθαρὰν ἄρουραν ὁ ἱερὸς σπόρος χωρῇ καὶ μηδεμίαν κρᾶσιν αἱ γοναὶ πρὸς ἑτέραν οἰκίαν λαμβάνωσιν, εἶτα δ’ ὅπως ἀκακωτάταις καὶ ἀδιαστρόφοις ταῖς ψυχαῖς συνερχόμενοι ῥᾳδίως διαπλάττωσι τὰ ἤθη καὶ τοὺς τρόπους αὐτῶν· ὁλκοὶ γὰρ καὶ εὐάγωγοι διάνοιαι παρθένων πρὸς ἀρετήν, εἰς διδασκαλίαν ἑτοιμόταται·", "st": "105"}, {"sp": "N", "t": "ἡ δ’ ἑτέρου πεῖραν ἀνδρὸς λαβοῦσα κατὰ τὸ εἰκὸς ἀπειθεστέρα πρὸς μάθησιν, ἅτε τὴν ψυχὴν ἀκραιφνεστάτην οὐκ ἔχουσα καθάπερ τινὰ λελειασμένον κηρὸν εἰς τρανότητα τῶν ἐγγραφησομένων δογμάτων, ἀλλὰ τραχεῖαν ὑπὸ τῶν προεγχαραχθέντων τύπων, οἳ δυσεξάλειπτοι παραμένοντες ἢ οὐ παραδέχονται σφραγῖδας ἑτέρας ἢ παραδεξάμενοι συγχέουσι ταῖς ἑαυτῶν ἀνωμαλίαις.", "st": "106"}, {"sp": "N", "t": "παρθένον οὖν ὁ ἀρχιερεὺς ἀγέσθω γάμων ἁγνήν· λέγω δὲ παρθένον οὐ μόνον ᾗ μὴ ἕτερος ὡμίλησεν, ἀλλὰ καὶ ἐφ’ ᾗ μηδεὶς ἄλλος ἀνὴρ ὠνομάσθη διά τινων ὁμολογιῶν, κἂν ἁγνεύῃ τὸ σῶμα.", "st": "107"}, {"sp": "N", "t": "Τοῖς δὲ κατὰ μέρος ἱερεῦσι τὰ μὲν ἄλλα περὶ γάμων διατέτακται ταὐτὰ ἃ καὶ τοῖς τὴν μεγίστην ἔχουσιν ἱερωσύνην, ἐφεῖται δ’ οὐ μόνον παρθένους ἀλλὰ καὶ χήρας, οὐ πάσας ἀλλ’ ὧν τετελευτήκασιν ἄνδρες, μετ’ ἀδείας ἄγεσθαι. φιλονεικίας γὰρ καὶ στάσεις ἐκ τοῦ βίου τῶν ἱερέων οἴεται δεῖν ὁ νόμος ἀναιρεῖν· πρὸς μὲν οὖν τοὺς ζῶντας γένοιντ’ ἂν ἴσως ἔριδες ἐκ πάθους γυναικείου, ζηλοτυπίας, τοῖς δ’ ἀποθανοῦσι συναποθνῄσκει καὶ τὰ τῆς πρὸς τοὺς δευτέρους ἄνδρας ἔχθρας.", "st": "108"}, {"sp": "N", "t": "ἄλλως τε τὸν ἀρχιερέα πλείονος ἐδικαίωσεν ἁγιστείας καὶ καθάρσεως ὥσπερ ἐν ἅπασι τοῖς ἄλλοις καὶ ἐν γάμου κοινωνίᾳ μεταλαχεῖν, οὐκ ἐάσας ὅτι μὴ κόρην ἄγεσθαι· τοῖς δὲ τῆς δευτέρας τάξεως ὑπανῆκε τὰ περὶ συνόδους γυναικῶν, ἐφιεὶς καὶ πεπειραμένας ἑτέρων ἀνδρῶν ἐγγυᾶσθαι.", "st": "109"}, {"sp": "N", "t": "πρὸς δὲ τούτῳ καὶ τὸ γένος ἠκρίβωσε τῶν μελλουσῶν γαμεῖσθαι, προστάξας τῷ μὲν ἀρχιερεῖ μνᾶσθαι μὴ παρθένον μόνον ἀλλὰ καὶ ἱέρειαν ἐξ ἱερέων, ἵν’ ἐκ μιᾶς οἰκίας καὶ τρόπον τινὰ τοῦ αὐτοῦ αἵματος ὦσι νυμφίος τε καὶ νύμφη πρὸς ἁρμονίαν ἐπιδειξάμενοι παρ’ ὅλον τὸν βίον κρᾶσιν ἠθῶν βεβαιοτάτην.", "st": "110"}, {"sp": "N", "t": "ἐπετράπη δὲ τοῖς ἄλλοις καὶ μὴ ἱερέων γαμεῖν θυγατέρας, τῇ μὲν ὅτι μικρὰ τούτων καθάρσια, τῇ δ’ ὅτι τὸ ἔθνος οὐκ ἐβουλήθη γενεᾶς εἰς ἅπαν ἱερατικῆς ἀμοιρῆσαί τε καὶ παντελῶς ἀπεζεῦχθαι. δι’ ἣν αἰτίαν οὐκ ἐκώλυσε τοὺς ἄλλους ἱερέας ἐπιγαμίας ποιεῖσθαι πρὸς τοὺς ἀπὸ τοῦ ἔθνους, αἵπερ εἰσὶ δεύτεραι συγγένειαι· γαμβροὶ γὰρ ἀνθ’ υἱῶν πενθεροῖς καὶ ἀντὶ πατέρων γαμβροῖς πενθεροί.", "st": "111"}, {"sp": "N", "t": "Τὰ μὲν δὴ περὶ γάμου ταῦτα καὶ τὰ τούτοις ὅμοια χάριν παίδων γενέσεως. ἐπεὶ δ’ ἕπεται γενέσει φθορά, καὶ τοὺς ἐπὶ τελευταῖς ἀνέγραψε τοῖς ἱερεῦσι νόμους, κελεύσας μὴ ἐφ’ ἅπασιν αὐτοὺς μιαίνεσθαι τοῖς ὁπωσοῦν ἢ κατὰ φιλίαν ἢ κατὰ συγγένειαν ᾠκειωμένοις, ἀλλ’ ἐπὶ μόνοις πατράσι καὶ μητράσιν, υἱοῖς καὶ θυγατράσιν, ἀδελφοῖς καὶ ἀδελφαῖς παρθένοις.", "st": "112"}, {"sp": "N", "t": "τὸν δ’ ἀρχιερέα παντὸς πένθους ὑπεξείλετο· καὶ μήποτ’ εἰκότως· τὰς μὲν γὰρ τῶν ἄλλων ἱερέων ὑπηρεσίας ἀνθ’ ἑτέρων ἕτεροι λειτουργεῖν δύνανται, ὡς, κἂν πενθῶσί τινες, μηδὲν τῶν ἐξ ἔθους ὑστερίζειν, τὰς δὲ τοῦ ἀρχιερέως οὐδενὶ δρᾶν ἐφεῖται. παρ’ ἣν αἰτίαν ἀμίαντος ἀεὶ διατελείτω μὴ προσαπτόμενος νεκροῦ σώματος, ὅπως τὰς ὑπὲρ τοῦ ἔθνους εὐχὰς καὶ θυσίας ἕτοιμος ὢν ἐν καιροῖς τοῖς προσήκουσιν ἀκωλύτως ἐπιτελῇ.", "st": "113"}, {"sp": "N", "t": "καὶ γὰρ ἄλλως προσκεκληρωμένος θεῷ καὶ τῆς ἱερᾶς τάξεως γεγονὼς ταξίαρχος ὀφείλει πάντων ἀλλοτριοῦσθαι τῶν ἐν γενέσει, μὴ γονέων, μὴ τέκνων, μὴ ἀδελφῶν εὐνοίας οὕτως ἡττώμενος, ὡς ἢ παρελθεῖν ἢ ὑπερθέσθαι τι τῶν ὁσίων, ὃ πραχθῆναι πάντως αὐτίκα ἄμεινον.", "st": "114"}, {"sp": "N", "t": "κελεύει δὲ μήτε τὰ ἱμάτια περιρρήττειν ἐπὶ τοῖς οἰκειοτάτοις ἀποθανοῦσι μήτε ἀφαιρεῖν ἀπὸ τῆς κεφαλῆς τὰ παράσημα τῆς ἱερωσύνης μήτε συνόλως ἐκ τῶν ἁγίων ἐξιέναι κατὰ πρόφασιν πένθους, ἵνα καὶ τὸν τόπον αἰδούμενος καὶ τὰ περὶ ἑαυτὸν προκοσμήματα οἷς ἀνέστεπται, κρείττων οἴκτου γενόμενος, ἄλυπος εἰς ἀεὶ διατελῇ.", "st": "115"}, {"sp": "N", "t": "βούλεται γὰρ αὐτὸν ὁ νόμος μείζονος μεμοιρᾶσθαι φύσεως ἢ κατ’ ἄνθρωπον, ἐγγυτέρω προσιόντα τῆς θείας, μεθόριον, εἰ δεῖ τἀληθὲς λέγειν, ἀμφοῖν, ἵνα διὰ μέσου τινὸς ἄνθρωποι μὲν ἱλάσκωνται θεόν, θεὸς δὲ τὰς χάριτας ἀνθρώποις ὑποδιακόνῳ τινὶ χρώμενος ὀρέγῃ καὶ χορηγῇ.", "st": "116"}, {"sp": "N", "t": "Ταῦτ’ εἰπὼν ἑξῆς εὐθὺς νομοθετεῖ περὶ τῶν χρησομένων ταῖς ἀπαρχαῖς. ἐὰν οὖν τις, φησί, τῶν ἱερέων ὀφθαλμοὺς ἢ χεῖρας ἢ βάσεις ἤ τι μέρος ἄλλο πηρωθῇ τοῦ σώματος ἢ καί τινα μῶμον ἐνδέξηται, λειτουργιῶν μὲν ἀνεχέτω διὰ τὰς ἐγγενομένας κῆρας, τὰ δὲ κοινὰ τῶν ἱερέων γέρα καρπούσθω διὰ τὴν ἀνυπαίτιον εὐγένειαν.", "st": "117"}, {"sp": "N", "t": "ἐὰν μέντοι λέπραι τινὸς ἐξανθήσασαι κατάσχωσιν ἢ καὶ γονορρυής τις γένηται τῶν ἱερέων, μήτε τραπέζης ἱερᾶς ψαυέτω μήτε τῶν προκειμένων ἄθλων τῷ γένει, μέχρις ἂν ἥ τε ῥύσις ἐπίσχῃ καὶ ἡ λέπρα μεταβαλοῦσα τῷ τῆς ὑγιοῦς σαρκὸς ἐξομοιωθῇ χρώματι.", "st": "118"}, {"sp": "N", "t": "κἂν προσάψηται μέντοι τις ὅτου δήποτε τῶν ἀκαθάρτων ἱερεὺς ἢ καὶ νύκτωρ, οἷα φιλεῖ πολλάκις, ὀνειρώξῃ, τὴν ἡμέραν ἐκείνην μηδὲν προσφερέσθω τῶν καθιερωθέντων, λουσάμενος δ’ ἐπιγενομένης ἑσπέρας χρῆσθαι μὴ κεκωλύσθω.", "st": "119"}, {"sp": "N", "t": "πάροικος δ’ ἱερέως καὶ μισθωτὸς εἰργέσθω τῶν ἀπαρχῶν, ὁ μὲν πάροικος, ἐπειδὴ γείτονες τὰ πολλὰ συνέστιοι καὶ ὁμοτράπεζοι· δέος γάρ, μὴ προῆταί τις τὰ καθιερωθέντα προφάσει καταχρησάμενος εἰς ἀσέβειαν ἀκαίρῳ φιλανθρωπίᾳ· μεταδοτέον γὰρ οὐ πᾶσι πάντων, ἀλλὰ τῶν ἐφαρμοζόντων τοῖς ληψομένοις· εἰ δὲ μή, τὸ κάλλιστον καὶ λυσιτελέστατον τῶν ἐν τῷ βίῳ, τάξις, ἀναιρεθήσεται ὑπὸ τοῦ βλαβερωτάτου παρευημερηθεῖσα, συγχύσεως.", "st": "120"}, {"sp": "N", "t": "εἰ γὰρ ἴσον μὲν μέρος ἐν ὁλκάσιν οἴσονται ναῦται κυβερνήταις, ἴσον δὲ ἐν ταῖς μακραῖς τριήρεσι τριηράρχοις καὶ ναυάρχοις ἐρέται καὶ τὸ ἐπιβατικόν, ἐν δὲ στρατοπέδοις ἴσον ἱππεῖς μὲν ἱππάρχοις, ὁπλῖται δὲ ταξιάρχοις, λοχαγοὶ δὲ στρατηγοῖς, ἐν δὲ πόλεσι κρινόμενοι δικασταῖς καὶ βουλευταὶ προβούλοις καὶ συνόλως ἄρχουσιν ἰδιῶται, ταραχαὶ καὶ στάσεις γενήσονται καὶ ἡ διὰ λόγων ἰσότης τὴν δι’ ἔργων ἀνισότητα γεννήσει· τὸ γὰρ τοῖς τὰς ἀξίας ἀνομοίοις ὅμοια ἀπονέμειν ἄνισον, τὸ δ’ ἄνισον πηγὴ κακῶν.", "st": "121"}, {"sp": "N", "t": "οὗ χάριν καὶ τὰ γέρα τῶν ἱερέων οὐ δοτέον ὥσπερ ἄλλοις οὐδὲ τοῖς παροίκοις ἕνεκα τοῦ γειτνιᾶν ἐφαψομένοις ὧν οὐ θέμις· οὐ γὰρ οἰκίας ἀλλὰ γένους ἐστὶν ἡ τιμή.", "st": "122"}, {"sp": "N", "t": "ὁμοίως μέντοι μηδὲ μισθωτῷ μηδεὶς παρεχέτω μήτε μισθὸν μήθ’ ὑπηρεσίας ἀμοιβὴν ἱερὸν γέρας· χρήσεται γὰρ ὁ λαβὼν ἔστιν ὅτε πρὸς ἃ μὴ δεῖ, βέβηλα τὰ τῆς εὐγενείας ἆθλα καὶ τῆς περὶ τὸν νεὼν λειτουργίας ἀπεργασάμενος.", "st": "123"}, {"sp": "N", "t": "δι’ ἣν αἰτίαν οὐδ’ ἀλλογενεῖ συνόλως ὁ νόμος ἐπιτρέπει μεταλαμβάνειν τῶν ἁγίων, κἂν εὐπατρίδης ὢν τυγχάνῃ τῶν αὐτοχθόνων καὶ πρὸς ἀνδρῶν καὶ πρὸς γυναικῶν ἀνεπίληπτος [ὤν], ἵνα αἱ τιμαὶ μὴ νοθεύωνται, μένωσι δ’ ἐν τῇ ἱερατικῇ τάξει βεβαίως φυλαττόμεναι.", "st": "124"}, {"sp": "N", "t": "καὶ γὰρ ἄτοπον τὰς μὲν θυσίας καὶ ἱερουργίας καὶ ὅσα ἄλλα περὶ τὸν βωμὸν ἁγιστεύεται μὴ πᾶσιν ἀλλὰ τοῖς ἱερεῦσι μόνοις ἐπιτετράφθαι, τὰ δὲ ἀντὶ τούτων ἆθλα κοινὰ γίνεσθαι καὶ τῶν ἐπιτυχόντων, ὡς δέον μὲν πόνοις πολλοῖς καὶ καμάτοις καὶ ταῖς μεθ’ ἡμέραν καὶ νύκτωρ φροντίσιν ἀποτρύχειν τοὺς ἱερέας, τὰ δ’ ἆθλα κοινὰ καὶ τοῖς ἀργοῦσιν ἀποφαίνειν.", "st": "125"}, {"sp": "N", "t": "οἰκογενεῖ δέ, φησίν, καὶ ἀργυρωνήτῳ μεταδιδότω δεσπότης ἱερεὺς σιτίων καὶ ποτῶν ἐκ τῶν ἀπαρχῶν· πρῶτον μὲν ὅτι θεράποντι πόρος εἷς ὁ δεσπότης, ὁ δὲ τοῦ δεσπότου κλῆρος αἱ ἱεραὶ φιλανθρωπίαι, ἐξ ὧν ἀνάγκη τὸν δοῦλον τρέφεσθαι·", "st": "126"}, {"sp": "N", "t": "δεύτερον δ’ ὅτι τὰ γενησόμενα πάντως ἀνάγκη δρᾶν ἑκόντας· οἱ δ’ οἰκέται, κἂν μὴ θέλωμεν, ἅτε ἀεὶ συνόντες καὶ συνδιαιτώμενοι, σιτία τε καὶ ποτὰ καὶ ὄψα τοῖς δεσπόταις προευτρεπιζόμενοι καὶ τραπέζαις ἐφεστῶτες καὶ τὰ λείψανα ἐκκομίζοντες, κἂν μὴ φανερῶς λαμβάνωσι, λάθρα γοῦν ὑφαιρήσονται, κλέπτειν ὑπὸ τῆς ἀνάγκης βιασθέντες, ὡς ἀνθ’ ἑνὸς ἐγκλήματος, εἴπερ ἐστὶν ἀδίκημα τὸ ἐκ τῶν δεσποτικῶν τρέφεσθαι, καὶ ἕτερον προσκατασκευάζεσθαι, κλοπήν, ἵνα οἷα φῶρες πρὸ τῶν ἀνυπαιτίως ζώντων ἀπολαύσωσι τῶν καθιερωθέντων, ὅπερ ἐστὶν ἀτοπώτατον·", "st": "127"}, {"sp": "N", "t": "τρίτον κἀκεῖνο χρὴ λογίζεσθαι, ὅτι τὰ τῶν ἀπαρχῶν οὐ παρόσον ἐπινέμεται τοῖς οἰκέταις ὀλιγωρηθήσεται, διὰ τὸν δεσποτικὸν φόβον· ἱκανὸς γὰρ οὗτος ἐπιστομίζειν τήν τινων εὐχέρειαν ῥᾳθυμεῖν οὐκ ἐφιείς.", "st": "128"}, {"sp": "N", "t": "Ταῦθ’ ὑπειπὼν φιλανθρωπίας μεστὸν νόμον ἑξῆς ἀναγράφει. ἐὰν θυγάτηρ, φησίν, ἱερέως γημαμένη μὴ ἱερεῖ χηρεύσῃ, τελευτήσαντος ἀνδρὸς ἢ καὶ ἔτι ζῶντος, ἄπαις καταλειφθεῖσα, πάλιν ἐπὶ τὸν πατρῷον οἶκον ἐπανερχέσθω μεταληψομένη τῶν ἀπαρχῶν, ὧν καὶ ἡνίκα παρθένος ἦν ἐκοινώνει· τρόπον γάρ τινα καὶ νῦν ἐστι δυνάμει παρθένος ἡ καὶ ἀνδρὸς καὶ παίδων ἔρημος, οὐδεμίαν ἑτέραν ἔχουσα καταφυγὴν ὅτι μὴ τὸν πατέρα.", "st": "129"}, {"sp": "N", "t": "υἱῶν δὲ ὄντων ἢ θυγατέρων, ἀνάγκη τὴν μητέρα τοῖς τέκνοις συντετάχθαι· υἱοὶ γὰρ καὶ θυγατέρες τῆς τοῦ γεννήσαντος οἰκίας ὄντες εἰς ταύτην συνεφέλκονται καὶ τὴν μητέρα.", "st": "130"}, {"sp": "N", "t": "Τοῖς ἱερεῦσιν οὐκ ἀπένειμε χώρας ἀποτομὴν ὁ νόμος, ἵν’ ὡς ἕτεροι τὰς ἀπὸ τῆς γῆς καρπούμενοι προσόδους τῶν ἀναγκαίων εὐπορῶσιν, ἀλλ’ ὑπερβολῇ χρησάμενος τιμῆς τὸν θεὸν ἔφη κλῆρον αὐτῶν εἶναι, κατ’ ἀναφορὰν τὴν ἐπὶ τὰ καθιερούμενα, δυεῖν ἕνεκα, τῆς τε ἀνωτάτω τιμῆς, ἐπεὶ κοινωνοὶ τῶν κατ’ εὐχαριστίαν ἀπονεμομένων γίνονται θεῷ, καὶ τοῦ περὶ μόνα πραγματεύεσθαι δεῖν τὰ περὶ τὰς ἁγιστείας ὥσπερ τινὰς κλήρων ἐπιμελητάς.", "st": "131"}, {"sp": "N", "t": "ἃ δὲ προτίθησιν ἆθλα καὶ ἀριστεῖα ταῦτ’ ἐστί. πρῶτον μὲν ἄπονον καὶ ἀταλαίπωρον τροφὴν ἑτοίμην· κελεύει γὰρ τοὺς σιτοπονοῦντας ἀπὸ παντὸς στέατός τε καὶ φυράματος ἄρτον ἀφαιρεῖν ἀπαρχὴν εἰς ἱερέων χρῆσιν, προνοούμενος ἅμα καὶ τῆς εἰς εὐσέβειαν ἀγούσης ὁδοῦ νομίμῳ διδασκαλίᾳ τῶν ἀφαιρούντων.", "st": "132"}, {"sp": "N", "t": "ἐθιζόμενοι γὰρ ἀεὶ καὶ τῆς ἀναγκαίας τροφῆς ἀπάρχεσθαι τὴν θεοῦ μνήμην ἄληστον ἕξουσιν, οὗ μεῖζον ἀγαθὸν οὐκ ἔστιν εὑρεῖν. πολυανθρωποτάτου δ’ ἔθνους ἀναγκαῖον εἶναι καὶ τὰς ἀπαρχὰς ἀφθόνους, ὡς καὶ τὸν ἀπορώτατον τῶν ἱερέων ἕνεκα περιουσίας τροφῶν εὐπορώτατον δοκεῖν εἶναι.", "st": "133"}, {"sp": "N", "t": "δεύτερον δὲ προστάττει καὶ ἀπὸ τῆς ἄλλης ἁπάσης κτήσεως ἀπάρχεσθαι, καθ’ ἑκάστην μὲν ληνὸν οἶνον, καθ’ ἑκάστην δ’ ἅλωνα σῖτόν τε καὶ κριθήν, ὁμοίως δ’ ἐξ ἐλαιῶν ἔλαιον καὶ ἀπὸ τῶν ἄλλων ἀκροδρύων ἡμέρους καρπούς, ἵνα μὴ τἀναγκαῖα μόνον ἔχοντες αὐχμηρότερον ἀποζῶσιν, ἀλλὰ καὶ τῶν πρὸς ἁβροδίαιτον βίον εὐποροῦντες ἱλαρώτερον ἐξ ἀφθόνων τρυφῶσι μετὰ κόσμου τοῦ προσήκοντος.", "st": "134"}, {"sp": "N", "t": "τρίτον ἐστὶ γέρας τὰ πρωτότοκα ἀρρενικὰ πάντα τῶν χερσαίων ὅσα πρὸς ὑπηρεσίαν καὶ χρῆσιν ἀνθρώπων· ταῦτα γὰρ κελεύει διαδίδοσθαι τοῖς ἱερεῦσι, βοῶν μὲν καὶ προβάτων καὶ αἰγῶν αὐτὰ τὰ ἔκγονα, μόσχους καὶ κριοὺς καὶ χιμάρους, ἐπειδὴ καθαρὰ καὶ πρὸς ἐδωδὴν καὶ πρὸς θυσίας ἐστί τε καὶ νενόμισται, λύτρα δὲ τῶν ἄλλων κατατιθέναι, ἵππων καὶ ὄνων καὶ καμήλων καὶ τῶν παραπλησίων, μὴ μειοῦντας τὴν ἀξίαν.", "st": "135"}, {"sp": "N", "t": "ἔστι δὲ καὶ ταῦτα παμπληθῆ· κτηνοτροφοῦσι γὰρ καὶ ζῳοτροφοῦσιν ἐν τοῖς μάλιστα οἱ ἀπὸ τοῦ ἔθνους αἰπόλια καὶ βουκόλια καὶ ποίμνας καὶ μυρίας ἄλλας ἀγέλας παντοδαπῶν ζῴων ἐκνέμοντες.", "st": "136"}, {"sp": "N", "t": "ἤδη μέντοι καὶ προσυπερβάλλων ὁ νόμος οὐ μόνον ἀπὸ τῆς κτήσεως καθ’ ἑκάστην ἰδέαν ἀπάρχεσθαι προστάττει, ἀλλὰ καὶ ἀπὸ τῶν οἰκείων ψυχῶν τε καὶ σωμάτων· μέρη γὰρ διαιρετὰ γονέων παῖδές εἰσιν, εἰ δὲ δεῖ τἀληθὲς εἰπεῖν, ἀδιαίρετα, συγγενικῷ αἵματι καὶ λόγοις προγόνων, ἀοράτοις εἴδεσιν, εἰς ἐκγόνους διήκουσι φίλτροις τε ἑνωτικῆς εὐνοίας καὶ φύσεως δεσμοῖς ἀλύτοις ἡρμοσμένοι.", "st": "137"}, {"sp": "N", "t": "ἀλλ’ ὅμως καὶ τούτων τοὺς πρωτοτόκους ἄρρενας τρόπον ἀπαρχῆς καθιεροῖ, χαριστήρια εὐτεκνίας καὶ εὐγονίας οὔσης τε καὶ ἐλπιζομένης, καὶ ἅμα βουλόμενος οὐ μόνον ἀμέμπτους ἀλλὰ καὶ σφόδρα ἐπαινετοὺς εἶναι τοὺς γάμους, ἐξ ὧν ὁ πρῶτος βλαστήσας καρπὸς καθιεροῦται· ὅπερ χρὴ λογιζομένους καὶ ἄνδρας καὶ γυναῖκας σωφροσύνης καὶ οἰκουρίας καὶ ὁμονοίας περιέχεσθαι καὶ συμπνέοντας ἀλλήλοις ἔν τε λόγῳ καὶ ἔργῳ τὴν λεγομένην κοινωνίαν ἀληθείᾳ παγίως βεβαιοῦσθαι.", "st": "138"}, {"sp": "N", "t": "τῆς δὲ τῶν πρωτοτόκων υἱῶν καθιερώσεως, ὑπὲρ τοῦ μήτε γονεῖς τέκνων μήτε τέκνα γονέων διαζεύγνυσθαι, τιμᾶται τὴν ἀπαρχὴν ἀργυρίῳ ῥητῷ, προστάξας ἴσον εἰσφέρειν καὶ πένητα καὶ πλούσιον, οὐ πρὸς ἀξίωμα τῶν εἰσφερόντων οὐδὲ πρὸς εὐεξίαν καὶ κάλλος τῶν γεννηθέντων ἀπιδών, ἀλλ’ ὅσον δυνατὸν εἰσενεγκεῖν καὶ τῷ λίαν ἀπόρῳ σταθμησάμενος.", "st": "139"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἡ παίδων γένεσις ἐν ἴσῳ καὶ τοῖς λαμπροτάτοις καὶ τοῖς ἀφανεστάτοις εἴωθε συμβαίνειν, ἴσην ἐδικαίωσε καὶ τὴν εἰσφορὰν νομοθετῆσαι", "st": "140"}, {"sp": "N", "t": "στοχασάμενος, ὡς ἔφην, μάλιστα τοῦ πᾶσι δυνατοῦ. μετὰ δὲ ταῦτα καὶ ἄλλον πόρον οὐ βραχὺν ἐπινέμει τοῖς ἱερεῦσιν, ἕκαστον τῶν προσόδων ἀπάρχεσθαι κελεύσας, ἀπό τε σίτου καὶ οἴνου καὶ ἐλαίου καὶ ἔτι θρεμμάτων ἐπιγονῆς κατά τε ποίμνας καὶ βουκόλια καὶ αἰπόλια καὶ τὰς ἄλλας ἀγέλας. ὅση δὲ καὶ τούτων ἐστὶν ἀφθονία, τεκμήραιτ’ ἄν τις ἐκ τῆς περὶ τὸ ἔθνος πολυανθρωπίας.", "st": "141"}, {"sp": "N", "t": "ἐξ ὧν ἁπάντων δῆλόν ἐστιν, ὅτι βασιλέων σεμνότητα καὶ τιμὴν περιάπτει τοῖς ἱερεῦσιν ὁ νόμος· ὡς γοῦν ἡγεμόσι φόρους ἀπὸ παντὸς μέρους κτήσεως δίδοσθαι κελεύει, καὶ δίδονται τὸν ἐναντίον τρόπον ἢ ὃν αἱ πόλεις τοῖς δυνάσταις εἰσφέρουσιν·", "st": "142"}, {"sp": "N", "t": "αἱ μὲν γὰρ ἐξ ἀνάγκης καὶ μόλις, ἐπιστένουσαι, τοὺς ἐκλογεῖς τῶν χρημάτων ὡς κοινοὺς λυμεῶνας ὑποβλεπόμεναι καὶ προφάσεις ἄλλοτε ἀλλοίας σκηπτόμεναι καὶ τῶν προθεσμιῶν ἀλογοῦσαι τὰ ὁρισθέντα τέλη καὶ δασμοὺς κατατιθέασιν·", "st": "143"}, {"sp": "N", "t": "οἱ δ’ ἀπὸ τοῦ ἔθνους [τὰ ἱερατικὰ] γεγηθότες, χαίροντες, τοὺς αἰτοῦντας φθάνοντες, τὰς προθεσμίας ἐπιτέμνοντες, λαμβάνειν ἀλλ’ οὐ διδόναι νομίζοντες, μετ’ εὐφημίας καὶ εὐχαριστίας καθ’ ἑκάστην τῶν ἐτησίων ὡρῶν ποιοῦνται τὰς εἰσφοράς, ἄνδρες ὁμοῦ καὶ γυναῖκες, αὐτοκελεύστῳ προθυμίᾳ καὶ ἑτοιμότητι καὶ σπουδῇ παντὸς λόγου κρείττονι.", "st": "144"}, {"sp": "N", "t": "Καὶ ταῦτα μὲν ἀπὸ τῆς ἑκάστου κτήσεως ἐπινέμεται· ἄλλαι δέ εἰσιν ἐξαίρετοι πρόσοδοι πρεπωδέσταται ἱερεῦσιν αἱ ἀπὸ τῶν ἀναγομένων θυσιῶν. παντὸς γὰρ ἱερείου προστέτακται δύο τοῖς ἱερεῦσιν ἀπὸ δυεῖν δίδοσθαι μελῶν, βραχίονα μὲν ἀπὸ χειρὸς δεξιᾶς, ἀπὸ δὲ τοῦ στήθους ὅσον πῖον, τὸ μὲν ἰσχύος καὶ ἀνδρείας καὶ πάσης νομίμου πράξεως ἔν τε τῷ διδόναι καὶ λαμβάνειν καὶ ἐνεργεῖν σύμβολον, τὸ δὲ τῆς περὶ τὸν θυμὸν ἵλεω πραότητος.", "st": "145"}, {"sp": "N", "t": "ἐνοικεῖν γὰρ αὐτὸν λόγος ἔχει τοῖς στήθεσιν, ἐπειδὴ χωρίον οἰκειότατον ἡ φύσις ἀπένειμε τὰ στέρνα θυμῷ πρὸς ἐνδιαίτησιν, ᾧ καθάπερ στρατιώτῃ περιέβαλεν εἰς τὸ δυσάλωτον ἕρκος ὀχυρώτατον, τὸν ἐπικαλούμενον θώρακα, ὃν ἐκ πολλῶν καὶ συνεχῶν καὶ κραταιοτάτων ὀστέων ἀπειργάσατο σφίγξας αὐτὸν εὖ μάλα νεύροις ἀρραγέσιν.", "st": "146"}, {"sp": "N", "t": "ἀπὸ δὲ τῶν ἔξω τοῦ βωμοῦ θυομένων ἕνεκα κρεωφαγίας τρία προστέτακται τῷ ἱερεῖ δίδοσθαι, βραχίονα καὶ σιαγόνας καὶ τὸ ἔνυστρον καλούμενον, τὸν μὲν βραχίονα διὰ τὴν ὀλίγῳ πρότερον εἰρημένην αἰτίαν, τὰς δὲ σιαγόνας τοῦ τε κυριωτάτου τῶν μελῶν, κεφαλῆς, καὶ λόγου τοῦ κατὰ προφορὰν ἀπαρχήν, οὗ τὸ νᾶμα ῥεῖν ἔξω δίχα τῆς τούτων κινήσεως οὐκ ἂν δύναιτο· σειομένων γὰρ—ἀφ’ οὗ καὶ προσωνομάσθησαν ἐτύμως—ὅταν πληχθῶσιν ὑπὸ γλώττης, ἅπασα ἡ τῆς φωνῆς ὀργανοποιΐα συνηχεῖ.", "st": "147"}, {"sp": "N", "t": "τὸ δὲ ἔνυστρον ἔκφυσις κοιλίας ἐστί· κοιλίαν δὲ φάτνην ἀλόγου θρέμματος, ἐπιθυμίας, εἶναι συμβέβηκεν, ἥτις ὑπ’ οἰνοφλυγίας καὶ ὀψοφαγίας ἀρδομένη τροφαῖς ἐπαλλήλοις σιτίων ὁμοῦ καὶ ποτῶν ἀεὶ κατακλύζεται καὶ συὸς τρόπον ἐν βορβόρῳ διαιτωμένη χαίρει· παρὸ καὶ τόπος ἀπενεμήθη σφόδρα οἰκειότατος ὁ τῶν περιττωμάτων ἀκολάστῳ καὶ ἀπρεπεστάτῳ θρέμματι.", "st": "148"}, {"sp": "N", "t": "ἀντίπαλον δὲ ἐπιθυμίας ἐγκράτεια, ἣν ἀσκητέον καὶ διαπονητέον καὶ σπουδαστέον μηχανῇ πάσῃ περιποιεῖσθαι ὡς μέγιστον ἀγαθὸν καὶ τελειότατον ἰδίᾳ τε καὶ κοινῇ συμφέρον.", "st": "149"}, {"sp": "N", "t": "ἐπιθυμία μὲν οὖν βέβηλος καὶ ἀκάθαρτος καὶ ἀνίερος οὖσα πέρα τῶν ἀρετῆς ὅρων ἐλήλαται καὶ πεφυγάδευται δεόντως· ἐγκράτεια δέ, καθαρὰ καὶ ἀκηλίδωτος ἀρετή, πάντων ὅσα πρὸς βρῶσιν καὶ πόσιν ἀλογοῦσα καὶ ἐπάνω τῶν γαστρὸς ἡδονῶν αὐχοῦσα ἵστασθαι, βωμῶν ἱερῶν ψαυέτω καὶ τὴν πρόσφυσιν ἐπιφερομένη τῆς κοιλίας, ὑπόμνημα τοῦ καταφρονητικῶς ἔχειν ἀπληστίας καὶ λαιμαργίας", "st": "150"}, {"sp": "N", "t": "καὶ πάντων ὅσα τὰ εἰς τὰς ἐπιθυμίας ἀναφλέγει. ἐφ’ ἅπασι μέντοι καὶ τὰς τῶν ὁλοκαυτωμάτων—ἀμύθητα δὲ ταῦτ’ ἐστί—δορὰς προστάττει τοὺς ὑπηρετοῦντας ταῖς θυσίαις ἱερεῖς λαμβάνειν, οὐ βραχεῖαν ἀλλ’ ἐν τοῖς μάλιστα πολυχρήματον δωρεάν. ἐξ ὧν δῆλόν ἐστιν, ὅτι κλῆρον ἕνα μὴ παρασχὼν τῇ ἱερωμένῃ φυλῇ κατὰ ταὐτὰ ταῖς ἄλλαις τοῦ πασῶν ἔδωκε σεμνότερον πόρον καὶ ἁγιώτερον, κατὰ πρόφασιν ἀπαρχῶν τῶν ἐξ ἅπαντος θυσίας εἴδους.", "st": "151"}, {"sp": "N", "t": "ὑπὲρ δὲ τοῦ μηδένα τῶν διδόντων ὀνειδίζειν τοῖς λαμβάνουσι, κελεύει τὰς ἀπαρχὰς εἰς τὸ ἱερὸν κομίζεσθαι πρότερον, εἶτ’ ἐνθένδε τοὺς ἱερεῖς λαμβάνειν· ἥρμοττε γὰρ θεῷ μὲν τοὺς εὐεργετουμένους ἐν ἅπασι τοῖς κατὰ τὸν βίον χαριστηρίους ἀνάγειν ἀπαρχάς, τὸν δὲ ἅτε μηδενὸς ἐπιδεᾶ τοῖς ἀμφὶ τὸ ἱερὸν ὑπηρέταις καὶ λειτουργοῖς χαρίζεσθαι μετὰ σεμνότητος καὶ τιμῆς τῆς ἁπάσης· τὸ γὰρ μὴ παρ’ ἀνθρώπων ἀλλὰ παρὰ τοῦ πάντων εὐεργέτου δοκεῖν λαμβάνειν ἀδυσώπητον ἔχει δωρεάν.", "st": "152"}, {"sp": "N", "t": "Τοσούτων οὖν προκειμένων ἄθλων, ἐάν τινες ἀπορῶσι τῶν ἱερέων κοσμίως καὶ ἀνυπαιτίως ζῶντες, τῆς ἡμετέρας παρανομίας ἐφεστᾶσι κατήγοροι, κἂν ἡσυχάζωσιν· εἰ γὰρ ἐπειθαρχοῦμεν τοῖς κελευσθεῖσι καὶ τὰς ἀπαρχὰς ἐποιούμεθα ᾗ προστέτακται, οὐκ ἂν μόνον ἐκεῖνοι τῶν ἀναγκαίων εὐπόρουν, ἀλλὰ καὶ τῶν ἄλλων ὅσα πρὸς ἁβροδιαίτους χορηγίας ἀνεπίμπλαντο.", "st": "153"}, {"sp": "N", "t": "κἂν ἄρα ποτὲ αὖθις ἡ φυλὴ τῶν ἱερέων ἐν ἅπασι τοῖς κατὰ τὸν βίον ἀφθόνοις ἐξετάζηται, μέγα δεῖγμα γενήσεται τοῦτο κοινῆς ὁσιότητος καὶ τῆς τῶν νομίμων ἐπ’ ἀκριβὲς εἰς ἅπαν φυλακῆς. ἀλλ’ ἥ τινων ὀλιγωρία—ἅπαντας γὰρ οὐκ ἀσφαλὲς αἰτιᾶσθαι—γέγονεν αἰτία πενίας τοῖς ἱερωμένοις, εἰ δὲ δεῖ τἀληθὲς εἰπεῖν, καὶ αὐτοῖς ἐκείνοις.", "st": "154"}, {"sp": "N", "t": "τὸ γὰρ παρανομεῖν ἐπιζήμιον τοῖς παρανομοῦσι, κἂν πρὸς ὀλίγον δελεάζῃ χρόνον· τὸ δὲ ἕπεσθαι τοῖς τῆς φύσεως νόμοις ὠφελιμώτατον, κἂν παραυτίκα αὐστηρὸν ᾖ καὶ μηδὲν προσηνὲς ἐμφαίνῃ.", "st": "155"}, {"sp": "N", "t": "Τοσαύτας προσόδων ἀφορμὰς χαρισάμενος τοῖς ἱερεῦσιν οὐδὲ τῶν ἐν τῇ δευτέρᾳ τάξει κατωλιγώρησεν· εἰσὶ δὲ νεωκόροι. τούτων οἱ μὲν ἐπὶ θύραις ἵδρυνται παρ’ αὐταῖς ταῖς εἰσόδοις πυλωροί, οἱ δ’ εἴσω κατὰ τὸ πρόναον ὑπὲρ τοῦ μή τινα ὧν οὐ θέμις ἑκόντα ἢ καὶ ἄκοντα ἐπιβῆναι, οἱ δ’ ἐν κύκλῳ περινοστοῦσιν ἐν μέρει διακληρωσάμενοι νύκτα καὶ ἡμέραν, ἡμεροφύλακες καὶ νυκτοφύλακες, ἕτεροι δὲ τὰς στοὰς καὶ τὰ ἐν ὑπαίθρῳ κοροῦντες τὸν φορυτὸν ἐκκομίζουσιν ἐπιμελούμενοι καθαριότητος· οἷς ἅπασι μισθὸς ὡρίσθησαν αἱ δεκάται, κλῆρος γὰρ νεωκόρων οὗτος.", "st": "156"}, {"sp": "N", "t": "οὐ πρότερον γοῦν εἴασεν ὁ νόμος αὐταῖς χρῆσθαι τοὺς λαβόντας ἢ πάλιν ἄλλας δεκάτας ὡς ἀπὸ κτημάτων ἰδίων ἀπάρξασθαι καὶ δοῦναι τοῖς τῆς ἀμείνονος τάξεως ἱερεῦσι· τηνικαῦτα γὰρ ἐφῆκεν ἀπολαύειν, πρότερον δ’ οὐκ ἐᾷ.", "st": "157"}, {"sp": "N", "t": "ἀπένειμε δὲ καὶ πόλεις αὐτοῖς ὀκτὼ πρὸς ταῖς τεσσαράκοντα καὶ καθ’ ἑκάστην προάστεια εἰς δισχιλίους πήχεις ἐν κύκλῳ πρὸς νομὰς θρεμμάτων καὶ τὰς ἄλλας ὧν δεῖ πόλεσιν ἀναγκαίας ὑπηρεσίας. ἐκ δὲ τούτων ἀπεκληρώθησαν ἕξ, αἱ μὲν ἐκτὸς αἱ δὲ ἐντὸς Ἰορδάνου τοῦ ποταμοῦ, τρεῖς ἑκατέρωθεν, εἰς καταφυγὴν τοῖς ἀκούσιον φόνον δράσασιν.", "st": "158"}, {"sp": "N", "t": "ἐπειδὴ γὰρ τὸν ὁπωσοῦν γενόμενον ἀνθρώπῳ τελευτῆς παραίτιον οὐκ ἦν εὐαγὲς εἴσω περιρραντηρίων παρέρχεσθαι χρώμενον πρὸς ἀσφάλειαν καταφυγῇ τῷ ἱερῷ, τὰς εἰρημένας ἀνῆκε πόλεις, ἱερὰ δεύτερα, πολλὴν ἀσυλίαν ἐχούσας ἕνεκα τῆς περὶ τοὺς οἰκήτορας προνομίας τε καὶ τιμῆς, οἳ τοὺς ἱκέτας διασῴζειν ἔμελλον, εἰ βιάζοιτό τις ἐχυρωτέρα δύναμις, οὐ παρασκευαῖς ταῖς εἰς πόλεμον οὔσαις, ἀλλ’ ἀξιώμασι καὶ προνομίαις, ἅπερ ἐκ τῶν νόμων διὰ τὴν σεμνότητα τῆς ἱερωσύνης εἶχον.", "st": "159"}, {"sp": "N", "t": "ὁ δὲ φυγὰς ἐντὸς ὅρων τῆς πόλεως, εἰς ἣν πεφυγάδευται, κατακεκλείσθω διὰ τοὺς ἐφέδρους κολαστάς, οἳ γένει προσήκοντες τῷ τεθνεῶτι πόθῳ τοῦ συγγενοῦς, κἂν μὴ ὑφ’ ἑκόντος ἀναιρεθῇ, κατὰ τοῦ κτείναντος φονῶσι, νικῶντος τοῦ οἰκείου πάθους τὸν ἀκριβῆ τῶν δικαίων λογισμόν. ἔξω δὲ προϊὼν ἐπ’ ὀλέθρῳ ἀνενδοιάστῳ προελευσόμενος ἴστω· λήσεται γὰρ οὐδένα τῶν ἀφ’ αἵματος, ὑφ’ ὧν αὐτίκα λίνοις καὶ πάγαις σαγηνευθεὶς οἰχήσεται.", "st": "160"}, {"sp": "N", "t": "προθεσμία δ’ ἔστω τῆς φυγῆς ὁ βίος τοῦ μεγάλου ἱερέως, οὗ τελευτήσαντος ἀμνηστίας ἀξιωθεὶς κατίτω. ταῦτα καὶ τὰ τούτοις παραπλήσια νομοθετήσας περὶ τῶν ἱερέων ἑξῆς ἀναδιδάσκει περὶ ζῴων, ἃ πρὸς θυσίας ἐστὶν ἐπιτήδεια.", "st": "161"}, {"sp": "N", "t": "Τῶν εἰς τὰς ἱερουργίας ζῴων τὰ μέν ἐστι χερσαῖα, τὰ δὲ ἀεροπόρα. τὰ μὲν οὖν τῶν πτηνῶν ἔθνη μυρία ὅσα παρελθὼν δύο μόνα ἐξ ἁπάντων εἵλετο, περιστερὰν καὶ τρυγόνα, διότι περιστερὰ μὲν τῶν φύσει τιθασῶν καὶ ἀγελαστικῶν ἡμερώτατον, τρυγὼν δὲ τῶν φύσει μονωτικῶν τιθασώτατον.", "st": "162"}, {"sp": "N", "t": "τὰς δὲ τῶν χερσαίων ἀμυθήτους ἀγέλας, ὧν οὐδ’ ἀριθμὸν εὑρεῖν εὔπορον, ὑπερβὰς τρεῖς ἀριστίνδην ἐπέκρινε, βοῶν καὶ προβάτων καὶ αἰγῶν· ἡμερώταται γὰρ αὗται καὶ χειροηθέσταται· βουκόλια γοῦν μεγάλα καὶ ποίμνια καὶ αἰπόλια πρὸς ἑνὸς ἄγεται τοῦ τυχόντος, οὐκ ἀνδρὸς μόνον ἀλλὰ καὶ κομιδῇ νηπίου παιδός, εἴς τε νομὴν ἐξιόντα καὶ ὁπότε δέοι πάλιν εἰς σηκοὺς ὑποστρέφοντα ἐν κόσμῳ.", "st": "163"}, {"sp": "N", "t": "τῆς δ’ ἡμερότητος πολλὰ μὲν καὶ ἄλλα σημεῖα, σαφέστατα δὲ ταυτί· τό τε πάντα εἶναι χλοηφάγα καὶ μηδὲν αὐτῶν σαρκοβόρον καὶ τὸ μήτε γαμψοὺς ἔχειν ὄνυχας μήτε τὴν ἔκφυσιν τῶν ὀδόντων παντελῆ· τὸ γὰρ ἀνωτέρω φάτνιον οὐκ ὀδοντοφυεῖ, ἀλλ’ ὅσοι τομίαι τῶν ὀδόντων κατ’ αὐτὸ ἐπιλελοίπασι.", "st": "164"}, {"sp": "N", "t": "πρὸς δὲ τούτοις καὶ βιωφελέστατα τῶν ζῴων ἐστί· κριοὶ μὲν εἰς ἐσθῆτας, τὴν ἀναγκαιοτάτην σκέπην σωμάτων, βόες δὲ εἰς τὸ ἀρόσαι γῆν καὶ προετοιμάσασθαι πρὸς σπόρον καὶ τὸν γενόμενον ἀλοῆσαι καρπὸν εἰς μετουσίαν καὶ ἀπόλαυσιν τροφῆς, αἰγῶν δὲ αἱ τρίχες καὶ δοραὶ συνυφαινόμεναί τε καὶ συρραπτόμεναι φορηταὶ γεγόνασιν ὁδοιπόροις οἰκίαι καὶ μάλιστα τοῖς ἐν στρατείαις, οὓς ἔξω πόλεως ἐν ὑπαίθρῳ τὰ πολλὰ διατρίβειν ἀναγκάζουσιν αἱ χρεῖαι.", "st": "165"}, {"sp": "N", "t": "πάντα δ’ ὁλόκληρα, περὶ μηδὲν μέρος κηραίνοντα τοῦ σώματος, ὅλα δι’ ὅλων ἀσινῆ, μώμων ἀμέτοχα· τοσαύτη γοῦν ἐστι πρόνοια, οὐ μόνον τοῖς ἀνάγουσι τὰς θυσίας ἀλλὰ καὶ τοῖς ἱερωμένοις, ὥστε οἱ δοκιμώτατοι τῶν ἱερέων ἀριστίνδην ἐπικριθέντες εἰς τὴν τῶν μώμων ἐπίσκεψιν ἀπὸ κεφαλῆς ἄχρι ποδῶν ἄκρων ἐρευνῶσιν ὅσα τε ἐμφανῆ καὶ ὅσα ὑπὸ γαστρὶ καὶ μηροῖς ἀποκέκρυπται, μή που τις βραχεῖα λώβη διαλέληθε.", "st": "166"}, {"sp": "N", "t": "τὸ δ’ ἀκριβὲς καὶ περιττὸν τῆς ἐξετάσεως οὐχ ἕνεκα τῶν καταθυομένων ἀλλὰ τοῦ περὶ τοὺς καταθύοντας ἀνυπαιτίου γίνεται· βούλεται γὰρ αὐτοὺς ἀναδιδάξαι διὰ συμβόλων, ὁπότε προσέρχοιντο βωμοῖς ἢ εὐξόμενοι ἢ εὐχαριστήσοντες, μηδὲν ἀρρώστημα ἢ νόσημα ἢ πάθος ἐπιφέρεσθαι τῇ ψυχῇ, πειρᾶσθαι δ’ ὅλην δι’ ὅλων ἀκηλίδωτον ἁγιάζειν, ὡς ἰδόντα μὴ ἀποστραφῆναι θεόν.", "st": "167"}, {"sp": "N", "t": "Ἐπεὶ δὲ τῶν θυσιῶν αἱ μέν εἰσιν ὑπὲρ ἅπαντος τοῦ ἔθνους, εἰ δὲ δεῖ τἀληθὲς εἰπεῖν, ὑπὲρ ἅπαντος ἀνθρώπων γένους, αἱ δ’ ὑπὲρ ἑκάστου τῶν ἱερουργεῖν ἀξιούντων, λεκτέον πρότερον περὶ τῶν κοινῶν. θαυμαστὴ τούτων ἡ τάξις ἐστίν· αἱ μὲν γὰρ ἀνάγονται καθ’ ἑκάστην ἡμέραν, αἱ δὲ ταῖς ἑβδόμαις, αἱ δὲ νουμηνίαις καὶ ἱερομηνίαις, αἱ δὲ νηστείαις, αἱ δὲ τρισὶ καιροῖς ἑορτῶν.", "st": "168"}, {"sp": "N", "t": "καθ’ ἑκάστην μὲν οὖν ἡμέραν δύο ἀμνοὺς ἀνάγειν διείρηται, τὸν μὲν ἅμα τῇ ἕῳ, τὸν δὲ δείλης ἑσπέρας, ὑπὲρ εὐχαριστίας ἑκάτερον, τὸν μὲν ὑπὲρ τῶν μεθ’ ἡμέραν, τὸν δ’ ὑπὲρ τῶν νύκτωρ εὐεργεσιῶν, ἃς ἀπαύστως καὶ ἀδιαστάτως ὁ θεὸς τῷ γένει τῶν ἀνθρώπων χορηγεῖ.", "st": "169"}, {"sp": "N", "t": "ταῖς δ’ ἑβδόμαις διπλασιάζει τὸν τῶν ἱερείων ἀριθμόν, ἴσα προστιθεὶς ἴσοις, ἰσότιμον ἡγούμενος αἰῶνι τὴν ἑβδόμην, ἣν καὶ γενέθλιον τοῦ κόσμου παντὸς ἀνέγραψεν· οὗ χάριν τὴν τῆς ἑβδόμης θυσίαν ἐξομοιῶσαι τῇ “ἐνδελεχείᾳ” τῶν ἡμερησίων ἀμνῶν διενοήθη.", "st": "170"}, {"sp": "N", "t": "δὶς δὲ καθ’ ἑκάστην ἡμέραν ἐπιθυμιᾶται τὰ πάντων εὐωδέστατα θυμιαμάτων εἴσω τοῦ καταπετάσματος, ἀνίσχοντος ἡλίου καὶ δυομένου, πρό τε τῆς ἑωθινῆς θυσίας καὶ μετὰ τὴν ἑσπερινήν, ὡς εἶναι τὰ μὲν ἔναιμα εὐχαριστίαν ὑπὲρ ἡμῶν τῶν ἐναίμων, τὰ δὲ θυμιάματα ὑπὲρ τοῦ ἡγεμονικοῦ, τοῦ ἐν ἡμῖν λογικοῦ πνεύματος, ὅπερ ἐμορφώθη πρὸς ἀρχέτυπον ἰδέαν εἰκόνος θείας.", "st": "171"}, {"sp": "N", "t": "ἄρτοι δὲ προτίθενται ταῖς ἑβδόμαις ἐπὶ τῆς ἱερᾶς τραπέζης ἰσάριθμοι τοῖς μησὶ τοῦ ἐνιαυτοῦ, δυσὶ θέμασιν ἀνὰ ἕξ, [δώδεκα,] κατὰ τὸν λόγον τῶν ἰσημεριῶν ἑκάτερα —δύο γάρ εἰσιν ἀνὰ πᾶν ἔτος, ἐαρινή τε καὶ μετοπωρινή, αἳ μησὶν ἓξ καταριθμοῦνται —· δι’ ἣν αἰτίαν * * * ἐαρινῇ μὲν τὰ σπαρτὰ πάντα τελειογονεῖται, καθ’ ὃν χρόνον τὰ δένδρα γεννᾶν ἄρχεται, μετοπωρινῇ δὲ καὶ ὁ τῶν δένδρων καρπὸς τελεσφορεῖται, ἐν ᾧ καιρῷ πάλιν ἀρχὴ σπορᾶς. οὕτως δολιχεύουσα ἡ φύσις τὸν αἰῶνα ἄλλας ἐπ’ ἄλλαις ἀμείβει δωρεὰς ἀνθρώπων γένει, ὧν εἰσι σύμβολα αἱ διτταὶ τῶν προκειμένων ἄρτων ἑξάδες.", "st": "172"}, {"sp": "N", "t": "αἰνίττονται δὲ καὶ τὴν ὠφελιμωτάτην τῶν ἀρετῶν ἐγκράτειαν, ἣ δορυφορεῖται πρὸς εὐτελείας καὶ εὐκολίας καὶ ὀλιγοδεΐας, διὰ τὸν ἐξ ἀκολασίας καὶ πλεονεξίας βλαβερώτατον ἐπιτειχισμόν· ἄρτος γὰρ ἐραστῇ σοφίας διαρκὴς τροφή, παρέχουσα καὶ τὰ σώματα ἄνοσα καὶ τὸν λογισμὸν ὑγιῆ καὶ ἐν τοῖς μάλιστα νηφάλιον·", "st": "173"}, {"sp": "N", "t": "ὄψα δὲ καὶ μελίπηκτα καὶ ἡδύσματα καὶ ὅσα σιτοπόνων καὶ ὀψαρτυτῶν περιεργίαι τεχνιτεύουσι καταγοητεύουσαι τὴν ἄμουσον καὶ ἀφιλόσοφον καὶ ἀνδραποδωδεστάτην τῶν αἰσθήσεων γεῦσιν, ὑπηρετοῦσαν καλῷ μὲν οὐδενὶ θεάματι ἢ ἀκούσματι, γαστρὸς δὲ τῆς ταλαίνης ἐπιθυμίαις, νόσους σώματι καὶ ψυχῇ κατασκευάζει πολλάκις ἀνιάτους.", "st": "174"}, {"sp": "N", "t": "συνεπιτίθεται δὲ τοῖς ἄρτοις λιβανωτὸς καὶ ἅλες, ὁ μὲν σύμβολον τοῦ μηδὲν ἥδυσμα εὐωδέστερον ὀλιγοδεΐας εἶναι καὶ ἐγκρατείας παρὰ σοφίᾳ δικαζούσῃ, οἱ δ’ ἅλες διαμονῆς τε τῶν συμπάντων—οἷς γὰρ ἂν παραπασθῶσι διατηροῦσι —καὶ ἱκανοῦ προσοψήματος.", "st": "175"}, {"sp": "N", "t": "οἶδ’ ὅτι γέλωτα καὶ χλεύην ταῦτα θήσονται οἱ περὶ τὰ συμπόσια καὶ τὰς εὐωχίας πραγματευόμενοι καὶ πολυτελεῖς τραπέζας μεταδιώκοντες, οἱ ὀρνέων καὶ ἰχθύων καὶ κρεῶν καὶ τῆς ὁμοιοτρόπου φλυαρίας ἄθλιοι δοῦλοι, μηδ’ ὄναρ ἀληθοῦς ἐλευθερίας γεύσασθαι δυνάμενοι. ὧν ὀλίγα φροντιστέον τοῖς κατὰ θεὸν καὶ πρὸς τὴν τοῦ ὄντως ὄντος ἀρέσκειαν ζῆν ἐγνωκόσιν, οἳ τῶν σαρκὸς ἀλογεῖν ἡδονῶν πεπαιδευμένοι τὰς διανοίας χαρὰς καὶ εὐπαθείας θεωρίᾳ τῶν τῆς φύσεως ἐνασκούμενοι μεταδιώκουσι.", "st": "176"}, {"sp": "N", "t": "Ταῦτα περὶ τῆς ἑβδόμης διαταξάμενος ταῖς νουμηνίαις φησὶ δεῖν θύειν ὁλόκαυτα δέκα τὰ σύμπαντα· μόσχους δύο, κριὸν ἕνα, ἀμνοὺς ἑπτά. ἐπειδὴ γὰρ ὁ μὴν τέλειος, ἐν ᾧ σελήνη τὸν ἑαυτῆς κύκλον περατοῦται, τέλειον ἀριθμὸν ζῴων ἠξίωσεν ἱερουργεῖσθαι.", "st": "177"}, {"sp": "N", "t": "ἡ δεκὰς δὲ παντελὴς ἀριθμός, ὃν εὖ μάλα διένειμεν εἰς τὰ λεχθέντα, τοὺς μὲν δύο μόσχους, ἐπειδὴ δύο κινήσεις εἰσὶ σελήνης ἀεὶ διαυλοδρομούσης, ἡ μὲν κατ’ αὔξησιν ἄχρι πλησιφαοῦς, ἡ δὲ κατὰ μείωσιν ἄχρι συνόδου, τὸν δ’ ἕνα κριόν, ἐπειδὴ λόγος εἷς ἐστι, καθ’ ὃν αὔξεταί τε καὶ μειοῦται τοῖς ἴσοις διαστήμασι καὶ φωτιζομένη καὶ ἐπιλείπουσα, τοὺς δὲ ἑπτὰ ἀμνούς, ὅτι καθ’ ἑβδομάδας ἐπιδέχεται τοὺς τελείους σχηματισμούς, πρώτῃ μὲν ἑβδομάδι τῇ ἀπὸ συνόδου τὸν διχότομον, δευτέρᾳ δὲ τὸν πλησιφαῆ, καὶ ὅταν ἀνακάμπτῃ πάλιν, εἰς διχότομον τὸ πρῶτον, ἔπειτ’ εἰς σύνοδον ἀπολήγει.", "st": "178"}, {"sp": "N", "t": "μετὰ δὲ τῶν ἱερείων σεμίδαλιν ἀναδεδευμένην ἐλαίῳ προσφέρειν καὶ οἶνον εἰς σπονδὰς μέτροις ὡρισμένοις διετάξατο, διότι καὶ ταῦτα σελήνης περιόδοις κατὰ τὰς ἐτησίους ὥρας τελεσφορεῖται διαφερόντως τοὺς καρποὺς πεπαινούσης, σῖτος δὲ καὶ οἶνος καὶ ἔλαιον, βιωφελέσταται οὐσίαι καὶ πρὸς χρῆσιν ἀνθρώποις ἀναγκαιόταται, πάσαις εἰκότως θυσίαις συγκαθιεροῦνται.", "st": "179"}, {"sp": "N", "t": "Τῇ δ’ ἱερομηνίᾳ διττὰ θύματα προσάγεται προσηκόντως, ἐπεὶ καὶ διττὸς ὁ περὶ αὐτῆς λόγος, ὁ μὲν ὡς νουμηνίας, ὁ δὲ ὡς ἱερομηνίας. ᾗ μὲν οὖν νουμηνία, τὰ ἴσα ταῖς ἄλλαις ἱερουργεῖσθαι διείρηται, ᾗ δὲ καὶ ἱερομηνία, διπλασιάζεται τὰ δῶρα, δίχα τῶν μόσχων· εἷς γὰρ ἀντὶ δυεῖν προσάγεται, τοῦ βραβευτοῦ δικαιώσαντος ἀδιαιρέτῳ φύσει μονάδος πρὸ διαιρετῆς δυάδος χρήσασθαι ἐν ἀρχῇ τοῦ ἐνιαυτοῦ.", "st": "180"}, {"sp": "N", "t": "Ἐν δὲ τῷ πρώτῳ καιρῷ—πρῶτον δὲ καιρὸν τὴν ἐαρινὴν ὥραν καὶ ἰσημερίαν καλεῖ—προστάξας ἑπτὰ ἡμέρας ἑορτὴν ἄγειν τὴν ἐπικαλουμένην τῶν ἀζύμων ἰσοτίμους ἀπέφηνε πάσας ἐν ταῖς ἱερουργίαις· δέκα γὰρ ὅσα καὶ ταῖς νουμηνίαις θύειν καθ’ ἑκάστην κελεύει, τὰ σύμπαντα ὁλόκαυτα, δίχα τῶν περὶ πλημμελείας, ἀριθμὸν ἑβδομήκοντα.", "st": "181"}, {"sp": "N", "t": "τὸν γὰρ αὐτὸν ἔχειν ᾠήθη λόγον πρὸς μῆνα νουμηνίαν ὃν πρὸς ἰσημερίαν ἑβδόμῳ μηνὶ γινομένην τὰς ἑπτὰ τῆς ἑορτῆς ἡμέρας, ἵν’ ἀποφήνῃ καὶ τὴν ἀρχὴν ἑκάστου μηνὸς ἱερὰν καὶ ἀθρόων τῶν ἑπτὰ τὰς ἰσαρίθμους ταῖς νουμηνίαις ἡμέρας.", "st": "182"}, {"sp": "N", "t": "Μεσοῦντος δὲ ἔαρος ἄμητος ἐνίσταται, καθ’ ὃν καιρὸν χαριστήρια μὲν ἀνάγεται τῷ θεῷ τῆς πεδιάδος ἐπὶ τῷ πλήρη τὸν καρπὸν ἐνηνοχέναι καὶ τὰ θέρη συγκομίζεσθαι, δημοτελεστάτη δ’ ἄγεται ἑορτὴ προσαγορευομένη πρωτογεννημάτων ἐτύμως ἀπὸ τοῦ συμβεβηκότος, ἐπειδὴ τῶν γεννημάτων τὰ πρῶτα, αἱ ἀπαρχαί, τότε καθιεροῦνται.", "st": "183"}, {"sp": "N", "t": "προστέτακται δ’ ἀνάγειν θυσίας μόσχους δύο, κριὸν ἕνα καὶ ἑπτὰ ἀμνούς, ταῦτα μὲν δέκα ἱερεῖα ὁλόκαυτα, δύο δ’ ἀμνοὺς εἰς βρῶσιν ἱερέων, οὓς ἐπικαλεῖ σωτηρίου διὰ τὸ τὰς τροφὰς ἀνθρώποις ἐκ πολλῶν καὶ παντοδαπῶν διασεσῶσθαι· φθοραὶ γὰρ εἰώθασι καταλαμβάνειν, αἱ μὲν ἐπομβρίαις, αἱ δ’ αὐχμοῖς, αἱ δ’ ἄλλαις ἀμυθήτοις νεωτεροποιΐαις, αἱ δ’ αὖ χειροποίητοι κατ’ ἐφόδους ἐχθρῶν τὴν τῶν πέλας γῆν δῃοῦν ἐπιχειρούντων.", "st": "184"}, {"sp": "N", "t": "εἰκότως οὖν τὰ σῶστρα τῷ πάσας ἀποσκεδάσαντι τὰς ἐπιβουλὰς ἀνάγεται χαριστήρια καὶ ἀνάγεται ἄρτοις, οὓς προσενεγκόντες τῷ βωμῷ καὶ ἄνω πρὸς οὐρανὸν ἀνατείναντες ἐπιδιανέμουσι τοῖς ἱερεῦσι μετὰ τῶν κρεῶν τῆς τοῦ σωτηρίου θυσίας εἰς ἱεροπρεπεστάτην εὐωχίαν.", "st": "185"}, {"sp": "N", "t": "Ὅταν δ’ ὁ τρίτος ἐνστῇ καιρὸς ἐν τῷ ἑβδόμῳ μηνὶ κατ’ ἰσημερίαν μετοπωρινήν, ἐν ἀρχῇ μὲν ἱερομηνία ἄγεται προσαγορευομένη σαλπίγγων, περὶ ἧς ἐλέχθη πρότερον, δεκάτῃ δ’ ἡ νηστεία, περὶ ἣν ἐσπουδάκασιν οὐ μόνον οἷς ζῆλος εὐσεβείας καὶ ὁσιότητος, ἀλλὰ καὶ οἷς κατὰ τὸν ἄλλον βίον εὐαγὲς οὐδὲν δρᾶται· πάντες γὰρ ἡττώμενοι τοῦ περὶ αὐτὴν ἱεροπρεποῦς τεθήπασι καὶ οἱ χείρους τοῖς βελτίοσι τότε γοῦν εἰς ἐγκράτειαν καὶ ἀρετὴν ἁμιλλῶνται.", "st": "186"}, {"sp": "N", "t": "διττοὺς δ’ ἔχει λόγους τὸ ἀξίωμα τῆς ἡμέρας, τοὺς μὲν ὡς ἑορτῆς, τοὺς δὲ ὡς καθάρσεως καὶ φυγῆς ἁμαρτημάτων, ἐφ’ οἷς ἀμνηστία δέδοται χάρισι τοῦ ἵλεω θεοῦ μετάνοιαν ἐν ἴσῳ τῷ μηδὲ ἁμαρτάνειν τετιμηκότος.", "st": "187"}, {"sp": "N", "t": "τὰς μὲν οὖν ὡς ἑορτῆς θυσίας ἰσαρίθμους ἀπέφηνε ταῖς τῶν ἱερομηνιῶν, μόσχον καὶ κριὸν καὶ ἑπτὰ ἄρνας, ἀνακερασάμενος μονάδα ἑβδομάδι καὶ πρὸς ἀρχὴν τὸ τέλος ἀπευθύνας—τέλος μὲν γὰρ ἔργων ἑβδομάς, ἀρχὴν δὲ μονὰς κεκλήρωται —, τὰς δ’ ὡς καθάρσεως τρεῖς· προστάττει γὰρ δύο χιμάρους ἀνάγειν καὶ κριόν, εἶτά φησι δεῖν τὸν μὲν ὁλοκαυτοῦν, διακληροῦν δὲ τοὺς χιμάρους, καὶ τὸν μὲν λαχόντα τῷ θεῷ θύειν, τὸν δ’ ἕτερον εἰς ἀτριβῆ καὶ ἄβατον ἐρημίαν ἐκπέμπειν ἐφ’ ἑαυτῷ κομίζοντα τὰς ὑπὲρ τῶν πλημμελησάντων ἀράς, οἳ μεταβολαῖς ταῖς πρὸς τὸ βέλτιον ἐκαθάρθησαν, εὐνομίᾳ καινῇ παλαιὰν ἀνομίαν ἐκνιψάμενοι.", "st": "188"}, {"sp": "N", "t": "Τῇ δὲ πεντεκαιδεκάτῃ τῆς πλησιφαοῦς σελήνης ἄγεται ἡ ἐπικαλουμένη σκηνῶν ἑορτή, καθ’ ἣν πλείους εἰσὶν αἱ χορηγίαι τῶν θυσιῶν· καταθύονται γὰρ ἐφ’ ἡμέρας ἑπτὰ μόσχοι μὲν ἑβδομήκοντα, κριοὶ δὲ τέσσαρες καὶ δέκα, ἄρνες δὲ δυοῖν δεόντων ἑκατόν, ἅπαντα ζῷα ὁλόκαυτα. προστέτακται δὲ καὶ τὴν ὀγδόην ἱερὰν νομίζειν, περὶ ἧς ἀκριβωτέον, ὅταν σύμπας ὁ περὶ τῶν ἑορτῶν ἐξετάζηται λόγος, ἐν ᾗ προσάγεται ὅσα καὶ ἐν ταῖς ἱερομηνίαις.", "st": "189"}, {"sp": "N", "t": "Αἱ μὲν οὖν ὑπὲρ τοῦ ἔθνους ἢ κυριώτερον εἰπεῖν ὑπὲρ παντὸς ἀνθρώπων γένους κοιναὶ καὶ ὁλόκαυτοι θυσίαι κατ’ ἐμὴν δύναμιν εἴρηνται. ταῖς δ’ ὁλοκαύτοις καθ’ ἑκάστην ἡμέραν ἑορτῆς παρέπεται χίμαρος, ὃς καλεῖται μὲν περὶ ἁμαρτίας, καταθύεται δὲ εἰς ἁμαρτημάτων ἄφεσιν, οὗ τὰ κρέα τοῖς ἱερεῦσιν εἰς ἐδωδὴν ἀπονέμεται. τίς οὖν αἰτία;", "st": "190"}, {"sp": "N", "t": "ἢ ὅτι ἑορτὴ καιρός ἐστιν εὐφροσύνης, ἡ δ’ ἀψευδὴς καὶ πρὸς ἀλήθειαν εὐφροσύνη φρόνησίς ἐστιν ἐνιδρυμένη ψυχῇ βεβαίως, φρόνησιν δ’ ἀκλινῆ λαβεῖν οὐκ ἔνεστιν ἄνευ θεραπείας ἁμαρτημάτων καὶ παθῶν ἐκτομῆς; ἄτοπον γὰρ ἕκαστον μὲν τῶν ὁλοκαυτουμένων ἀσινὲς καὶ ἀβλαβὲς ἀνευρισκόμενον καθιεροῦσθαι, τὴν δὲ τοῦ θύοντος διάνοιαν μὴ οὐ κεκαθάρθαι πάντα τρόπον καὶ πεφαιδρύνθαι λουτροῖς καὶ περιρραντηρίοις χρησαμένην, ἅπερ ὁ τῆς φύσεως ὀρθὸς λόγος δι’ ὑγιαινόντων καὶ ἀδιαφθόρων ὤτων ψυχαῖς φιλοθέοις ἐπαντλεῖ.", "st": "191"}, {"sp": "N", "t": "πρὸς δὲ τούτῳ κἀκεῖνο δεόντως ἂν λέγοιτο· αἱ ἑορτώδεις ἀνέσεις αὗται καὶ ἐκεχειρίαι μυρίας ἤδη πολλάκις ἁμαρτημάτων ὁδοὺς ἀνέτεμον· ἄκρατος γὰρ καὶ αἱ μετ’ οἰνοφλυγίας ὀψοφαγίαι τὰς γαστρὸς ἀκορέστους ἐπιθυμίας ἐγείρουσαι προσαναφλέγουσι καὶ τὰς ὑπὸ γαστέρα, καὶ ῥέουσαι καὶ χεόμεναι πάντῃ φορὰν ἀμυθήτων ἀπεργάζονται κακῶν τὸ τῆς ἑορτῆς ἀδεὲς ὁρμητήριον ἔχουσαι καὶ πρὸς τὸ μηδὲν παθεῖν καταφυγήν.", "st": "192"}, {"sp": "N", "t": "ἅπερ συνιδὼν οὐκ ἐφῆκε κατὰ τὰ αὐτὰ τοῖς ἄλλοις ἑορτάζειν, ἀλλ’ ἐν αὐτῷ τῷ τῆς εὐφροσύνης καιρῷ πρῶτον μὲν ἐκέλευσεν ἁγνεύειν ἐπιστομίζοντας τὰς ἐφ’ ἡδονὴν ὁρμάς, εἶτα εἰς τὸ ἱερὸν ἐπὶ μετουσίαν ὕμνων καὶ εὐχῶν καὶ θυσιῶν ἐκάλεσεν, ἵνα κἀκ τοῦ τόπου κἀκ τῶν ὁρωμένων καὶ λεγομένων διὰ τῶν κυριωτάτων αἰσθήσεων, ὄψεως καὶ ἀκοῆς, ἐγκρατείας ἅμα καὶ εὐσεβείας ἐρασθῶσιν, εἶτ’ ἐπὶ πᾶσιν ὑπέμνησε τοῦ μὴ ἁμαρτάνειν διὰ τῆς θυσίας τοῦ περὶ ἁμαρτίας· ὁ γὰρ ἀμνηστίαν ἐφ’ οἷς ἥμαρτεν αἰτούμενος οὐχ οὕτως ἐστὶ κακοδαίμων, ὥστ’ ἐν ᾧ χρόνῳ παλαιῶν ἀδικημάτων αἰτεῖται λύσιν ἕτερα καινοτομεῖν.", "st": "193"}, {"sp": "N", "t": "Τοσαῦτα περὶ τούτων διαλεχθεὶς ἄρχεται διαιρεῖν τὰ τῶν θυσιῶν γένη καὶ τέμνων εἰς εἴδη τρία τὰ ἀνωτάτω τὸ μὲν ὁλόκαυτον καλεῖ, τὸ δὲ σωτήριον, τὸ δὲ περὶ ἁμαρτίας· εἶθ’ ἕκαστον τοῖς ἁρμόττουσιν ἐπικοσμεῖ τοῦ πρέποντος ἅμα καὶ εὐαγοῦς οὐ μετρίως στοχασάμενος.", "st": "194"}, {"sp": "N", "t": "παγκάλη δὲ καὶ προσφυεστάτη τοῖς πράγμασιν ἡ διαίρεσις ἀκολουθίαν ἔχουσα καὶ εἱρμόν· εἰ γὰρ βούλοιτό τις ἐξετάζειν ἀκριβῶς τὰς αἰτίας, ὧν ἕνεκα τοῖς πρώτοις ἔδοξεν ἀνθρώποις ἐπὶ τὰς διὰ θυσιῶν εὐχαριστίας ὁμοῦ καὶ λιτὰς ἐλθεῖν, εὑρήσει δύο τὰς ἀνωτάτω· μίαν μὲν τὴν πρὸς θεὸν τιμήν, τὴν ἄνευ τινὸς ἑτέρου δι’ αὐτὸν μόνον γινομένην ὡς ἀναγκαῖον καὶ καλόν, ἑτέραν δὲ τὴν τῶν θυόντων προηγουμένην ὠφέλειαν· διττὴ δ’ ἐστίν, ἡ μὲν ἐπὶ μετουσίᾳ ἀγαθῶν, ἡ δὲ ἐπὶ κακῶν ἀπαλλαγῇ.", "st": "195"}, {"sp": "N", "t": "τῇ μὲν οὖν κατὰ θεὸν καὶ δι’ αὐτὸν μόνον γινομένῃ προσήκουσαν ὁ νόμος ἀπένειμε θυσίαν τὴν ὁλόκαυτον, ὁλοκλήρῳ καὶ παντελεῖ μηδὲν ἐπιφερομένῃ τῆς θνητῆς φιλαυτίας ὁλόκληρον καὶ παντελῆ· τὴν δὲ χάριν ἀνθρώπων, ἐπειδὴ διαίρεσιν ἐπεδέχετο ἡ δόξα, καὶ αὐτὸς διεῖλε, κατὰ μὲν τὴν μετουσίαν τῶν ἀγαθῶν ὁρίσας θυσίαν ἣν ὠνόμασε σωτήριον, τῇ δὲ φυγῇ τῶν κακῶν ἀπονείμας τὴν περὶ ἁμαρτίας. ὡς τρεῖς εἶναι δεόντως ἐπὶ τρισί,", "st": "196"}, {"sp": "N", "t": "τὴν μὲν ὁλόκαυτον δι’ αὐτὸν μόνον τὸν θεόν, ὃν καλὸν τιμᾶσθαι, μὴ δι’ ἕτερον, τὰς δ’ ἄλλας δι’ ἡμᾶς, τὴν μὲν σωτήριον ἐπὶ σωτηρίᾳ καὶ βελτιώσει τῶν ἀνθρωπίνων πραγμάτων, τὴν δὲ περὶ ἁμαρτίας ἐπὶ θεραπείᾳ ὧν ἐπλημμέλησεν ἡ ψυχή.", "st": "197"}, {"sp": "N", "t": "Λεκτέον δὲ περὶ ἑκάστης τὰ νομοθετηθέντα τὴν ἀρχὴν ποιησαμένους ἀπὸ τῆς ἀρίστης· ἀρίστη δ’ ἐστὶν ἡ ὁλόκαυτος. ἔστω δή, φησί, πρῶτον μὲν τὸ ἱερεῖον ἄρρεν, ἐκ τῶν πρὸς τὰς θυσίας ἀριστίνδην ζῴων ἐπικριθέντων, μόσχος ἢ ἀμνὸς ἢ ἔριφος· ἔπειτα δ’ ἀπονιψάμενος ὁ προσάγων τὰς χεῖρας ἐπιφερέτω τῇ τοῦ ἱερείου κεφαλῇ·", "st": "198"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα λαβών τις τῶν ἱερέων καταθυέτω καὶ φιάλην ἕτερος ὑποσχὼν καὶ δεξάμενος τοῦ αἵματος ἐν κύκλῳ περιϊὼν τὸν βωμὸν ἐπιρραινέτω, καὶ τὸ ἱερεῖον ἀποδαρὲν εἰς ὁλόκληρα μέλη διανεμέσθω, κοιλίας ἀποπλυνομένης καὶ ποδῶν· εἶτα σύμπαν τῷ ἱερῷ πυρὶ τοῦ βωμοῦ παραδιδόσθω, γεγονὸς καὶ ἐξ ἑνὸς πολλὰ καὶ ἐκ πολλῶν ἕν.", "st": "199"}, {"sp": "N", "t": "ταῦτα μὲν ἡ ῥητὴ πρόσταξις περιέχει. μηνύεται δὲ καὶ νοῦς ἕτερος αἰνιγματώδη λόγον ἔχων τὸν διὰ συμβόλων· σύμβολα δ’ ἐστὶ τὰ λεχθέντα φανερὰ ἀδήλων καὶ ἀφανῶν. ἄρρεν εὐθέως τὸ ὁλόκαυτον ἱερεῖον, ἐπειδὴ τοῦ θήλεος καὶ τελειότερον καὶ ἡγεμονικώτερον καὶ συγγενέστερον αἰτίῳ δραστικῷ· τὸ γὰρ θῆλυ ἀτελές, ὑπήκοον, ἐν τῷ πάσχειν μᾶλλον ἢ ποιεῖν ἐξεταζόμενον.", "st": "200"}, {"sp": "N", "t": "δυοῖν δ’ ὄντων, ἐξ ὧν ἡ ἡμετέρα ψυχὴ συνέστη, λογικοῦ τε καὶ ἀλόγου, τὸ μὲν λογικὸν τῆς ἄρρενος γενεᾶς ἐστιν, ὅπερ νοῦς καὶ λογισμὸς κεκλήρωται, τὸ δ’ ἄλογον τῆς πρὸς γυναικῶν, ὅπερ ἔλαχεν αἴσθησις. νοῦς δὲ αἰσθήσεως, ὡς ἀνὴρ γυναικός, καθ’ ὅλον γένος ἀμείνων, ὃς ἄμωμος ὢν καὶ καθαρθεὶς καθάρσεσι ταῖς ἀρετῆς τελείας αὐτός ἐστιν ἡ εὐαγεστάτη θυσία καὶ ὅλη δι’ ὅλων εὐάρεστος θεῷ.", "st": "201"}, {"sp": "N", "t": "τὰς δὲ ἐπιτιθεμένας τῇ τοῦ ζῴου κεφαλῇ χεῖρας δεῖγμα σαφέστατον εἶναι συμβέβηκε πράξεων ἀνυπαιτίων καὶ βίου μηδὲν ἐπιφερομένου τῶν εἰς κατηγορίαν ἀλλὰ τοῖς τῆς φύσεως νόμοις καὶ θεσμοῖς συνᾴδοντος.", "st": "202"}, {"sp": "N", "t": "βούλεται γὰρ τοῦ θύοντος πρῶτον μὲν τὸν νοῦν ὡσιῶσθαι γνώμαις ἀγαθαῖς καὶ συμφερούσαις ἐνασκούμενον, ἔπειτα δὲ τὸν βίον ἐξ ἀρίστων συνεστάναι πράξεων, ὡς ἅμα τῇ τῶν χειρῶν ἐπιθέσει δύνασθαί τινα παρρησιασάμενον ἐκ καθαροῦ τοῦ συνειδότος τοιαῦτα εἰπεῖν·", "st": "203"}, {"sp": "N", "t": "αἱ χεῖρες αὗται οὔτε δῶρον ἐπ’ ἀδίκοις ἔλαβον οὔτε τὰς ἐξ ἁρπαγῆς καὶ πλεονεξίας διανομὰς οὔτε αἵματος ἀθῴου προσήψαντο, οὐ πήρωσιν, οὐχ ὕβριν, οὐ τραῦμα, οὐ βίαν ἐξειργάσαντο, οὐκ ἄλλο τὸ παράπαν οὐδὲν τῶν κατηγορίαν καὶ ψόγον ἐχόντων ὑπηρέτησαν, ἀλλ’ ὑποδιάκονοι πάντων ἐγένοντο τῶν καλῶν καὶ συμφερόντων, ἃ παρὰ σοφίᾳ καὶ νόμοις καὶ σοφοῖς καὶ νομίμοις ἀνδράσι τετίμηται.", "st": "204"}, {"sp": "N", "t": "τὸ δ’ αἷμα κύκλῳ προσχεῖται τῷ βωμῷ, διότι κύκλος σχημάτων τὸ τελειότατον καὶ ὑπὲρ τοῦ μέρος μηδὲν ἔρημον καὶ κενὸν ἀπολειφθῆναι ψυχικῆς σπονδῆς· ψυχῆς γὰρ κυρίως εἰπεῖν ἐστι σπονδὴ τὸ αἷμα. συμβολικῶς οὖν ἀναδιδάσκει τὴν διάνοιαν ὅλην δι’ ὅλων ἐν κύκλῳ χορεύουσαν ἐν πάσαις ἰδέαις λόγων καὶ βουλευμάτων καὶ ἔργων ἐπιδείκνυσθαι τὴν πρὸς τὸν θεὸν ἀρέσκειαν.", "st": "205"}, {"sp": "N", "t": "ἀποπλύνεσθαι δὲ κοιλίαν καὶ πόδας διείρηται, πάνυ συμβολικῶς· διὰ μὲν γὰρ τῆς κοιλίας αἰνίττεται τὴν ἐπιθυμίαν, ἣν ἐκνίπτεσθαι συμφέρον κηλίδων καὶ μιασμάτων καὶ μέθης καὶ παροινίας μεστήν, κακὸν βλαβερώτατον ἐπὶ λύμῃ τοῦ βίου τῶν ἀνθρώπων συγκροτούμενόν τε καὶ συνασκούμενον·", "st": "206"}, {"sp": "N", "t": "διὰ δὲ τοῦ τοὺς πόδας ἀπολούεσθαι τὸ μηκέτι βαίνειν ἐπὶ γῆς, ἀλλ’ αἰθεροβατεῖν· ἡ γὰρ τοῦ φιλοθέου ψυχὴ πρὸς ἀλήθειαν ἀπὸ γῆς ἄνω πρὸς οὐρανὸν πηδᾷ καὶ πτερωθεῖσα μετεωροπολεῖ συντάττεσθαι γλιχομένη καὶ συγχορεύειν ἡλίῳ καὶ σελήνῃ καὶ τῇ τῶν ἄλλων ἀστέρων ἱερωτάτῃ καὶ παναρμονίῳ στρατιᾷ, ταξιαρχοῦντος καὶ ἡγεμονεύοντος τοῦ θεοῦ τοῦ τὴν ἀνανταγώνιστον καὶ ἀναφαίρετον βασιλείαν ἔχοντος, δι’ ἧς ἐνδίκως ἕκαστα πρυτανεύεται.", "st": "207"}, {"sp": "N", "t": "ἡ δὲ εἰς μέλη τοῦ ζῴου διανομὴ δηλοῖ, ἤτοι ὡς ἓν τὰ πάντα ἢ ὅτι ἐξ ἑνός τε καὶ εἰς ἕν, ὅπερ οἱ μὲν κόρον καὶ χρησμοσύνην ἐκάλεσαν, οἱ δ’ ἐκπύρωσιν καὶ διακόσμησιν, ἐκπύρωσιν μὲν κατὰ τὴν τοῦ θερμοῦ δυναστείαν τῶν ἄλλων ἐπικρατήσαντος, διακόσμησιν δὲ κατὰ τὴν τῶν τεττάρων στοιχείων ἰσονομίαν, ἣν ἀντιδιδόασιν ἀλλήλοις.", "st": "208"}, {"sp": "N", "t": "ἐμοὶ δὲ εὐθυβολώτερον σκοπουμένῳ δοκεῖ τοῦτο δηλοῦσθαι· ἡ τιμῶσα ψυχὴ τὸ ὂν δι’ αὐτὸ τὸ ὂν ὀφείλει μὴ ἀλόγως μηδ’ ἀνεπιστημόνως ἀλλὰ σὺν ἐπιστήμῃ καὶ λόγῳ τιμᾶν. ὁ δὲ περὶ αὐτοῦ λόγος τομὴν ἐπιδέχεται καὶ διαίρεσιν καθ’ ἑκάστην τῶν θείων δυνάμεων καὶ ἀρετῶν· ὁ γὰρ θεὸς ἀγαθός τέ ἐστι καὶ ποιητὴς καὶ γεννητὴς τῶν ὅλων καὶ προνοητικὸς ὧν ἐγέννησε, σωτήρ τε καὶ εὐεργέτης, μακαριότητος καὶ πάσης εὐδαιμονίας ἀνάπλεως· ὧν ἕκαστον καὶ καθ’ αὑτὸ ἰδίᾳ σεμνὸν καὶ ἐπαινετὸν καὶ μετὰ τῶν ὁμογενῶν ἐξεταζόμενον.", "st": "209"}, {"sp": "N", "t": "ἔχει δὲ καὶ τὰ ἄλλα ταύτῃ. ὅταν βουληθῇς, ὦ διάνοια, εὐχαριστῆσαι περὶ γενέσεως κόσμου θεῷ, καὶ περὶ τοῦ ὅλου ποιοῦ τὴν εὐχαριστίαν καὶ περὶ τῶν ὁλοσχερεστάτων αὐτοῦ μερῶν ὡς ἂν ζῴου τελειοτάτου μελῶν, οἷον οὐρανοῦ λέγω καὶ ἡλίου καὶ σελήνης, πλανήτων καὶ ἀπλανῶν ἀστέρων, εἶτα γῆς καὶ τῶν ἐν αὐτῇ ζῴων καὶ φυτῶν, εἶτα πελαγῶν καὶ ποταμῶν αὐθιγενῶν τε καὶ χειμάρρων καὶ τῶν ἐν αὐτοῖς, ἔπειτα ἀέρος καὶ τῶν κατ’ αὐτὸν μεταβολῶν· χειμὼν γὰρ καὶ θέρος, ἔαρ τε καὶ μετόπωρον, αἱ ἐτήσιοι καὶ βιωφελέσταται ὧραι, παθήματα ἀέρος γεγόνασιν ἐπὶ σωτηρίᾳ τῶν μετὰ σελήνην τρεπομένου.", "st": "210"}, {"sp": "N", "t": "κἂν ἄρα ποτὲ περὶ ἀνθρώπων εὐχαριστῇς, μὴ μόνον περὶ τοῦ γένους ἀλλὰ καὶ περὶ τῶν εἰδῶν καὶ ἀναγκαιοτάτων μερῶν εὐχαρίστει, ἀνδρῶν, γυναικῶν, Ἑλλήνων, βαρβάρων, τῶν ἐν ἠπείροις, τῶν τὰς νήσους εἰληχότων· κἂν περὶ ἑνὸς ἀνδρός, τέμε τῷ λόγῳ τὴν εὐχαριστίαν, μὴ εἰς τὰ λεπτότατα μέχρι τῶν ἐσχάτων, ἀλλὰ εἰς τὰ συνεκτικώτατα, σῶμα καὶ ψυχὴν τὸ πρῶτον, ἐξ ὧν συνέστηκεν, εἶτα εἰς λόγον καὶ νοῦν καὶ αἴσθησιν· οὐ γὰρ ἂν γένοιτο ἀναξία θεοῦ ἀκοῆς καὶ ἡ ὑπὲρ ἑκάστου τούτων εὐχαριστία καθ’ αὑτήν.", "st": "211"}, {"sp": "N", "t": "Ἀπόχρη τοσαῦτα περὶ τῆς ὁλοκαύτου θυσίας λελέχθαι. τὴν δὲ τοῦ σωτηρίου λεγομένην ἑξῆς ἐπισκεπτέον. ἐπὶ ταύτης ἀδιαφορεῖ, ἐάν τε ἄρρεν ᾖ τὸ ἱερεῖον ἐάν τε καὶ θῆλυ. σφαγέντος δὲ τρία ταῦτα ὑπεξαιρεῖται τῷ βωμῷ, τὸ στέαρ καὶ λοβὸς ἥπατος καὶ νεφροὶ δύο· τὰ δ’ ἄλλα τῷ καταθύσαντι εὐωχία.", "st": "212"}, {"sp": "N", "t": "διὰ τί δὲ τὰ μέρη ταῦτα τῶν ἐντοσθιδίων καθιεροῦται, μετὰ ἀκριβείας ἐπισκεπτέον ἐκεῖνο μὴ παρελθόντας· διαλογιζόμενος ἐν ἐμαυτῷ πολλάκις ταῦτα καὶ διερευνώμενος ἐπηπόρησα, τί δήποτε λοβὸν μὲν ἥπατος καὶ νεφροὺς καὶ στέαρ ἀπαρχὰς τῶν καταθυομένων ζῴων ὑπεξείλετο ὁ νόμος, οὔτε δὲ καρδίαν οὔτε ἐγκέφαλον, τοῦ ἡγεμονικοῦ τῷ ἑτέρῳ τούτων ἐνδιαιτωμένου.", "st": "213"}, {"sp": "N", "t": "τὸ δ’ αὐτὸ νομίζω καὶ ἄλλους οὐκ ὀλίγους τῶν διανοίᾳ μᾶλλον ἢ ὀφθαλμοῖς ταῖς ἱεραῖς γραφαῖς ἐντυγχανόντων ἐπιζητήσειν· ἐὰν μὲν οὖν ἐπισκεψάμενοι πιθανωτέραν αἰτίαν εὕρωσιν, ἑαυτούς τε καὶ ἡμᾶς ὠφελήσουσιν· εἰ δὲ μή, τὴν ἐπινοηθεῖσαν ὑφ’ ἡμῶν ἐπικρινάτωσαν, εἰ δόκιμος. ἔστι δὲ ἥδε· τὸ ἡγεμονικὸν μόνον τῶν ἐν ἡμῖν ἀφροσύνην καὶ ἀδικίαν καὶ δειλίαν καὶ τὰς ἄλλας κακίας δέχεταί τε καὶ χωρεῖ· τούτου δὲ οἶκος τὸ ἕτερον τῶν λεχθέντων ἐστίν, ἐγκέφαλος ἢ καρδία.", "st": "214"}, {"sp": "N", "t": "ἐδικαίωσεν οὖν ὁ ἱερὸς λόγος τῷ τοῦ θεοῦ βωμῷ, δι’ οὗ πάντων ἁμαρτημάτων καὶ παρανομημάτων ἀπολύσεις γίνονται καὶ παντελεῖς ἀφέσεις, μὴ προσφέρειν ἀγγεῖον, ἐν ᾧ ποτε φωλεύσας ὁ νοῦς ἐπὶ τὴν ἀδικίας καὶ ἀσεβείας ἀνοδίαν ἐχώρησεν ἐκτραπόμενος τὴν ἐπ’ ἀρετὴν καὶ καλοκἀγαθίαν ἄγουσαν ὁδόν· εὔηθες γὰρ τὰς θυσίας ὑπόμνησιν ἁμαρτημάτων ἀλλὰ μὴ λήθην αὐτῶν κατασκευάζειν. τοῦτ’ αἴτιον εἶναί μοι δοκεῖ τοῦ μηδέτερον τῶν ἡγεμονίαν ἐχόντων, ἐγκέφαλον ἢ καρδίαν, προσφέρεσθαι.", "st": "215"}, {"sp": "N", "t": "ἃ δὲ διείρηται, λόγον ἔχει προσήκοντα· τὸ μὲν στέαρ, ὅτι καὶ πιότατον καὶ τῶν σπλάγχνων φυλακτήριον—ἐπαμπίσχει γὰρ αὐτὰ καὶ πιαίνει καὶ τῇ μαλακότητι τῆς ἐπαφῆς ὠφελεῖ —, οἱ δὲ νεφροὶ διὰ τοὺς παραστάτας καὶ τὰ γεννητικά, οἷς παροικοῦντες ἀγαθῶν τρόπον γειτόνων βοηθοῦσι καὶ συμπράττουσιν, ὅπως ὁ τῆς φύσεως σπόρος εὐοδῇ, μηδενὸς τῶν πλησίον ἐμποδίζοντος—αὐτοὶ μὲν γὰρ αἱμοειδεῖς εἰσι δεξαμεναί, οἷς ἡ τῶν περιττωμάτων ὑγρὰ κάθαρσις ἀποκρίνεται, οἱ δὲ παραστάται πλησίον, δι’ ὧν ἄρδεται ὁ σπόρος —, λοβὸς δ’ ἥπατος τοῦ κυριωτάτου τῶν σπλάγχνων ἐστὶν ἀπαρχή, δι’ οὗ τὴν τροφὴν ἐξαιματοῦσθαι συμβέβηκε καὶ ἐποχετευομένην τῇ καρδίᾳ φέρεσθαι διὰ φλεβῶν εἰς τὴν τοῦ ὅλου σώματος διαμονήν.", "st": "216"}, {"sp": "N", "t": "στόμαχος μὲν γὰρ παρακείμενος τῇ καταπόσει τὴν ὑπὸ τῶν ὀδόντων τμηθεῖσαν πρότερον καὶ λεανθεῖσαν αὖθις τροφὴν ὑποδέχεται καὶ προκατεργάζεται κοιλίᾳ· κοιλία δὲ παρὰ στομάχου λαμβάνουσα τὴν δευτέραν ὑπηρεσίαν ἐπιτελεῖ, πρὸς ἣν ὑπὸ φύσεως ἐτάχθη, χύλωσιν ἀπεργαζομένη τῆς τροφῆς· αὐλοὶ δὲ δύο τῆς κοιλίας σωληνοειδεῖς ἐκπεφύκασιν εἰς ἧπαρ ἐπαντλοῦντες ταῖς διαπεφυκυίαις ἐν αὐτῷ δεξαμεναῖς.", "st": "217"}, {"sp": "N", "t": "ἔχει δὲ διττὴν δύναμιν ἧπαρ, διακριτικήν τε καὶ τὴν πρὸς ἐξαιμάτωσιν· ἡ μὲν οὖν διακριτικὴ πᾶν ὅσον ἀτέραμνον καὶ δυσκατέργαστον εἰς τὸ παρακείμενον χολῆς ἀγγεῖον ἀποκρίνει, ἡ δ’ ἑτέρα τὸ καθαρὸν καὶ διηθημένον τῷ περὶ αὐτὴν φλογμῷ τρέπει μὲν εἰς αἷμα ζωτικώτατον, ἀναθλίβει δ’ εἰς καρδίαν, ἀφ’ ἧς ὡς ἐλέχθη ταῖς φλεψὶν ἐποχετευόμενον διὰ παντὸς εἱλεῖται τοῦ σώματος γινόμενον αὐτῷ τροφή.", "st": "218"}, {"sp": "N", "t": "πρόσεστι δὲ κἀκεῖνο τοῖς εἰρημένοις· τὴν τοῦ ἥπατος φύσιν μετέωρον καὶ λειοτάτην οὖσαν [καὶ] διὰ λειότητα φανοτάτου κατόπτρου λόγον ἔχειν συμβέβηκεν, ἵν’ ἐπειδὰν τῶν ἡμερινῶν φροντίδων ἀναχωρήσας ὁ νοῦς, ὕπνῳ μὲν παρειμένου τοῦ σώματος, μηδεμιᾶς δὲ τῶν αἰσθήσεων ἱσταμένης ἐμποδών, ἀνακυκλεῖν αὑτὸν ἄρξηται καὶ τὰ νοήματα καθαρῶς ἐφ’ αὑτοῦ σκοπεῖν, οἷα εἰς κάτοπτρον ἀποβλέπων τὸ ἧπαρ ἕκαστα εἱλικρινῶς καταθεᾶται τῶν νοητῶν καὶ περιβλεπόμενος ἐν κύκλῳ τὰ εἴδωλα, μή τι πρόσεστιν αἶσχος, [ἵνα] τὸ μὲν φύγῃ, τὸ δ’ ἐναντίον ἕληται, καὶ πάσαις ταῖς φαντασίαις εὐαρεστήσας προφητεύῃ διὰ τῶν ὀνείρων τὰ μέλλοντα.", "st": "219"}, {"sp": "N", "t": "Δυσὶ δὲ μόναις ἡμέραις ἐπιτρέπει τὴν χρῆσιν τῆς τοῦ σωτηρίου θυσίας ποιεῖσθαι μηδὲν εἰς τὴν τρίτην ἀπολείποντας, πολλῶν χάριν· ἑνὸς μὲν ὅτι τὰ τῆς ἱερᾶς τραπέζης πάντα καιρίως δεῖ προσφέρεσθαι σπουδὴν ποιουμένους, ὡς μὴ μεταβάλῃ μήκει χρόνου· κρεῶν δὲ ἑώλων εὔσηπτος ἡ φύσις, κἂν ἡδύσμασι παραρτυθῇ.", "st": "220"}, {"sp": "N", "t": "ἑτέρου δ’ ὅτι τὰς θυσίας ἀταμιεύτους εἶναι προσήκει καὶ πᾶσιν εἰς μέσον προκεῖσθαι τοῖς δεομένοις· εἰσὶ γὰρ οὐκέτι τοῦ τεθυκότος, ἀλλ’ ᾧ τέθυται τὸ ἱερεῖον, ὃς εὐεργέτης καὶ φιλόδωρος ὢν κοινωνὸν ἀπέφηνε τοῦ βωμοῦ καὶ ὁμοτράπεζον τὸ συμπόσιον τῶν τὴν θυσίαν ἐπιτελούντων, οἷς παραγγέλλει μὴ νομίζειν ἑστιᾶν· ἐπίτροποι γὰρ εὐωχίας εἰσίν, οὐχ ἑστιάτορες, ὁ δ’ ἑστιάτωρ ἐστὶν οὗ συμβέβηκεν εἶναι καὶ τὴν παρασκευήν, ἣν οὐ θέμις ἀποκρύπτειν φειδωλίαν, ἀνελεύθερον κακίαν, φιλανθρωπίας, ἀρετῆς εὐγενοῦς, προκρίνοντας.", "st": "221"}, {"sp": "N", "t": "τελευταίου δ’ ὅτι τὴν τοῦ σωτηρίου θυσίαν ὑπὲρ δυεῖν προσάγεσθαι συμβέβηκε, ψυχῆς τε καὶ σώματος, ὧν ἑκατέρῳ μίαν ἡμέραν ἀπένειμεν εἰς εὐωχίαν τῶν κρεῶν· ἥρμοττε γὰρ ἰσάριθμον χρόνον ὁρισθῆναι τοῖς πεφυκόσι σῴζεσθαι τῶν ἐν ἡμῖν, ὡς τῇ μὲν προτεραίᾳ λαμβάνειν ἅμα τῇ βρώσει τῆς ψυχικῆς σωτηρίας ὑπόμνησιν, τῇ δ’ ὑστεραίᾳ τῆς κατὰ τὸ σῶμα ὑγείας.", "st": "222"}, {"sp": "N", "t": "ἐπεὶ δὲ τρίτον οὐδὲν ἦν ὃ κυρίως πέφυκε σωτηρίαν ἐνδέχεσθαι, τὴν εἰς τὴν τρίτην ἡμέραν χρῆσιν ἀνὰ κράτος ἀπηγόρευσε προστάξας, εἰ καὶ τύχοι τι κατ’ ἄγνοιαν ἢ λήθην ἀπολειφθέν, εὐθὺς ἀναλίσκεσθαι πυρί. τὸν δὲ γευσάμενον αὐτὸ μόνον ἔνοχον ἀποφαίνει καί φησιν αὐτῷ· τεθυκέναι νομίζων, ὦ καταγέλαστε, οὐ τέθυκας· οὐ προσηκάμην ἀθύτων, ἀνιέρων, βεβήλων, ἀκαθάρτων, ὧν ἥψηκας κρεῶν, ὦ γατρίμαργε, θυσιῶν οὐδ’ ὄναρ ἐπῃσθημένος.", "st": "223"}, {"sp": "N", "t": "Τῆς δὲ τοῦ σωτηρίου θυσίας ἐν εἴδει περιλαμβάνεται ἡ λεγομένη τῆς αἰνέσεως, ἥτις λόγον ἔχει τοιόνδε· ὁ μηδενὶ τὸ παράπαν ἀβουλήτῳ περιπεσών, μήτε κατὰ σῶμα μήτε κατὰ τὰ ἐκτός, ἀλλ’ ἀπολέμῳ καὶ εἰρηνικῷ βίῳ χρώμενος ἐν εὐπαθείαις τε καὶ εὐτυχίαις ἐξεταζόμενος, ἀπήμων καὶ ἄπταιστος ὢν καὶ τὸ μακρὸν τοῦ βίου πέλαγος εὐθύνων ἐν εὐδίᾳ καὶ γαλήνῃ πραγμάτων, ἐπιπνεούσης ἀεὶ κατ’ οἰάκων εὐπραγίας, ἀναγκαίως ὀφείλει τὸν κυβερνήτην θεὸν καὶ ἄνοσον μὲν σωτηρίαν ἀζημίους δ’ ὠφελείας καὶ συνόλως ἀμιγῆ κακῶν τὰ ἀγαθὰ δωρούμενον ὕμνοις τε καὶ εὐδαιμονισμοῖς καὶ εὐχαῖς θυσίαις τε καὶ ταῖς ἄλλαις εὐχαριστίαις εὐαγῶς ἀμείβεσθαι· ἃ δὴ πάντα ἀθρόα συλλήβδην ἓν ὄνομα τὸ αἰνέσεως ἔλαχε.", "st": "224"}, {"sp": "N", "t": "ταύτην τὴν θυσίαν οὐχ ὥσπερ τὴν προτέραν τοῦ σωτηρίου δυσὶν ἡμέρας ἀναλίσκεσθαι προστάττει, μιᾷ δ’ αὐτὸ μόνον, ἵν’ οἱ ἐπιτυχόντες ἑτοίμων καὶ προχείρων εὐεργεσιῶν ἑτοίμην καὶ ἀνυπέρθετον ποιῶνται τὴν μετάδοσιν.", "st": "225"}, {"sp": "N", "t": "Ταῦτα μὲν ἐπὶ τοσοῦτον. τὴν δὲ τρίτην ἑξῆς ἐπισκεπτέον, ἣ καλεῖται περὶ ἁμαρτίας. αὕτη τέτμηται πολλαχῇ, κἀν τοῖς προσώποις κἀν τοῖς τῶν ἱερείων εἴδεσι, προσώποις μὲν ἀρχιερέως καὶ τοῦ σύμπαντος ἔθνους καὶ ἄρχοντος ἐν μέρει καὶ ἰδιώτου, ἱερείοις δὲ μόσχου καὶ χιμάρου καὶ χιμαίρας ἢ ἀμνάδος.", "st": "226"}, {"sp": "N", "t": "διακέκριται δὲ καὶ μάλιστ’ ἦν ἀναγκαῖον διακεκρίσθαι τά θ’ ἑκούσια καὶ ἀκούσια, τροπὰς λαμβανόντων τὰς πρὸς τὸ βέλτιον τῶν δοξάντων ἁμαρτεῖν καὶ κακιζόντων μὲν αὑτοὺς ἐφ’ οἷς ἐπλημμέλησαν, μεθορμιζομένων δὲ πρὸς ζωὴν ἀνυπαίτιον.", "st": "227"}, {"sp": "N", "t": "τὰ μὲν οὖν τοῦ ἀρχιερέως ἁμαρτήματα καὶ τοῦ ἔθνους ἰσοτίμῳ καθαίρεται ζῴῳ — μόσχον γὰρ ἀνάγεσθαι περὶ ἑκατέρου προστέτακται —, τὰ δὲ τοῦ ἄρχοντος ἐλάττονι μέν, ἄρρενι δὲ καὶ τούτῳ—χίμαρος γάρ ἐστι τὸ ἱερεῖον —, τὰ δὲ τοῦ ἰδιώτου καταδεεστέρῳ τὸ εἶδος—θῆλυ γὰρ ἀλλ’ οὐκ ἄρρεν θῦμα, χίμαιρα, καταθύεται —.", "st": "228"}, {"sp": "N", "t": "ἔδει γὰρ ἰδιώτου μὲν πλέον ἄρχοντα φέρεσθαι κἀν ταῖς ἱερουργίαις, ἄρχοντος δὲ τὸ ἔθνος, ἐπεὶ τὸ ὅλον τοῦ μέρους ἀεὶ κρεῖττον εἶναι δεῖ, τὸν δ’ ἀρχιερέα τῷ ἔθνει τῆς αὐτῆς ἠξιῶσθαι προνομίας ἐν τῷ καθαίρεσθαι καὶ παρὰ τῆς ἵλεω τοῦ θεοῦ δυνάμεως ἀμνηστίαν ἀδικημάτων αἰτεῖσθαι· τὸ δ’ ἰσότιμον οὐ δι’ αὑτόν, ὡς ἔοικε, καρποῦται μᾶλλον ἢ διότι τοῦ ἔθνους ὑπηρέτης ἐστὶ τὰς κοινὰς ὑπὲρ ἁπάντων ποιούμενος εὐχαριστίας ἐν ταῖς ἱερωτάταις εὐχαῖς καὶ ἐν ταῖς εὐαγεστάταις θυσίαις.", "st": "229"}, {"sp": "N", "t": "σεμνὴ δὲ καὶ θαυμάσιος καὶ ἡ περὶ ταῦτα διάταξις· “ἐὰν” φησίν “ὁ ἀρχιερεὺς ἄκων ἁμάρτῃ,” καὶ προστίθησιν “ὥστε τὸν λαὸν ἁμαρτεῖν”, μόνον οὐκ ἄντικρυς ἀναδιδάσκων, ὅτι ὁ πρὸς ἀλήθειαν ἀρχιερεὺς καὶ μὴ ψευδώνυμος ἀμέτοχος ἁμαρτημάτων ἐστίν, εἰ δ’ ὀλισθήσοι ποτέ, πείσεται τοῦτο οὐ δι’ αὑτόν, ἀλλὰ διὰ κοινὸν τοῦ ἔθνους σφάλμα· τὸ δὲ σφάλμα οὐκ ἀνίατον, ἀλλὰ ῥᾳδίως τὴν θεραπείαν ἐνδεχόμενον.", "st": "230"}, {"sp": "N", "t": "ὅταν οὖν σφαγιασθῇ ὁ μόσχος, κελεύει τοῦ αἵματος ἐπιρραίνειν ἑπτάκις τῷ δακτύλῳ ἀντικρὺ τοῦ πρὸς τοῖς ἀδύτοις καταπετάσματος, ἐσωτέρω τοῦ προτέρου, καθ’ ὃν τόπον ἵδρυται τὰ ἱερώτατα σκεύη, κἄπειτα τὰ τοῦ θυμιατηρίου τέτταρα κέρατα—τετράγωνον γάρ ἐστι— χρίειν καὶ ἐπαλείφειν, τὸ δ’ ἄλλο αἷμα προσχεῖν παρὰ τῇ βάσει τοῦ ἐν ὑπαίθρῳ βωμοῦ·", "st": "231"}, {"sp": "N", "t": "ἐφ’ ὃν ἀναφέρειν τρία διείρηται, στέαρ καὶ λοβὸν ἥπατος καὶ διττοὺς νεφρούς, κατὰ τὴν ἐπὶ τοῦ σωτηρίου διάταξιν, δορὰν δὲ καὶ κρέα καὶ σύμπαν ἀπὸ κεφαλῆς ἄχρι ποδῶν τὸ ἄλλο σῶμα τοῦ μόσχου μετὰ τῶν ἐντοσθιδίων προφέρειν ἔξω καὶ κατακαίειν ἐν χωρίῳ καθαρῷ, ἔνθα τὴν ἱερὰν ἀπὸ τοῦ βωμοῦ τέφραν ἐκκομίζεσθαι συμβέβηκε.", "st": "232"}, {"sp": "N", "t": "τὰ δ’ αὐτὰ νομοθετεῖ καὶ περὶ παντὸς τοῦ ἔθνους ἁμαρτόντος. εἰ δέ τις ἄρχων πλημμελήσειε, χιμάρῳ ποιεῖται τὴν κάθαρσιν, ὡς εἶπον, ἐὰν δὲ ἰδιώτης, χιμαίρᾳ ἢ ἀμνάδι· τῷ μὲν γὰρ ἄρρεν, τῷ δ’ ἰδιώτῃ θῆλυ ζῷον ἀπένειμε, τὰ δ’ ἄλλα διαταξάμενος ἐπ’ ἀμφοῖν ὅμοια, χρίσαι τὰ κέρατα τοῦ ἐν ὑπαίθρῳ βωμοῦ τῷ αἵματι, στέαρ καὶ λοβὸν ἥπατος καὶ διττοὺς νεφροὺς ἀνενεγκεῖν, τὰ δ’ ἄλλα τοῖς ἱερεῦσι παρασχεῖν ἐδωδήν.", "st": "233"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν ἁμαρτημάτων τὰ μὲν εἰς ἀνθρώπους, τὰ δ’ εἰς ἱερὰ καὶ ἅγια δρᾶται, περὶ μὲν τῶν εἰς ἀνθρώπους γινομένων ἀκουσίως διείλεκται, τὴν δ’ ἐπὶ τοῖς ἱεροῖς κάθαρσιν ἱλάσκεσθαι κριῷ νομοθετεῖ, πρότερον ἀποτίσαντας ἐκεῖνο περὶ ὃ γέγονεν ἡ πλημμέλεια, τὸ πέμπτον προσεπιτιθέντας τῆς ἀξίας τιμῆς.", "st": "234"}, {"sp": "N", "t": "Ταῦτα καὶ τὰ τούτοις ὅμοια νομοθετήσας ἐπὶ τοῖς ἀκουσίοις καὶ περὶ τῶν ἑκουσίων ἑξῆς διατάττεται. ἐάν τις, φησί, ψεύσηται περὶ κοινωνίας ἢ περὶ παρακαταθήκης ἢ ἁρπαγῆς ἢ εὑρέσεως ὧν ἀπώλεσεν ἕτερος καὶ ὑπονοηθείς, ὅρκου προταθέντος, ὀμόσῃ καὶ δόξας ἐκπεφευγέναι τὸν ἀπὸ τῶν κατηγόρων ἔλεγχον αὐτὸς ἑαυτοῦ γένηται κατήγορος, ἔνδον ὑπὸ τοῦ συνειδότος ἐλεγχθείς, καὶ κακίσῃ μὲν ἑαυτὸν ὧν ἠρνήσατο καὶ ἐπιώρκησεν, ὁμολογῶν δ’ ἄντικρυς τὸ πραχθὲν ἀδίκημα συγγνώμην αἰτῆται, κελεύει τῷ τοιούτῳ παρέχειν ἀμνηστίαν,", "st": "235"}, {"sp": "N", "t": "ἐπαληθεύσαντι τὴν μετάνοιαν οὐχ ὑποσχέσει ἀλλ’ ἔργοις, ἀποδόσει τῆς παρακαταθήκης καὶ ὧν ἥρπασεν ἢ εὗρεν ἢ συνόλως ἐσφετερίσατο τοῦ πλησίον, προσαποτίσας καὶ τὸ ἐπίπεμπτον εἰς παρηγορίαν τοῦ πλημμεληθέντος.", "st": "236"}, {"sp": "N", "t": "ὅταν δὲ ἱλάσηται τὸν ἠδικημένον πρότερον, ἴτω, φησί, μετὰ ταῦτα καὶ εἰς τὸ ἱερὸν αἰτησόμενος ὧν ἐξήμαρτεν ἄφεσιν, ἐπαγόμενος παράκλητον οὐ μεμπτὸν τὸν κατὰ ψυχὴν ἔλεγχον, ὃς ἀνιάτου συμφορᾶς αὐτὸν ἐρρύσατο τὴν θανατοῦσαν νόσον ἀνεὶς καὶ πρὸς ὑγείαν παντελῆ μεταβαλών.", "st": "237"}, {"sp": "N", "t": "κριὸν δ’ εἶναι καὶ τούτῳ διείρηται σφάγιον, καθὰ καὶ τῷ πρὸς τὰ ἅγια πλημμελήσαντι· τὸ γὰρ ἐν τοῖς ἁγίοις ἀκούσιον ἁμάρτημα ἰσότιμον ἀπέφηνε τῷ περὶ τὰ ἀνθρώπινα ἑκουσίῳ, εἰ μὴ ἄρα καὶ τοῦτ’ ἐστί τι ἅγιον, ἐπειδὴ προσγέγονεν ὅρκος, ὃν οὐκ ἐφ’ ὑγιεῖ γενόμενον ἐπηνωρθώσατο τροπῇ τῇ πρὸς τὸ βέλτιον.", "st": "238"}, {"sp": "N", "t": "Παρατηρητέον δ’ ὅτι τὰ μὲν ἐπιφερόμενα τῷ βωμῷ ἐκ τοῦ περὶ ἁμαρτίας ἱερείου ταὐτά ἐστιν ἃ καὶ ἐπὶ τῆς τοῦ σωτηρίου θυσίας, λοβὸς ἥπατος καὶ στέαρ καὶ νεφροί· τρόπον γάρ τινα καὶ ὁ μετανοῶν σῴζεται, τὴν χαλεπωτέραν τῶν ἐν τῷ σώματι παθῶν νόσον ψυχῆς ἐκτρεπόμενος.", "st": "239"}, {"sp": "N", "t": "τὰ δ’ ἄλλα μέρη τοῦ ζῴου πρὸς ἐδωδὴν ἀπονέμεται διαφερόντως. ἐν τρισὶ δ’ ἡ διαφορά· τόπῳ, χρόνῳ, τοῖς λαμβάνουσι· τόπος μὲν οὖν τὸ ἱερόν, χρόνος δὲ ἀντὶ δυεῖν ἡμερῶν μία, οἱ δὲ μεταλαμβάνοντες ἱερεῖς, ἀλλ’ οὐχ ὧν ἐστιν ἡ θυσία, καὶ ἱερέων ἄρσενες.", "st": "240"}, {"sp": "N", "t": "ἔξω μὲν οὖν οὐκ ἐᾷ τοῦ ἱεροῦ προφέρειν βουλόμενος, εἴ τι τῷ μετανοοῦντι πρότερον ἡμάρτηται, μὴ περίφημον εἶναι βασκάνων καὶ φιλαπεχθημόνων γνώμαις ἀγνώμοσι καὶ στόμασιν ἀχαλίνοις, ἐπ’ ὀνείδει καὶ διαβολαῖς ἐκδεδομένον, ἀλλ’ ἐντὸς ὅρων ἱερῶν, ἐν οἷς καὶ ἡ κάθαρσις γέγονεν, εἶναι.", "st": "241"}, {"sp": "N", "t": "τοῖς δ’ ἱερεῦσιν εὐωχεῖσθαι τὴν θυσίαν κελεύει διὰ πολλά· πρῶτον μὲν ἵνα τιμήσῃ τοὺς τεθυκότας, ἡ γὰρ τῶν ἑστιωμένων ἀξίωσις ἐπικοσμεῖ τοὺς ἑστιάτορας· δεύτερον δὲ ἵνα βεβαιότατα πιστεύσωσιν, ὅτι οἷς ἁμαρτημάτων εἰσέρχεται μεταμέλεια ἵλεω τὸν θεὸν ἔχουσιν· οὐ γὰρ ἂν τοὺς προσπόλους αὐτοῦ καὶ θεράποντας ἐπὶ μετουσίαν τῆς τοιαύτης τραπέζης ἐκάλεσεν, εἰ μὴ παντελὴς ἐγεγένητο ἀμνηστία· τρίτον δ’ ὅτι λειτουργεῖν οὐδενὶ τῶν ἱερέων ἔξεστιν, ὃς ἂν μὴ ὁλόκληρος ᾖ· καὶ γὰρ τῷ βραχυτάτῳ μώμῳ σκορακίζεται.", "st": "242"}, {"sp": "N", "t": "παρηγορεῖ δὴ τοὺς μηκέτι τὴν τῶν ἀδικημάτων ὁδὸν ἰόντας ὡς ἱερατικοῦ γένους ἕνεκα προαιρέσεως καθαρᾶς μεταλαχόντας καὶ πρὸς ἱερέων ἰσοτιμίαν ἐπαχθέντας. ὅθεν καὶ μιᾷ ἡμέρᾳ τὸ περὶ ἁμαρτίας ἱερεῖον ἀναλίσκεται, ὡς δέον ὑπερτίθεσθαι μὲν τὸ ἁμαρτάνειν μέλλοντας ἀεὶ πρὸς αὐτὸ καὶ βραδύνοντας, πρὸς δὲ τὸ κατορθοῦν ἐπεσπευσμένῳ τάχει χρῆσθαι.", "st": "243"}, {"sp": "N", "t": "τὰ δ’ ὑπὲρ τοῦ ἀρχιερέως ἢ τοῦ ἔθνους ἕνεκα πλημμελείας σφαγιαζόμενα πρὸς μὲν ἐδωδὴν οὐ σκευάζεται, κατακαίεται δ’ ἐπὶ τῆς ἱερᾶς τέφρας, ὡς ἐλέχθη· κρείττων γὰρ οὐδεὶς ἀρχιερέως ἢ τοῦ ἔθνους ἐστίν, ὃς ἁμαρτησάντων γενήσεται παραιτητής.", "st": "244"}, {"sp": "N", "t": "εἰκότως οὖν ἀναλίσκεται τὰ κρέα πυρί, κατὰ μίμησιν τῶν ὁλοκαυτουμένων, ἐπὶ τιμῇ τῶν προσώπων, οὐχ ὅτι πρὸς ἀξίωσιν αἱ ἱεραὶ γίνονται κρίσεις, ἀλλ’ ὅτι τῶν τὰς ἀρετὰς μεγάλων καὶ ὡς ἀληθῶς ἁγίων ἁμαρτήματα τοιαῦτά ἐστιν, ὡς ἑτέρων κατορθώματα νομίζεσθαι.", "st": "245"}, {"sp": "N", "t": "καθάπερ γὰρ ἡ βαθεῖα καὶ ἀρετῶσα πεδιάς, κἂν ἀφορήσῃ ποτέ, τῆς λυπρόγεω φύσει καρπὸν φέρει πλείονα, τὸν αὐτὸν τρόπον καὶ τῶν σπουδαίων καὶ φιλοθέων συμβαίνει τὰς πρὸς καλοκἀγαθίαν ἀφορίας ἀμείνους εἶναι ὧν ἐκ τύχης οἱ φαῦλοι κατορθοῦσι· γνώμῃ γὰρ οὐδὲν ὑγιὲς δρᾶν ὑπομένουσι.", "st": "246"}, {"sp": "N", "t": "Ταῦτα διαταξάμενος περὶ ἑκάστης ἰδέας τῶν θυσιῶν ἐν μέρει, τῆς τε ὁλοκαύτου καὶ σωτηρίου καὶ περὶ ἁμαρτίας, ἄλλην προσνομοθετεῖ κοινὴν τῶν τριῶν, ἵνα ταύτας ἐπιδείξῃ φίλας καὶ συγγενεῖς οὔσας· ἡ δὲ συναγωγὸς αὐτῶν εὐχὴ μεγάλη καλεῖται.", "st": "247"}, {"sp": "N", "t": "διὰ τί δὲ ταύτης ἔτυχε τῆς προσρήσεως, λεκτέον· ὅταν ἀπάρξωνταί τινες ἀπὸ παντὸς μέρους κτήσεως, πυρούς, κριθάς, ἔλαιον, οἶνον, τὰ κάλλιστα τῶν ἀκροδρύων, ἔπειτα τῶν ζῴων τὰ πρωτότοκα ἀρρενικά, τὰ μὲν ἐκ τῶν καθαρῶν καθιερώσαντες, τὰ δ’ ἐκ τῶν μὴ καθαρῶν κατ’ ἀξίαν τιμησάμενοι, μηκέτ’ ἔχοντες ὕλας, ἐν αἷς διαθήσονται τὴν εὐσέβειαν, αὑτοὺς ἀνατιθέασι καὶ καθιεροῦσιν, ἄλεκτον ἐπιδεικνύμενοι ὁσιότητα καὶ ὑπερβολήν τινα γνώμης φιλοθέου. διὸ καὶ μεγάλη προσηκόντως εὐχὴ καλεῖται· κτημάτων γὰρ τὸ μέγιστον αὐτός τίς ἐστιν αὑτῷ· οὗ παραχωρεῖ καὶ ἐξίσταται.", "st": "248"}, {"sp": "N", "t": "ποιησαμένῳ δὲ τὴν εὐχὴν τάδε διαγορεύει· πρῶτον μὲν ἄκρατον μὴ προσφέρεσθαι μηδ’ “ὅσα ἐκ σταφυλῆς κατεργάζεται” μηδ’ ἄλλο τι μέθυσμα πίνειν ἐπὶ καθαιρέσει λογισμοῦ, νομίζοντα τὸν χρόνον ἐκεῖνον ἱερᾶσθαι· καὶ γὰρ τοῖς λειτουργοῖς τῶν ἱερέων δίψαν ἀκουμένοις ὕδατι τὰ περὶ μέθην ἀπείρηται·", "st": "249"}, {"sp": "N", "t": "δεύτερον δὲ τὰς τρίχας τῆς κεφαλῆς μὴ ἀποκείρεσθαι, σύμβολον ἐναργὲς τοῖς ὁρῶσι παρέχοντα τοῦ μὴ παρακόπτειν τὸ νόμισμα τῆς εὐχῆς· τρίτον δὲ τὸ σῶμα φυλάττειν καθαρὸν καὶ ἀμίαντον, ὡς μὴ γονεῦσιν ἐπεισιέναι τετελευτηκόσι μηδ’ ἀδελφοῖς, τὴν φυσικὴν εὔνοιαν καὶ συμπάθειαν πρὸς τὰ οἰκεῖα καὶ φίλτατα νικώσης εὐσεβείας, ἣν ἀεὶ νικᾶν καλὸν ὁμοῦ καὶ", "st": "250"}, {"sp": "N", "t": "συμφέρον. ἡκούσης δὲ τῆς προθεσμίας, τρία ζῷα κελεύει προσάγειν ἐπὶ λύσει τῆς εὐχῆς, ἄρνα καὶ ἀμνάδα καὶ κριόν, τὸν μὲν εἰς ὁλοκαύτωσιν, τὴν δὲ περὶ ἁμαρτίας, τὸν δὲ κριὸν εἰς θυσίαν τοῦ σωτηρίου.", "st": "251"}, {"sp": "N", "t": "πᾶσι γὰρ τούτοις ἐμφέρεταί πως ὁ εὐξάμενος, τῇ μὲν ὁλοκαύτῳ θυσίᾳ διὰ τὸ μὴ τῶν ἄλλων μόνον ἀπαρχῶν ἀλλὰ καὶ ἑαυτοῦ παραχωρεῖν, τῇ δὲ περὶ ἁμαρτίας διὰ τὸ ἄνθρωπος εἶναι—καὶ γὰρ ὁ τέλειος ᾗ γενητὸς οὐκ ἐκφεύγει τὸ διαμαρτάνειν —, τῇ δὲ τοῦ σωτηρίου, διότι τὸν σωτῆρα ὄντως θεὸν ἐπιγέγραπται τῆς σωτηρίας αἴτιον, ἀλλ’ οὐκ ἰατροὺς καὶ τὰς παρ’ αὐτοῖς δυνάμεις· οἱ μὲν γὰρ ἐπίκηροι καὶ θνητοὶ μηδ’ αὑτοῖς ὑγείαν ἱκανοὶ παρασχεῖν, αἱ δ’ οὔτε πάντας οὔτ’ ἀεὶ τοὺς αὐτοὺς ὠφελοῦσιν, ἀλλ’ ἔστιν ὅτι καὶ μέγα βλάπτουσιν, ἐπειδὴ τὸ κῦρος ἕτερος ἀνῆπται καὶ τῶν δυνάμεων καὶ τῶν χρωμένων αὐταῖς.", "st": "252"}, {"sp": "N", "t": "ἐκπλήττει δέ με τὸ τῶν τριῶν ζῴων προσαγομένων εἰς διαφερούσας θυσίας μηδὲν εἶναι ἑτερογενές, ἀλλὰ ταὐτοῦ γένους τὰ πάντα, κριὸν καὶ ἄρνα καὶ ἀμνάδα· βούλεται γάρ, ὅπερ ἔφην μικρῷ πρότερον, διὰ τούτου παραστῆσαι, ὅτι ἀδελφαὶ καὶ συγγενεῖς εἰσιν αἱ τρεῖς ἰδέαι τῶν θυσιῶν, τῷ καὶ τὸν μετανοοῦντα σῴζεσθαι καὶ τὸν σῳζόμενον ἐκ τῶν ψυχικῶν ἀρρωστημάτων μετανοεῖν καὶ ἑκάτερον σπεύδειν πρὸς ὁλόκληρον καὶ παντελῆ διάθεσιν, ἧς ἡ ὁλόκαυτος θυσία σύμβολον.", "st": "253"}, {"sp": "N", "t": "ἐπεὶ δ’ αὑτὸν ηὔξατο προσαγαγεῖν, τὸν δ’ ἱερὸν βωμὸν οὐ θέμις αἵματι ἀνθρωπίνῳ μιαίνεσθαι, ἔδει δέ τι πάντως μέρος ἱερουργηθῆναι, μέρος ἐσπούδασε λαβεῖν, ὅπερ ἀφαιρεθὲν οὔτ’ ἀλγηδόνας οὔτε λώβην ἀπεργάζεται· τοῦ γὰρ κατὰ τὸ σῶμα φυτικοῦ καθάπερ δένδρου περιττοὺς κλάδους τὰς τῆς κεφαλῆς τρίχας ἀπέκειρε καὶ παρέδωκε πυρί, ᾧ τὰ κρέα τῆς τοῦ σωτηρίου θυσίας ἕψεται· προσηκόντως, ἵνα τι τῶν τοῦ εὐξαμένου μέρος, ὃ μὴ ἐπιφέρειν ἔξεστι τῷ βωμῷ, θυσίας γοῦν εἴδει συνανακραθῇ, γενόμενον ὕλη φλογὸς ἱερᾶς.", "st": "254"}, {"sp": "N", "t": "Ταῦτα μὲν κοινὰ τῶν ἄλλων. ἔδει δὲ καὶ τοὺς ἱερεῖς ἀπάρξασθαί τι τῷ βωμῷ, μὴ νομίσαντας ἀσυλίαν εὑρῆσθαι τὰς ὑπηρεσίας καὶ λειτουργίας ἐφ’ ὧν ἐτάχθησαν. ἡ δ’ ἀπαρχὴ πρέπουσα ἱερεῦσιν ἀπ’ οὐδενὸς τῶν ἐναίμων, ἀλλ’ ἀπὸ τοῦ καθαρωτάτου τῆς ἀνθρωπίνης τροφῆς·", "st": "255"}, {"sp": "N", "t": "σεμίδαλις γάρ ἐστιν ἡ ἐνδελεχὴς αὐτῶν θυσία, μέτρου ἱεροῦ τὸ δέκατον καθ’ ἑκάστην ἡμέραν, οὗ τὸ μὲν ἥμισυ πρωΐας, τὸ δὲ ἥμισυ δείλης προσάγεται, ταγηνισθὲν ἐν ἐλαίῳ, μηδενὸς εἰς βρῶσιν ὑπολειφθέντος· χρησμὸς γάρ ἐστι, πᾶσαν θυσίαν ἱερέως ὁλόκαυτον εἶναι καὶ μηδὲν αὐτῆς εἰς ἐδωδὴν ἀπονέμεσθαι. εἰρηκότες οὖν, ὡς οἷόν τε ἦν, τὰ περὶ θυσιῶν ἑξῆς καὶ περὶ τῶν θυόντων λέξομεν.", "st": "256"}, {"sp": "N", "t": "Βούλεται τὸν ἀνάγοντα θυσίας ὁ νόμος καθαρὸν εἶναι σῶμα καὶ ψυχήν, ψυχὴν μὲν ἀπό τε τῶν παθῶν καὶ νοσημάτων καὶ ἀρρωστημάτων καὶ κακιῶν τῶν ἔν τε λόγοις καὶ πράξεσι, τὸ δὲ σῶμα ἀφ’ ὧν ἔθος", "st": "257"}, {"sp": "N", "t": "αὐτῷ μιαίνεσθαι. κάθαρσιν δ’ ἐπενόησεν ἑκατέρῳ τὴν προσήκουσαν, ψυχῇ μὲν διὰ τῶν πρὸς τὰς θυσίας εὐτρεπιζομένων ζῴων, σώματι δὲ διὰ λουτρῶν καὶ περιρραντηρίων, περὶ ὧν μικρὸν ὕστερον ἐροῦμεν· ἄξιον γὰρ τῷ κρείττονι καὶ ἡγεμονικωτέρῳ τῶν ἐν ἡμῖν, ψυχῇ, καὶ τὰ τῶν λόγων ἀπονεῖμαι πρεσβεῖα. τίς οὖν ἡ ταύτης κάθαρσις;", "st": "258"}, {"sp": "N", "t": "ἴδε, φησίν, ᾧ οὗτος, ὃ προσάγεις ἱερεῖον, ὡς ἔστιν ὁλόκληρον καὶ παντελῶς μώμων ἀμέτοχον, ἐπικριθὲν ἐκ πολλῶν ἀριστίνδην διανοίαις μὲν ἀδεκάστοις ἱερέων ὀξυωπεστάταις δ’ αὐτῶν ὄψεσι καὶ τῷ συνεχεῖ τῆς ἀσκήσεως συγκεκροτημέναις εἰς ἀνυπαίτιον ἐπίσκεψιν· ἐὰν γὰρ μὴ τοῖς ὀφθαλμοῖς μᾶλλον ἢ τῷ λογισμῷ τοῦτο κατίδῃς, ἐκνίψῃ τὰ ἁμαρτήματα καὶ ὅσας ἐν ἅπαντι τῷ βίῳ κηλῖδας ἀπεμάξω, τὰ μὲν ἀβουλήτοις συντυχίαις, τὰ δὲ καθ’ ἑκούσιον γνώμην.", "st": "259"}, {"sp": "N", "t": "εὑρήσεις γὰρ τὴν τοσαύτην περὶ τὸ ζῷον ἀκριβολογίαν αἰνιττομένην διὰ συμβόλου τὴν τῶν σῶν βελτίωσιν ἠθῶν· οὐ γὰρ ὑπὲρ ἀλόγων ὁ νόμος, ἀλλ’ ὑπὲρ τῶν νοῦν καὶ λόγον ἐχόντων, ὥστε οὐ τῶν θυομένων φροντίς ἐστιν, ἵνα μηδεμίαν ἔχῃ λώβην, ἀλλὰ τῶν θυόντων, ἵνα περὶ μηδὲν πάθος κηραίνωσι.", "st": "260"}, {"sp": "N", "t": "τό γε μὴν σῶμα, ὡς εἶπον, λουτροῖς καὶ περιρραντηρίοις καθαίρει καὶ οὐκ ἐᾷ περιρρανάμενον εἰς ἅπαξ ἢ ἀπολουσάμενον εὐθὺς εἴσω περιβόλων ἱερῶν παρέρχεσθαι, ἀλλὰ ἑπτὰ ἡμέρας ἔξω διατρίβειν κελεύει καὶ δὶς περιρραίνεσθαι τῇ τρίτῃ καὶ ἑβδόμῃ καὶ μετὰ ταῦτα λουσαμένῳ παρέχει τάς τε εἰσόδους καὶ τὰς ἱερουργίας ἀδεεῖς.", "st": "261"}, {"sp": "N", "t": "ὅσον δὲ κἀν τούτῳ τὸ προμηθὲς καὶ φιλόσοφον, ἐπισκεπτέον. οἱ μὲν ἄλλοι σχεδὸν ἅπαντες ἀμιγεῖ ὕδατι περιρραίνονται, θαλάττῃ μὲν οἱ πολλοί, τινὲς δὲ ποταμοῖς, οἱ δὲ καὶ κάλπεσιν ἐκ πηγῶν ἀρυόμενοι· Μωυσῆς δὲ τέφραν προετοιμασάμενος ὑπολειφθεῖσαν ἐξ ἱεροῦ πυρὸς — ὃν δὲ τρόπον, αὐτίκα δηλωθήσεται — ἀπὸ ταύτης φησὶ δεῖν ἀναιρεῖσθαι καὶ ἐμβάλλοντας εἰς ἀγγεῖον αὖθις ὕδωρ ἐπιφέρειν, εἶτα ἐκ τοῦ κράματος βάπτοντας ὑσσώπου κλάδους τοῖς καθαιρομένοις ἐπιρραίνειν.", "st": "262"}, {"sp": "N", "t": "αἰτία δ’ οὐκ ἀπὸ σκοποῦ λέγοιτ’ ἂν ἥδε· βούλεται τοὺς ἐπὶ τὴν τοῦ ὄντος θεραπείαν ἰόντας γνῶναι πρότερον ἑαυτοὺς καὶ τὴν ἰδίαν οὐσίαν· ὁ γὰρ ἀνεπιστήμων ἑαυτοῦ πῶς ἂν δυνηθείη καταλαβεῖν τὴν ἀνωτάτω καὶ πάνθ’ ὑπερβάλλουσαν θεοῦ δύναμιν;", "st": "263"}, {"sp": "N", "t": "ἔστιν οὖν ἡμῶν ἡ κατὰ τὸ σῶμα οὐσία, γῆ καὶ ὕδωρ, ἧς ὑπομιμνῄσκει διὰ τῆς καθάρσεως, αὐτὸ τοῦθ’ ὑπολαμβάνων εἶναι τὴν ὠφελιμωτάτην κάθαρσιν, τὸ γνῶναί τινα ἑαυτὸν καὶ ἐξ οἵων ὡς οὐδεμιᾶς σπουδῆς ἀξίων, τέφρας καὶ ὕδατος, συνεκράθη.", "st": "264"}, {"sp": "N", "t": "τοῦτο γὰρ ἐπιγνοὺς τὴν ἐπίβουλον οἴησιν εὐθὺς ἀποστραφήσεται καὶ καθελὼν τὸ ὑπέραυχον εὐαρεστήσει θεῷ καὶ μεταποιήσεται τῆς ἵλεω δυνάμεως αὐτοῦ τοῦ μισοῦντος ἀλαζονείαν. εἴρηται γάρ που καλῶς, ὅτι ὁ ἐγχειρῶν ὑπεραύχοις ἢ λόγοις ἢ ἔργοις οὐκ ἀνθρώπους μόνον ἀλλὰ καὶ “θεὸν παροξύνει” τὸν ἰσότητος καὶ παντὸς τοῦ ἀρίστου δημιουργόν.", "st": "265"}, {"sp": "N", "t": "ἐν οὖν τῷ περιρραίνεσθαι πληττομένοις καὶ διεγειρομένοις μόνον οὐκ ἄντικρυς αὐτὰ τὰ στοιχεῖα, γῆ καὶ ὕδωρ, φωνὴν ἀφιέντα φησίν· ἡμεῖς ἐσμεν ἡ τοῦ σώματος ὑμῶν οὐσία, ἡμᾶς ἡ φύσις κερασαμένη θείᾳ τέχνῃ διέπλασεν εἰς ἀνθρωπόμορφον ἰδέαν, ἐξ ἡμῶν παγέντες, ὅτε ἐγένεσθε, πάλιν εἰς ἡμᾶς ἀναλυθήσεσθε, ὅταν δέῃ θνῄσκειν· οὐδὲν γὰρ εἰς τὸ μὴ ὂν φθείρεσθαι πέφυκεν, ἀλλ’ ἐξ ὧν ἡ ἀρχή, πρὸς ταῦτα καὶ τὸ τέλος.", "st": "266"}, {"sp": "N", "t": "Ἤδη δ’ ἀναγκαῖον καὶ τὴν ὑπόσχεσιν ἀποδοῦναι τῆς περὶ τὴν τέφραν ταύτην ἰδιότητος· ἔστι γὰρ οὐ ξύλων αὐτὸ μόνον δαπανηθέντων ὑπὸ πυρός, ἀλλὰ καὶ ζῴου πρὸς τὴν τοιαύτην κάθαρσιν ἐπιτηδείου.", "st": "267"}, {"sp": "N", "t": "κελεύει γὰρ δάμαλιν πυρρὰν ἄζυγον ἄμωμον ἀχθεῖσαν σφαγιασθῆναι μὲν ἔξω πόλεως, τὸν δ’ ἀρχιερέα λαμβάνοντα ἀπὸ τοῦ αἵματος ἑπτάκις ἐπιρραίνειν ἀντικρὺ τοῦ νεὼ πάντα, εἶθ’ ὅλην κατακαίειν σὺν δορᾷ καὶ κρέασι καὶ αἵματι καὶ πλήρει τῇ κοιλίᾳ περιττωμάτων· ἤδη δ’ ὑπομαραινομένης τῆς φλογὸς εἰς τὸ μεσαίτατον τρία ταῦτα ἐμβάλλειν, ξύλον κέδρινον καὶ ὕσσωπον καὶ κόκκινον, κελεύει, εἶτ’ ἐὰν ἀποσβεσθῇ, τὴν τέφραν συλλέγειν καθαρὸν ἄνθρωπον καὶ ἀποτιθέναι πάλιν ἔξω πόλεως ἐν χωρίῳ καθαρῷ.", "st": "268"}, {"sp": "N", "t": "τίνα δὲ διὰ τούτων ὡς διὰ συμβόλων αἰνίττεται, δι’ ἑτέρων ἠκριβώσαμεν ἀλληγοροῦντες. ἀναγκαῖον οὖν τοὺς μέλλοντας φοιτᾶν εἰς τὸ ἱερὸν ἐπὶ μετουσίᾳ θυσίας τό τε σῶμα φαιδρύνεσθαι καὶ τὴν ψυχὴν πρὸ τοῦ σώματος· δεσπότις γὰρ καὶ βασιλὶς καὶ ἐν ἅπασι κρείττων ἅτε θειοτέρας φύσεως μεταλαχοῦσα. τὰ δὲ φαιδρύνοντα διάνοιάν ἐστι σοφία καὶ τὰ σοφίας δόγματα πρὸς τὴν θεωρίαν τοῦ κόσμου καὶ τῶν ἐν αὐτῷ ποδηγετοῦντα καὶ ὁ τῶν ἄλλων ἀρετῶν ἱερὸς χορὸς καὶ αἱ κατ’ ἀρετὰς καλαὶ καὶ σφόδρα ἐπαινεταὶ πράξεις.", "st": "269"}, {"sp": "N", "t": "ὁ μὲν οὖν τούτοις διακεκοσμημένος ἴτω θαρρῶν εἰς οἰκειότατον αὐτῷ τὸν νεών, ἐνδιαίτημα πάντων ἄριστον, ἱερεῖον ἐπιδειξόμενος αὑτόν· ὅτῳ δ’ ἐγκάθηνται καὶ ἐλλοχῶσιν αἱ πλεονεξίαι καὶ ἐπιθυμίαι τῶν ἀδικιῶν, ἐγκαλυψάμενος ἠρεμείτω τὴν ἀναίσχυντον ἀπόνοιαν καὶ τὸ λίαν θράσος ἐν οἷς εὐλάβεια λυσιτελὲς ἐπισχών· τὸ γὰρ τοῦ ὄντως ὄντος ἱερὸν ἀνιέροις ἄβατον θυσίαις.", "st": "270"}, {"sp": "N", "t": "εἴποιμ’ ἄν· ὦ γενναῖε, ὁ θεὸς οὐ χαίρει, κἂν ἑκατόμβας ἀνάγῃ τις· κτήματα γὰρ αὐτοῦ τὰ πάντα, κεκτημένος ὅμως οὐδενὸς δεῖται· χαίρει δὲ φιλοθέοις γνώμαις καὶ ἀνδράσιν ἀσκηταῖς ὁσιότητος, παρ’ ὧν ψαιστὰ καὶ κριθὰς καὶ τὰ εὐτελέστατα ὡς τιμιώτατα πρὸ τῶν πολυτελεστάτων ἄσμενος δέχεται·", "st": "271"}, {"sp": "N", "t": "κἂν μέντοι μηδὲν ἕτερον κομίζωσιν, αὑτοὺς φέροντες πλήρωμα καλοκἀγαθίας τελειότατον τὴν ἀρίστην ἀνάγουσι θυσίαν, ὕμνοις καὶ εὐχαριστίαις τὸν εὐεργέτην καὶ σωτῆρα θεὸν γεραίροντες, τῇ μὲν διὰ τῶν φωνητηρίων ὀργάνων, τῇ δὲ ἄνευ γλώττης καὶ στόματος, μόνῃ ψυχῇ τὰς νοητὰς ποιούμενοι διεξόδους καὶ ἐκβοήσεις, ὧν ἓν μόνον οὖς ἀντιλαμβάνεται τὸ θεῖον· αἱ γὰρ τῶν ἀνθρώπων οὐ φθάνουσιν ἀκοαὶ συναισθέσθαι.", "st": "272"}, {"sp": "N", "t": "Ὡς δ’ ἀψευδής ἐστιν οὗτος ὁ λόγος καὶ οὐκ ἐμὸς ἀλλὰ τῆς φύσεως, μαρτυρεῖ μέν πως καὶ ἡ ἐνάργεια τρανὴν παρέχουσα πίστιν τοῖς μὴ διὰ τὸ φιλόνεικον ἐπιτηδεύουσιν ἀπιστίαν, μαρτυρεῖ δὲ καὶ ὁ νόμος προστάξας δύο κατασκευασθῆναι βωμοὺς καὶ ταῖς ὕλαις καὶ τοῖς τόποις καὶ ταῖς χρείαις διαφέροντας·", "st": "273"}, {"sp": "N", "t": "ὁ μὲν γὰρ ἐκ λίθων λογάδων ἀτμήτων συνῳκοδόμηται καὶ ἐν ὑπαίθρῳ παρὰ ταῖς τοῦ νεὼ προσβάσεσιν ἵδρυται καὶ γέγονε πρὸς χρείαν τὴν τῶν ἐναίμων· ὁ δὲ χρυσοῦ μὲν τοῦ καθαρωτάτου κατεσκεύασται, ἵδρυται δ’ ἐν ἀδύτοις εἴσω τοῦ προτέρου καταπετάσματος, ὃς οὐδενὶ τῶν ἄλλων ἐστὶν ὁρατὸς ὅτι μὴ τοῖς ἁγνεύουσι τῶν ἱερέων καὶ γέγονε πρὸς χρείαν τὴν τῶν θυμιαμάτων.", "st": "274"}, {"sp": "N", "t": "ἐξ οὗ δῆλόν ἐστιν, ὅτι καὶ βραχύτατον λιβανωτὸν παρ’ ἀνδρὸς ὁσίου τιμιώτερον ὁ θεὸς νομίζει μυρίων θρεμμάτων, ὅσα ἄν τις ἱερουργῇ μὴ σφόδρα ἀστεῖος ὤν· ὅσῳ γάρ, οἶμαι, λίθων μὲν εἰκαίων ἀμείνων χρυσός, τὰ δ’ ἐν ἀδύτοις τῶν ἐκτὸς ἁγιώτερα, τοσούτῳ κρείττων ἡ διὰ τῶν ἐπιθυμιωμένων εὐχαριστία τῆς διὰ τῶν ἐναίμων.", "st": "275"}, {"sp": "N", "t": "ὅθεν οὐ μόνον ὕλης πολυτελείᾳ καὶ κατασκευῇ καὶ τόπῳ τετίμηται ὁ τῶν θυμιαμάτων βωμός, ἀλλὰ καὶ τῷ πρότερον καθ’ ἑκάστην ἡμέραν ὑπηρετεῖν ταῖς πρὸς θεὸν ἀνθρώπων εὐχαριστίαις· οὐ γὰρ ἐφεῖται τὴν ὁλόκαυτον θυσίαν ἔξω προσαγαγεῖν, πρὶν ἔνδον περὶ βαθὺν ὄρθρον ἐπιθυμιᾶσαι.", "st": "276"}, {"sp": "N", "t": "τὸ δ’ ἐστὶ σύμβολον οὐχ ἑτέρου τινὸς ἢ τοῦ παρὰ θεῷ μὴ τὸ πλῆθος τῶν καταθυομένων εἶναι τίμιον, ἀλλὰ τὸ καθαρώτατον τοῦ θύοντος πνεῦμα λογικόν· εἰ μὴ ἄρα δικαστὴς μέν, ᾧ μέλει τῆς ὁσίας κρίσεως, παρά τινος τῶν κρινομένων οὐκ ἂν λάβοι δῶρα ἢ λαβὼν ἔνοχος ἔσται δωροδοκίᾳ, οὐδ’ ἀνὴρ ἀστεῖος παρὰ μοχθηροῦ τινος, ἄνθρωπος παρ’ ἀνθρώπου πλουτοῦντος αὐτὸς ἴσως δεόμενος, σὺ δ’ ᾠήθης τὸν θεὸν δεκάζεσθαι, τὸν αὐταρκέστατον ἑαυτῷ καὶ μηδενὸς τῶν ἐν γενέσει χρεῖον, ὅστις ὢν τὸ πρῶτον ἀγαθόν, τὸ τελειότατον, ἡ ἀέναος πηγὴ φρονήσεως καὶ δικαιοσύνης καὶ πάσης ἀρετῆς, ἀποστρέφεται τὰς παρὰ τῶν ἀδίκων δωρεάς.", "st": "277"}, {"sp": "N", "t": "ὁ δὲ κομίζων οὐ πάντων ἀναισχυντότατος ἐξ ὧν ἔκλεψεν ἢ ἥρπασεν ἢ ἠρνήσατο ἢ ἀπεστέρησε μέρος ὡς κοινωνῷ τῆς ἑαυτοῦ κακίας καὶ πλεονεξίας διδούς; πάντων κακοδαιμονέστατε, εἴποιμ’ ἂν τῷ τοιούτῳ, δυοῖν θάτερον ἢ λήσεσθαι προσδοκᾷς ἢ καταφανήσεσθαι·", "st": "278"}, {"sp": "N", "t": "λήσεσθαι μὲν οὖν ὑπολαμβάνων ἀνεπιστήμων εἶ θεοῦ δυνάμεως, καθ’ ἣν ἅμα πάντα ὁρᾷ καὶ πάντων ἀκούει· νομίζων δ’ ἐμφανήσεσθαι θρασύτατος εἶ· δέον ἐφ’ οἷς ἥμαρτες ἐγκαλύπτεσθαι, προφέρεις εἰς μέσον τὰ δείγματα ὧν ἠδίκησας καὶ ἐπισεμνυνόμενος διανέμῃ πρὸς θεόν, ἀπαρχὰς αὐτῷ κομίζων ἀνοσίους, καὶ οὐκ ἐλογίσω τοῦθ’ ὅτι οὔτε νόμος ἀνομίαν παραδέχεται οὔτε φῶς ἡλιακὸν σκότος. ὁ δὲ θεὸς καὶ νόμων ἐστὶ παράδειγμα ἀρχέτυπον καὶ ἡλίου ἥλιος, νοητὸς αἰσθητοῦ, παρέχων ἐκ τῶν ἀοράτων πηγῶν ὁρατὰ φέγγη τῷ βλεπομένῳ.", "st": "279"}, {"sp": "N", "t": "Πάνυ καλῶς ἐν ταῖς ἱεραῖς τοῦ νόμου στήλαις κἀκεῖνο ἀναγέγραπται, μίσθωμα πόρνης εἰς τὸ ἱερὸν μὴ κομίζειν πεπρακυίας τὴν ἰδίαν ὥραν, ἑλομένης ἕνεκα λημμάτων αἰσχρῶν ἐπονείδιστον βίον.", "st": "280"}, {"sp": "N", "t": "εἰ δὲ τὰ παρὰ γυναικὸς ἡταιρηκυίας δῶρα ἀνίερα, πῶς οὐχὶ μᾶλλον τὰ παρὰ ψυχῆς πεπορνευμένης, ἥτις παρέρριψεν ἑαυτὴν ἐπ’ αἰσχύνῃ καὶ ὕβρεσι ταῖς ἐσχάταις, οἰνοφλυγίαις, ὀψοφαγίαις, φιλαργυρίαις, φιλοδοξίαις, φιληδονίαις, ἄλλαις μυρίαις παθῶν τε αὖ καὶ νοσημάτων καὶ κακιῶν ἰδέαις; ὧν τὰ μιάσματα ἐκεῖνα τίς ἂν ἐκνίψαι χρόνος; ἔγωγε οὐκ οἶδα.", "st": "281"}, {"sp": "N", "t": "τῶν μὲν γὰρ ἑταιρῶν τὴν ἐργασίαν κατέλυσε πολλάκις γῆρας, ἐπειδήπερ ἐξώροις γενομέναις οὐδεὶς ἔτι πρόσεισιν, ἀπομαρανθείσης ὥσπερ τινῶν ἀνθῶν τῆς ἀκμῆς· ψυχῆς δὲ πορνείαν ἀκολασίᾳ συντρόφῳ καὶ συνήθει πεπαιδοτριβημένης τίς ἂν αἰὼν μεταβάλοι πρὸς εὐκοσμίαν; αἰὼν μὲν οὔ, θεὸς δὲ μόνος, ᾧ δυνατὰ τὰ παρ’ ἡμῖν ἀδύνατα.", "st": "282"}, {"sp": "N", "t": "δεῖ δὴ τὸν μέλλοντα θύειν σκέπτεσθαι, μὴ εἰ τὸ ἱερεῖον ἄμωμον, ἀλλ’ εἰ ἡ διάνοια ὁλόκληρος αὐτῷ καὶ παντελὴς καθέστηκε. διερευνάτω μέντοι καὶ τὰς αἰτίας, ὧν ἕνεκα ἀνάγειν ἀξιοῖ θυσίας· ἤτοι γὰρ εὐχαριστῶν ἐπὶ προϋπηργμέναις εὐεργεσίαις ἢ βεβαιότητα παρόντων ἢ μελλόντων κτῆσιν ἀγαθῶν αἰτούμενος ἢ κακῶν παρόντων ἢ προσδοκωμένων ἀποτροπήν, ἐφ’ οἷς ἅπασιν ὑγείαν καὶ σωτηρίαν ἐκπορίζειν ὀφείλει τῷ λογισμῷ.", "st": "283"}, {"sp": "N", "t": "εἴτε γὰρ ἐπὶ προϋπηργμέναις εὐχαριστεῖ, μὴ ἀχαριστησάτω φαῦλος γενόμενος — σπουδαίῳ γὰρ ἐδόθησαν αἱ χάριτες —, εἴτε βεβαιούμενος τὰ παρόντα ἀγαθὰ καὶ χρηστὰ περὶ τῶν μελλόντων προσδοκῶν, ἄξιον αὑτὸν παρεχέτω τῶν εὐπραγιῶν ἀστεῖος ὤν, εἴτε κακῶν τινων φυγὴν αἰτούμενος, μὴ δράτω κολάσεων ἐπάξια καὶ τιμωριῶν.", "st": "284"}, {"sp": "N", "t": "Πῦρ, φησίν, ἐπὶ τοῦ θυσιαστηρίου καυθήσεται διὰ παντὸς ἄσβεστον· εἰκότως, οἶμαι, καὶ προσηκόντως· ἐπειδὴ γὰρ αἱ τοῦ θεοῦ χάριτες ἀέναοι καὶ ἀνελλιπεῖς καὶ ἀδιάστατοι, ὧν μεθ’ ἡμέραν καὶ νύκτωρ οἱ ἄνθρωποι τυγχάνουσιν, καὶ τὸ σύμβολον τῆς εὐχαριστίας, ἡ ἱερὰ φλόξ, ζωπυρείσθω καὶ ἀεὶ ἄσβεστος ἔστω.", "st": "285"}, {"sp": "N", "t": "τάχα μέντοι καὶ διὰ τοῦδε βούλεται τὰς παλαιὰς ταῖς νέαις θυσίαις ἁρμόσασθαι καὶ ἑνῶσαι τῇ μονῇ καὶ παρουσίᾳ τοῦ αὐτοῦ πυρός, ᾧ πᾶσαι καθιεροῦνται, πρὸς ἔνδειξιν τοῦ τελείας ἐν εὐχαριστίαις εἶναι, κἂν ἀπὸ μυρίων ὅσων ἀφορμῶν γίνωνται κατὰ περιουσίας ἀφθόνους ἢ τοὐναντίον ἐνδείας τῶν προσαγομένων.", "st": "286"}, {"sp": "N", "t": "τὰ μὲν ῥητὰ ταῦτα [σύμβολα νοητῶν], τὰ δὲ πρὸς διάνοιαν τοῖς τῆς ἀλληγορίας κανόσιν ἐπισκεπτέον· πρὸς ἀλήθειαν τοῦ θεοῦ θυσιαστήριόν ἐστιν ἡ εὐχάριστος τοῦ σοφοῦ ψυχὴ παγεῖσα ἐκ τελείων ἀρετῶν ἀτμήτων καὶ ἀδιαιρέτων· οὐδὲν γὰρ μέρος ἀρετῆς ἀχρεῖον.", "st": "287"}, {"sp": "N", "t": "ἐπὶ ταύτης ἀεὶ τὸ ἱερὸν φῶς ἀνακαίεται φυλαττόμενον ἄσβεστον· διανοίας δὲ φῶς ἐστι σοφία, ἐπεὶ καὶ τοὐναντίον σκότος ψυχῆς ἀφροσύνη· ὅπερ γὰρ αἰσθητὸν φῶς ὀφθαλμοῖς πρὸς κατάληψιν σωμάτων, τοῦτ’ ἐπιστήμη λογισμῷ πρὸς θεωρίαν τῶν ἀσωμάτων καὶ νοητῶν, ἧς ἀεὶ τὸ φέγγος ἐπιλάμπει μηδέποτε ἀμαυρούμενον ἢ σβεννύμενον.", "st": "288"}, {"sp": "N", "t": "Μετὰ ταῦτά φησιν· “ἐπὶ παντὸς δώρου προσοίσετε ἅλα”, δι’ οὗ, καθάπερ καὶ πρότερον εἶπον, τὴν εἰς ἅπαν διαμονὴν αἰνίττεται· φυλακτήριον γὰρ οἱ ἅλες σωμάτων, τετιμημένοι ψυχῆς δευτερείοις· ὡς γὰρ αἰτία τοῦ μὴ διαφθείρεσθαι τὰ σώματα ψυχή, καὶ οἱ ἅλες ἐπὶ πλεῖστον αὐτὰ συνέχοντες καὶ τρόπον τινὰ ἀθανατίζοντες.", "st": "289"}, {"sp": "N", "t": "διὸ καὶ κέκληκε θυσιαστήριον, ἴδιον καὶ ἐξαίρετον ὄνομα θέμενος αὐτῷ παρὰ τὸ διατηρεῖν, ὡς ἔοικε, τὰς θυσίας, καίτοι τῶν κρεῶν ἀναλισκομένων ὑπὸ πυρός· ὡς εἶναι σαφεστάτην πίστιν, ὅτι οὐ τὰ ἱερεῖα θυσίαν ἀλλὰ τὴν διάνοιαν καὶ προθυμίαν ὑπολαμβάνει τοῦ καταθύοντος εἶναι, ἐν ᾗ τὸ μόνιμον καὶ βέβαιον ἐξ ἀρετῆς.", "st": "290"}, {"sp": "N", "t": "προσέτι κἀκεῖνο προσνομοθετεῖ, κελεύων πᾶσαν θυσίαν δίχα ζύμης καὶ μέλιτος προσάγεσθαι, μηδέτερον ἀξιῶν ἀναφέρειν ἐπὶ τὸ θυσιαστήριον· μέλι μὲν ἴσως, ἐπειδήπερ ἡ συναγωγὸς αὐτοῦ μέλιττα ζῷόν ἐστιν οὐ καθαρόν, ἐκ σήψεως καὶ φθορᾶς νεκρῶν, ὡς ὁ λόγος, βοῶν γεννώμενον, καθὰ καὶ οἱ σφῆκες ἐξ ἱππείων σωμάτων·", "st": "291"}, {"sp": "N", "t": "ἢ κατὰ σύμβολον τοῦ πᾶσαν ἀνίερον εἶναι τὴν περιττὴν ἡδονήν, τὰ μὲν περὶ τὴν κατάποσιν γλυκαίνουσαν, πικρὰς δὲ καὶ δυσιάτους αὖθις ἐπιφέρουσαν ἀλγηδόνας, ὑφ’ ὧν ἀνάγκη τὴν ψυχὴν σείεσθαι καὶ κλονεῖσθαι παγίως ἱδρυθῆναι μὴ δυναμένην·", "st": "292"}, {"sp": "N", "t": "ζύμην δὲ διὰ τὴν γινομένην ἔπαρσιν ἐξ αὐτῆς, πάλιν συμβολικῶς, ἵνα μηδεὶς προσιὼν τῷ θυσιαστηρίῳ τὸ παράπαν ἐπαίρηται φυσηθεὶς ὑπ’ ἀλαζονείας, ἀλλ’ εἰς τὸ τοῦ θεοῦ μέγεθος ἀποβλέπων αἴσθησιν λαμβάνῃ τῆς περὶ τὸ γενητὸν ἀσθενείας, κἂν εὐτυχίαις ἑτέρων διαφέρῃ, καὶ τὸν εἰκότα ποιησάμενος λογισμὸν στέλλῃ τὸ τοῦ φρονήματος ὑπέραυχον ὕψος, τὴν ἐπίβουλον οἴησιν καθαιρῶν.", "st": "293"}, {"sp": "N", "t": "εἰ γὰρ ὁ τῶν ὅλων κτίστης καὶ ποιητὴς καὶ πάντων ἀνεπιδεὴς ὧν ἐγέννησεν, οὐ πρὸς τὰς ὑπερβολὰς τοῦ κράτους αὑτοῦ καὶ τῆς ἐξουσίας ἀπιδὼν ἀλλὰ πρὸς τὴν σὴν ἀσθένειαν, μεταδίδωσί σοι τῆς ἵλεω δυνάμεως αὑτοῦ τὰς ἐνδείας ἀναπληρῶν αἷς κέχρησαι, σὲ τί ποιεῖν ἁρμόττει πρὸς ἀνθρώπους τοὺς φύσει συγγενεῖς καὶ ἀπὸ τῶν αὐτῶν στοιχείων σπαρέντας, τὸν μηδὲν εἰς τὸν κόσμον ἀλλὰ μηδὲ σαυτὸν εἰσενηνοχότα;", "st": "294"}, {"sp": "N", "t": "γυμνὸς μὲν γάρ, θαυμάσιε, ἦλθες, γυμνὸς δὲ πάλιν ἄπεις, τὸν μεταξὺ χρόνον γενέσεως καὶ θανάτου παρὰ τοῦ θεοῦ χρῆσιν λαβών, ἐν ᾧ τί ποιεῖν προσῆκον ἦν ἢ κοινωνίας καὶ ὁμονοίας ἰσότητός τε καὶ φιλανθρωπίας καὶ τῆς ἄλλης ἀρετῆς ἐπιμελεῖσθαι, ἀποβαλλόμενον τὴν ἄνισον καὶ ἄδικον καὶ ἀσύμβατον κακίαν, ἣ τὸ ἡμερώτατον φύσει ζῷον, ἄνθρωπον, ὠμὸν καὶ ἀτίθασον ἐργάζεται;", "st": "295"}, {"sp": "N", "t": "Πάλιν ἀφ’ ἑσπέρας ἕως πρωίας προστάττει καίεσθαι λύχνους ἐπὶ τῆς ἱερᾶς λυχνίας εἴσω τοῦ καταπετάσματος, πολλῶν χάριν· ἑνὸς μὲν ἵνα ἐκ διαδοχῆς τοῦ μεθημερινοῦ φωτὸς καταλάμπηται τὰ ἅγια γινόμενα ἀεὶ σκότους ἀμέτοχα καθ’ ὁμοιότητα τῶν ἀστέρων· καὶ γὰρ οὗτοι δύντος ἡλίου τὸ ἴδιον ἀναφαίνουσι φέγγος ἣν ἐτάχθησαν ἐν τῷ κόσμῳ τάξιν οὐ λείποντες·", "st": "296"}, {"sp": "N", "t": "ἑτέρου δὲ τοῦ καὶ νύκτωρ ἀδελφόν τι καὶ συγγενὲς ταῖς μεθημεριναῖς θυσίαις ἐπιτελεῖσθαι πρὸς ἀρέσκειαν θεοῦ καὶ μηδένα χρόνον ἢ καιρὸν εὐχαριστίας παραλείπειν· ἐπιτηδειοτάτη δὲ καὶ προσφυεστάτη νυκτὶ τῆς εὐχαριστίας θυσία — θυσίαν γὰρ αὐτὴν ἄξιον καλεῖν — ἡ τοῦ ἱερωτάτου φέγγους ἐν τοῖς ἀδύτοις αὐγή·", "st": "297"}, {"sp": "N", "t": "τρίτου δὲ καὶ σφόδρα ἀναγκαίου· ἐπειδὴ γὰρ οὐ μόνον ἐγρηγορότες εὖ πάσχομεν ἀλλὰ καὶ καθεύδοντες, τοῦ φιλοδώρου θεοῦ μεγάλην ἐπικουρίαν, ὕπνον, τῷ θνητῷ γένει παρασχόντος ἐπ’ ὠφελείᾳ σώματός τε καὶ ψυχῆς, τοῦ μὲν σώματος τῶν μεθημερινῶν πόνων ἀφιεμένου, τῆς δὲ ψυχῆς ἐπικουφιζομένης τὰς φροντίδας καὶ ἀναχωρούσης εἰς ἑαυτὴν ἀπὸ τοῦ τῶν αἰσθήσεων ὄχλου καὶ θορύβου καὶ δυναμένης τότε γοῦν ἰδιάζειν καὶ ἐνομιλεῖν ἑαυτῇ, προσηκόντως ἐδικαίωσεν ὁ νόμος τὰς εὐχαριστίας διακληρῶσαι, ὑπὲρ μὲν ἐγρηγόρσεως διὰ τῶν προσαγομένων ἱερείων, ὑπὲρ δὲ ὕπνου καὶ τῶν ἀπὸ τοῦδε ὠφελειῶν διὰ τῆς τῶν ἱερῶν λύχνων ἐξάψεως.", "st": "298"}, {"sp": "N", "t": "Ἃ μὲν οὖν πρὸς εὐσέβειαν νομοθετεῖται κατὰ προστάξεις καὶ ἀπαγορεύσεις, ταῦτα καὶ τὰ τούτοις παραπλήσιά ἐστιν· ἃ δὲ κατὰ τὰς φιλοσόφους ὑποθήκας καὶ παραινέσεις, ὧδε λεκτέον. αἰτεῖται γάρ, φησίν, ὦ διάνοια, παρὰ σοῦ ὁ θεὸς οὐδὲν βαρὺ καὶ ποικίλον ἢ δύσεργον ἀλλὰ ἁπλοῦν πάνυ καὶ ῥᾴδιον.", "st": "299"}, {"sp": "N", "t": "ταῦτα δ’ ἐστὶν ἀγαπᾶν αὐτὸν ὡς εὐεργέτην, εἰ δὲ μή, φοβεῖσθαι γοῦν ὡς ἄρχοντα καὶ κύριον, καὶ διὰ πασῶν ἰέναι τῶν εἰς ἀρέσκειαν ὁδῶν καὶ λατρεύειν αὐτῷ μὴ παρέργως ἀλλὰ ὅλῃ τῇ ψυχῇ πεπληρωμένῃ γνώμης φιλοθέου καὶ τῶν ἐντολῶν αὐτοῦ περιέχεσθαι καὶ τὰ δίκαια τιμᾶν. ἐξ ὧν ἁπάντων αὐτὸς μὲν ἐν ὁμοίᾳ μένει φύσει μὴ τρεπόμενος. ἔτι δὲ τῶν ἄλλων ὅσα κατὰ τὸν κόσμον ἐστὶ βελτίωσιν ἴσχει, ἥλιος ἢ σελήνη ἢ τὸ πλῆθος τῶν ἄλλων ἀστέρων ἢ ὁ σύμπας οὐρανός. ἀλλὰ καὶ τῆς γῆς τὰ μὲν ὄρη πρὸς ὕψος αἴρεται περιμηκέστατον, ἡ δὲ πεδιὰς ὥσπερ αἱ χυταὶ οὐσίαι ἐπὶ πλεῖστον εὐρύνεται, καὶ ἡ θάλαττα μεταβάλλει πρὸς πότιμον ἢ οἱ ποταμοὶ πελαγῶν ἐξισοῦνται μεγέθεσιν. ἐπὶ μὲν οὖν τῶν αὐτῶν ὅρων ἕκαστον ἵδρυται ἐφ’ οἷς εὐθὺς ἐξ ἀρχῆς ὅτε ἐποίησεν ὁ θεὸς ἐτάχθη· σὺ δὲ βελτίων ἔσῃ ζῶν ἀνυπαιτίως. τί δὴ τούτων ἀργαλέον ἐστὶν ἢ ἐπίπονον;", "st": "300"}, {"sp": "N", "t": "οὐκ ἄπλωτα πελάγη δεῖ περαιοῦσθαι καὶ μέσου χειμῶνος κλύδωνι καὶ βίαις ἐναντίων πνευμάτων κλονουμένους ἄνω καὶ κάτω θαλαττεύειν ἢ τραχείας καὶ ἀτριβεῖς πεζεύειν ἀνοδίας, οὐχ ὁδούς, λῃστῶν ἢ θηρίων ἐφόδους ἀεὶ κατεπτηχότας ἢ τειχοφυλακεῖν ἐν ὑπαίθρῳ νυκτερεύοντας, ἐφεδρευόντων πολεμίων καὶ τοὺς ἀνωτάτω κινδύνους ἀπειλούντων — ἄπαγε, μηδὲν ἐπὶ καλοῖς λεγέσθω τῶν ἀηδῶν· εὐφημητέον ἐπὶ τοῖς οὕτω συμφέρουσιν.", "st": "301"}, {"sp": "N", "t": "ἐπινεῦσαι μόνον δεῖ τὴν ψυχήν, καὶ πάρεστιν ἐν ἑτοίμῳ τὰ πάντα. ἢ τοῦτο ἀγνοεῖς, ὅτι τοῦ θεοῦ καὶ ὁ αἰσθητός ἐστιν οὐρανὸς καὶ ὁ νοητός, ὁ κυρίως, εἴποι τις ἄν, “οὐρανὸς οὐρανοῦ”, καὶ πάλιν ἡ γῆ καὶ τὰ ἐν αὐτῇ καὶ σύμπας ὁ κόσμος, ὅ τε ὁρατὸς καὶ ὁ ἀόρατος καὶ ἀσώματος, τὸ παράδειγμα τοῦ ὁρατοῦ οὐρανοῦ;", "st": "302"}, {"sp": "N", "t": "ἀλλ’ ὅμως καὶ ἐξ ἅπαντος ἀνθρώπων γένους τοὺς πρὸς ἀλήθειαν ἀνθρώπους ἀριστίνδην ἐπιλέξας εἵλετο καὶ προνομίας ἠξίωσε τῆς πάσης, ἐπὶ τὴν θεραπείαν καλέσας ἑαυτοῦ, τὴν ἀέναον τῶν καλῶν πηγήν, ἀφ’ ἧς καὶ τὰς ἄλλας ὤμβρησεν ἀρετὰς καὶ ἀνέχεεν εἰς ἀπόλαυσιν ὠφελιμωτάτην, νέκταρος μᾶλλον ἢ οὐχ ἧττον ἀθανατίζον ποτόν.", "st": "303"}, {"sp": "N", "t": "οἰκτροὶ δὲ καὶ κακοδαίμονες ὅσοι μὴ τὸν ἀρετῆς πότον εὐωχήθησαν καὶ κακοδαιμονέστατοι διετέλεσαν οἱ εἰς ἅπαν ἄγευστοι καλοκἀγαθίας, παρὸν καὶ ἐνευφρανθῆναι καὶ ἐντρυφῆσαι δικαιοσύνῃ καὶ ὁσιότητι· ἀλλ’ εἰσὶν ἀπερίτμητοι τὴν καρδίαν, ᾗ φησιν ὁ νόμος, καὶ διὰ σκληρότητα τρόπων ἀφηνιασταί, σκιρτῶντες αὐθαδῶς καὶ ἀπαυχενίζοντες·", "st": "304"}, {"sp": "N", "t": "οὓς νουθετεῖ φάσκων· “περιτέμνεσθε τὴν σκληροκαρδίαν”, τὸ δέ ἐστι, τὰς περιττευούσας φύσεις τοῦ ἡγεμονικοῦ, ἃς αἱ ἄμετροι τῶν παθῶν ἔσπειράν τε καὶ συνηύξησαν ὁρμαὶ καὶ ὁ κακὸς ψυχῆς γεωργὸς ἐφύτευσεν, ἀφροσύνη, μετὰ σπουδῆς ἀποκείρασθε.", "st": "305"}, {"sp": "N", "t": "καὶ ὁ τράχηλος, φησίν, ὑμῶν μὴ σκληρὸς ἔστω, τουτέστι, μὴ ἀκαμπὴς ὁ νοῦς καὶ αὐθαδέστατος, μηδ’ ὑπὸ τῆς ἄγαν σκαιότητος ἐπιτηδευέτω τὴν βλαβερωτάτην ἀμαθίαν, ἀλλὰ τὸ φύσει δύσκολον καὶ δύστροπον ἀποθέμενος ὡς ἐχθρὸν μεταβαλλέτω πρὸς τὸ εὔκολον, πειθαρχήσων νόμοις φύσεως.", "st": "306"}, {"sp": "N", "t": "ἢ οὐχ ὁρᾷς, ὅτι περὶ τὸ ὂν αἱ πρῶται καὶ μέγισται τῶν δυνάμεών εἰσιν, ἥ τε εὐεργέτις καὶ κολαστήριος; καὶ προσηγόρευται ἡ μὲν εὐεργέτις θεός, ἐπειδὴ κατὰ ταύτην ἔθηκε καὶ διεκόσμησε τὸ πᾶν, ἡ δὲ ἑτέρα κύριος, καθ’ ἣν ἀνῆπται τῶν ὅλων τὸ κράτος. θεὸς δὲ οὐκ ἀνθρώπων μόνον ἀλλὰ καὶ θεῶν ἐστι θεός, καὶ ἄρχων οὐκ ἰδιωτῶν μόνον ἀλλὰ καὶ ἀρχόντων, μέγας τέ ἐστιν ὢν ὄντως καὶ ἰσχυρὸς καὶ", "st": "307"}, {"sp": "N", "t": "κραταιός. ἀλλ’ ὅμως. ὁ τοσοῦτος ἐν ἀρεταῖς καὶ δυνάμεσιν ἔλεον καὶ οἶκτον λαμβάνει τῶν ἐν ἐνδείαις ἀπορωτάτων, οὐκ ἀπαξιῶν γενέσθαι κριτὴς προσηλύτοις ἢ ὀρφανοῖς ἢ χήραις, ἀλλὰ βασιλέων καὶ τυράννων καὶ τῶν ἐν μεγάλαις δυναστείαις ὑπεριδὼν τὸ ταπεινὸν τῶν λεχθέντων ἀξιοῖ προνοίας.", "st": "308"}, {"sp": "N", "t": "τῶν μὲν ἐπηλύτων διὰ τόδε· καταλιπόντες οὗτοι τὰ πάτρια οἷς ἐνετράφησαν ψευδῶν πλασμάτων γέμοντα καὶ τύφου, γενόμενοι ἀτυφίας καὶ ἀληθείας ἐρασταὶ γνήσιοι, μετεχώρησαν πρὸς εὐσέβειαν, ἱκέται τε καὶ θεραπευταὶ τοῦ ὄντως ὄντος ἀξίως ὄντες τῆς προνοίας τῆς ἁρμοττούσης εἰκότως μεταλαγχάνουσι, καρπὸν εὑράμενοι τῆς ἐπὶ τὸν θεὸν καταφυγῆς τὴν ἀπ’ αὐτοῦ βοήθειαν.", "st": "309"}, {"sp": "N", "t": "ὀρφανῶν δὲ καὶ χηρῶν, ἐπειδὴ κηδεμόνας ἀφῄρηνται, οἱ μὲν γονεῖς, αἱ δὲ ἄνδρας, καταφυγὴ δ’ οὐδεμία τοῖς οὕτως ἐρήμοις ἐξ ἀνθρώπων ἀπολείπεται· διὸ τῆς μεγίστης ἐλπίδος οὐκ ἀμοιροῦσι, τοῦ θεοῦ, διὰ τὴν ἵλεω φύσιν αὐτοῦ τὴν πρόνοιαν καὶ ἐπιμέλειαν μὴ ἀποστραφέντος τῶν οὕτως ἐρήμων.", "st": "310"}, {"sp": "N", "t": "ἔστω δή, φησί, μόνος θεὸς αὔχημά σου καὶ μέγιστον κλέος, καὶ μήτ’ ἐπὶ πλούτῳ μήτε δόξῃ μήτε ἡγεμονίᾳ μήτε σώματος εὐμορφίᾳ μήτε ῥώμῃ μήτε τοῖς παραπλησίοις, ἐφ’ οἷς εἰώθασιν οἱ κενοὶ φρενῶν ἐπαίρεσθαι, σεμνυνθῇς, λογισάμενος ὅτι πρῶτον μὲν ἀμέτοχα ταῦτ’ ἐστὶ τῆς τοῦ ἀγαθοῦ φύσεως, ἔπειτα δ’ ὅτι καιρὸν ὀξὺν ἔχει τῆς μεταβολῆς, μαραινόμενα τρόπον τινά, πρὶν ἀνθῆσαι βεβαίως.", "st": "311"}, {"sp": "N", "t": "ὃ δὴ πάγιον καὶ ἄτρεπτον καὶ ἀμετάβλητον ἀγαθὸν μεταδιώκωμεν καὶ τῆς ἱκεσίας καὶ θεραπείας αὐτοῦ περιεχώμεθα καὶ μήτε κρατήσαντες ἐχθρῶν ζηλώσωμεν τὰς ἐκείνων ἐν αἷς εὐσεβεῖν δοκοῦσιν ἀσεβείας υἱοὺς καὶ θυγατέρας τοῖς αὑτῶν κατακαίοντες θεοῖς — οὐχ", "st": "312"}, {"sp": "N", "t": "ὅτι τὰ τέκνα πᾶσι τοῖς βαρβάροις ἐμπιμπράναι δι’ ἔθους ἐστίν· οὐ γὰρ οὕτως ἐξηγρίωνται τὰς φύσεις, ὡς, ἃ μηδὲ πολεμίους καὶ ἐχθροὺς ἀσυμβάτους ἐν πολέμῳ, ταῦτα τοὺς φιλτάτους καὶ οἰκειοτάτους ἐν εἰρήνῃ δρᾶν ὑπομένειν· ἀλλ’ ὅτι τὰς ψυχὰς τῷ ὄντι καταφλέγουσι καὶ διαφθείρουσιν ὧν ἐγέννησαν ἐξ ἔτι σπαργάνων ἁπαλαῖς ἔτι μὴ ἐγχαράττοντες τὰς ἀληθείας δόξας περὶ τοῦ ἑνὸς καὶ πρὸς ἀλήθειαν ὄντος θεοῦ — μήτ’ οὖν ἡττηθέντες ἀναπέσωμεν καὶ ὑπαχθῶμεν ταῖς ἐκείνων εὐτυχίαις ὡς δι’ εὐσέβειαν νενικηκότων·", "st": "313"}, {"sp": "N", "t": "πολλοῖς γὰρ ἐπ’ ἐνέδρᾳ συμβαίνουσιν αἱ παραυτίκα εὐπραγίαι δέλεαρ σφοδρῶν καὶ ἀνιάτων οὖσαι κακῶν· εἰκὸς δὲ καὶ ἀναξίους ὄντας κατορθοῦν, μὴ δι’ ἑαυτούς, ἀλλὰ ὑπὲρ τοῦ λυπεῖσθαι καὶ ἀνιᾶσθαι σφοδρότερον ἡμᾶς οὐχ ὅσια δρῶντας, οἳ γεννηθέντες ἐν πολιτείᾳ φιλοθέῳ καὶ ἐντραφέντες νόμοις ἐπὶ πᾶσαν ἀρετὴν ἀλείφουσι καὶ ἐκ πρώτης ἡλικίας παιδευόμενοι τὰ κάλλιστα παρὰ θεσπεσίοις ἀνδράσι τῶν μὲν ὀλιγωροῦμεν, τῶν δ’ ὡς ἀληθῶς ὀλιγωρίας ἀξίων περιεχόμεθα, παιδιὰν μὲν τὰ σπουδαῖα, σπουδὴν δὲ τὰ παιδιᾶς ἄξια ἡγούμενοι.", "st": "314"}, {"sp": "N", "t": "Κἂν μέντοι τις ὄνομα καὶ σχῆμα προφητείας ὑποδύς, ἐνθουσιᾶν καὶ κατέχεσθαι δοκῶν, ἄγῃ πρὸς τὴν τῶν νενομισμένων κατὰ πόλεις θρησκείαν θεῶν, οὐκ ἄξιον προσέχειν ἀπατωμένους ὀνόματι προφήτου· γόης γὰρ ἀλλ’ οὐ προφήτης ἐστὶν ὁ τοιοῦτος, ἐπειδὴ ψευδόμενος λόγια καὶ χρησμοὺς ἐπλάσατο.", "st": "315"}, {"sp": "N", "t": "κἂν ἀδελφὸς ἢ υἱὸς ἢ θυγάτηρ ἢ γυνὴ ἡ οἰκουρὸς ἢ γνήσιος φίλος ἤ τις ἕτερος εὔνους εἶναι δοκῶν εἰς τὰ ὅμοια ἐνάγῃ προτρέπων συνασμενίζειν τοῖς πολλοῖς καὶ ἐπὶ τὰ αὐτὰ ἱερὰ καὶ τὰς αὐτὰς σπονδάς τε καὶ θυσίας ἀφικνεῖσθαι, κολαστέον ὡς δήμιον καὶ κοινὸν ἐχθρὸν ὄντα ὀλίγα φροντίσαντας οἰκειότητος καὶ τὰς παραινέσεις αὐτοῦ διαγγελτέον πᾶσι τοῖς εὐσεβείας ἐρασταῖς, οἳ ἀνυπερθέτῳ τάχει ταῖς κατ’ ἀνδρὸς ἀνοσίου τιμωρίαις ἐπιδραμοῦνται κρίνοντες εὐαγὲς τὸ κατ’ αὐτοῦ φονᾶν.", "st": "316"}, {"sp": "N", "t": "ἔστω γὰρ ἡμῖν μία οἰκειότης καὶ φιλίας ἓν σύμβολον ἡ πρὸς θεὸν ἀρέσκεια καὶ τὸ πάντα λέγειν τε καὶ πράττειν ὑπὲρ εὐσεβείας· αἱ δ’ ἐκ προγόνων ἀφ’ αἵματος αὗται λεγόμεναι συγγένειαι καὶ αἱ κατ’ ἐπιγαμίας ἤ τινας ἄλλας ὁμοιοτρόπους αἰτίας οἰκειότητες ἀπορριπτέσθωσαν, εἰ μὴ πρὸς τὸ αὐτὸ τέλος ἐπείγονται, τὴν τοῦ θεοῦ τιμήν, ἣ πάσης ἑνωτικῆς εὐνοίας ἄλυτος δεσμός ἐστιν· ἀντιλήψονται γὰρ οἱ τοιοῦτοι σεμνοτέρας καὶ ἱεροπρεπεστέρας συγγενείας.", "st": "317"}, {"sp": "N", "t": "βεβαιοῦται δέ μου τὴν ὑπόσχεσιν ὁ νόμος λέγων, ὅτι οἱ “τὸ ἀρεστὸν” τῇ φύσει δρῶντες καὶ “τὸ καλὸν” υἱοί εἰσι τοῦ θεοῦ, φησὶ γάρ· “υἱοί ἐστε κυρίῳ τῷ θεῷ ὑμῶν”, δηλονότι προνοίας καὶ κηδεμονίας ἀξιωθησόμενοι τῆς ὡς ἐκ πατρός· ἡ δὲ ἐπιμέλεια τοσοῦτον διοίσει τῆς ἀπ’ ἀνθρώπων, ὅσονπερ, οἶμαι, καὶ ὁ ἐπιμελούμενος διαφέρει.", "st": "318"}, {"sp": "N", "t": "Πρὸς τούτοις ἔτι τὰ περὶ τελετὰς καὶ μυστήρια καὶ πᾶσαν τὴν τοιαύτην τερθρείαν καὶ βωμολοχίαν ἐκ τῆς ἱερᾶς ἀναιρεῖ νομοθεσίας, οὐκ ἀξιῶν τοὺς ἐν τοιαύτῃ πολιτείᾳ τραφέντας ὀργιάζεσθαι καὶ μυστικῶν πλασμάτων ἐκκρεμαμένους ὀλιγωρεῖν ἀληθείας καὶ τὰ νύκτα καὶ σκότος προσκεκληρωμένα μεταδιώκειν παρέντας τὰ ἡμέρας καὶ φωτὸς ἄξια. μηδεὶς οὖν μήτε τελείτω μήτε τελείσθω τῶν Μωυσέως φοιτητῶν καὶ γνωρίμων· ἑκάτερον γὰρ καὶ τὸ διδάσκειν καὶ τὸ μανθάνειν τελετὰς οὐ μικρὸν ἀνοσιούργημα.", "st": "319"}, {"sp": "N", "t": "τί γάρ, εἰ καλὰ ταῦτ’ ἐστίν, ὦ μύσται, καὶ συμφέροντα, συγκλεισάμενοι ἑαυτοὺς ἐν σκότῳ βαθεῖ τρεῖς ἢ τέτταρας μόνους ὠφελεῖτε, παρὸν ἅπαντας ἀνθρώπους ἐν ἀγορᾷ μέσῃ τὰ τῆς ὠφελείας προθέντας, ἵνα πᾶσιν ἀδεῶς ἐξῇ βελτίονος καὶ εὐτυχεστέρου κοινωνῆσαι βίου; φθόνος γὰρ ἀρετῆς διῴκισται.", "st": "320"}, {"sp": "N", "t": "οἱ μὲν γὰρ τὰ βλαβερὰ πράττοντες αἰσχυνέσθωσαν καὶ καταδύσεις ἐπιζητοῦντες καὶ γῆς μυχοὺς καὶ βαθὺ σκότος ἐπικρυπτέσθωσαν τὴν πολλὴν ἀνομίαν αὑτῶν ἐπισκιάζοντες, ὡς μηδεὶς ἴδοι· τοῖς δὲ τὰ κοινωφελῆ δρῶσιν ἔστω παρρησία καὶ μεθ’ ἡμέραν διὰ μέσης ἴτωσαν ἀγορᾶς ἐντευξόμενοι πολυανθρώποις ὁμίλοις, ἡλίῳ καθαρῷ τὸν ἴδιον βίον ἀνταυγάσοντες καὶ διὰ τῶν κυριωτάτων αἰσθήσεων τοὺς συλλόγους ὀνήσοντες, ὁρῶντας μὲν ἡδίστας ὁμοῦ καὶ καταπληκτικωτάτας ὄψεις, ἀκούοντας δὲ καὶ ἑστιωμένους λόγων ποτίμων, οἳ τὰς διανοίας τῶν μὴ σφόδρα ἀμούσων εἰώθασιν εὐφραίνειν. ἢ οὐχ", "st": "321"}, {"sp": "N", "t": "ὁρᾷς, ὅτι καὶ ἡ φύσις τῶν ἑαυτῆς ἀοιδίμων καὶ παγκάλων ἔργων οὐδὲν ἀπέκρυψεν, ἀλλὰ ἀστέρας μὲν καὶ τὸν σύμπαντα οὐρανὸν εἴς τε τὴν δι’ ὄψεως τέρψιν καὶ πρὸς φιλοσοφίας ἵμερον ἀπέφηνεν, πελάγη δὲ καὶ πηγὰς καὶ ποταμοὺς καὶ τὰς ἀέρος εὐκρασίας δι’ ἀνέμων τε καὶ πνευμάτων εἰς τὰς ἐτησίους ὥρας, φυτῶν τε καὶ ζῴων ἔτι δὲ καρπῶν ἀμυθήτους ἰδέας εἰς χρῆσιν καὶ ἀπόλαυσιν ἀνθρώπων;", "st": "322"}, {"sp": "N", "t": "εἶτ’ οὐκ ἐχρῆν καὶ ἡμᾶς ἑπομένους τοῖς ἐκείνης βουλήμασι πάνθ’ ὅσα ἀναγκαῖα καὶ χρήσιμα προτιθέναι πᾶσι τοῖς ἀξίοις ἐπ’ ὠφελείᾳ; νῦν δὲ συμβαίνει πολλάκις τῶν μὲν ἀγαθῶν ἀνδρῶν μηδένα μυεῖσθαι, λῃστὰς δ’ ἔστιν ὅτε καὶ καταποντιστὰς καὶ γυναικῶν θιάσους βδελυκτῶν καὶ ἀκολάστων, ἐπειδὰν ἀργύριον παράσχωσι τοῖς τελοῦσι καὶ ἱεροφαντοῦσιν. ὑπερόριοι δὴ πάντες οὗτοι φυγαδευέσθωσαν πόλεως καὶ καταστάσεως, ἐν ᾗ τὸ καλὸν καὶ ἡ ἀλήθεια δι’ αὐτὰ τιμᾶται. ταῦτα μὲν ἐπὶ τοσοῦτον.", "st": "323"}, {"sp": "N", "t": "Κοινωνίας δὲ καὶ φιλανθρωπίας εἰσηγητὴς ὢν ἐν τοῖς μάλιστα ὁ νόμος ἑκατέρας ἀρετῆς τήν τε ἀξίωσιν καὶ τὴν σεμνότητα διετήρησεν, οὐδενὶ τῶν ἀνιάτως ἐχόντων ἐπιτρέψας καταφυγεῖν ἐπ’ αὐτάς, ἀλλὰ πορρωτάτω σκορακίσας.", "st": "324"}, {"sp": "N", "t": "ἐπιστάμενος γοῦν ἐν ταῖς ἐκκλησίαις οὐκ ὀλίγους τῶν μοχθηρῶν παρεισρέοντας καὶ διὰ τὸ συνειλεγμένον πλῆθος λανθάνοντας, ἵνα μὴ τοῦτο γένηται, προανείργει πάντας τοὺς ἀναξίους ἱεροῦ συλλόγου τὴν ἀρχὴν ποιούμενος ἀπὸ τῶν νοσούντων τὴν θήλειαν νόσον ἀνδρογύνων, οἳ τὸ φύσεως νόμισμα παρακόπτοντες εἰς ἀκολάστων γυναικῶν πάθη καὶ μορφὰς εἰσβιάζονται· θλαδίας γὰρ καὶ ἀποκεκομμένους τὰ γεννητικὰ ἐλαύνει τό τε τῆς ὥρας ταμιεύοντας ἄνθος, ἵνα μὴ ῥᾳδίως μαραίνοιτο, καὶ τὸν ἄρρενα τύπον μεταχαράττοντας εἰς θηλύμορφον ἰδέαν. ἐλαύνει δὲ οὐ μόνον πόρνας ἀλλὰ καὶ τοὺς ἐκ πόρνης,", "st": "325"}, {"sp": "N", "t": "ἐπιφερομένους μητρῷον αἶσχος, [καὶ] διότι ἡ πρώτη σπορὰ καὶ γένεσις αὐτοῖς κεκιβδήλευται καὶ συγκέχυται διὰ τὸ πλῆθος τῶν ὡμιληκότων ταῖς μητράσιν, ὡς μὴ δύνασθαι τὸν ἀληθῆ πατέρα διαγνῶναι καὶ διακρῖναι.", "st": "326"}, {"sp": "N", "t": "ὁ δὲ τόπος οὗτος, εἰ καί τις ἄλλος, ἀλληγορίαν ἐπιδέχεται φιλοσόφου θεωρίας ὢν ἀνάπλεως· τῶν γὰρ ἀσεβῶν καὶ ἀνοσίων οὐχ εἷς τρόπος, ἀλλὰ πολλοὶ καὶ διαφέροντες. οἱ μὲν γὰρ τὰς ἀσωμάτους ἰδέας ὄνομα κενὸν ἀμέτοχον ἀληθοῦς πράγματος εἶναί φασι, τὴν ἀναγκαιοτάτην οὐσίαν ἐκ τῶν ὄντων ἀναιροῦντες, ἥτις ἐστὶν ἀρχέτυπον παράδειγμα πάντων ὅσα ποιότητες οὐσίας, καθ’ ἣν ἕκαστον εἰδοποιεῖτο καὶ διεμετρεῖτο.", "st": "327"}, {"sp": "N", "t": "τούτους αἱ ἱεραὶ τοῦ νόμου στῆλαι μηνύουσι “θλαδίας”· ὡς γὰρ τὸ τεθλασμένον ἀφῄρηται τὴν ποιότητα καὶ τὸ εἶδος καὶ οὐδὲν ἕτερόν ἐστιν ἢ κυρίως εἰπεῖν ἄμορφος ὕλη, οὕτως καὶ ἡ ἀναιροῦσα δόξα ἰδέας πάντα συγχεῖ καὶ πρὸς τὴν ἀνωτέρω τῶν στοιχείων οὐσίαν τὴν ἄμορφον καὶ ἄποιον ἐκείνην ἄγει.", "st": "328"}, {"sp": "N", "t": "οὗ τί γένοιτ’ ἂν ἀτοπώτερον; ἐξ ἐκείνης γὰρ πάντ’ ἐγέννησεν ὁ θεός, οὐκ ἐφαπτόμενος αὐτός — οὐ γὰρ ἦν θέμις ἀπείρου καὶ πεφυρμένης ὕλης ψαύειν τὸν εὐδαίμονα καὶ μακάριον —, ἀλλὰ ταῖς ἀσωμάτοις δυνάμεσιν, ὧν ἔτυμον ὄνομα αἱ ἰδέαι, κατεχρήσατο πρὸς τὸ γένος ἕκαστον τὴν ἁρμόττουσαν λαβεῖν μορφήν. ἡ δὲ πολλὴν ἀταξίαν εἰσηγεῖται καὶ σύγχυσιν· ἀναιροῦσα γὰρ ταῦτα, δι’ ὧν αἱ ποιότητες, συναναιρεῖ ποιότητας.", "st": "329"}, {"sp": "N", "t": "ἕτεροι δ’ ὡς ἐν ἄθλοις κακίας τὰ ἐπ’ ἀσεβείᾳ νικητήρια σπεύδοντες αἴρεσθαι προσυπερβάλλουσιν ἅμα ταῖς ἰδέαις καὶ ὕπαρξιν θεοῦ παρακαλυπτόμενοι ὡς οὐκ ὄντος λεγομένου δ’ εἶναι χάριν τοῦ συμφέροντος ἀνθρώποις, οἳ δὴ δι’ εὐλάβειαν τοῦ δοκοῦντος πάντῃ παρεῖναι καὶ πάντα καθορᾶν ὄμμασιν ἀκοιμήτοις [[οἷς]ἶς] ἔμελλον ἀνέξειν ἀδικημάτων. τούτους ὁ νόμος εὐθυβόλως “ἀποκόπους” προσαγορεύει τὴν περὶ τοῦ πάντα γεννῶντος ἐκτετμημένους ὑπόληψιν, ἀγόνους μὲν σοφίας, ἐπιτηδεύοντας δὲ τὴν μεγίστην κακιῶν, ἀθεότητα.", "st": "330"}, {"sp": "N", "t": "τρίτοι δ’ εἰσὶν οἳ τὴν ἐναντίαν ἔτεμον εἰσηγησάμενοι πλῆθος θεῶν ἀρρένων τε καὶ θηλειῶν, πρεσβυτέρων τε αὖ καὶ νεωτέρων, πολυαρχίας λόγῳ τὸν κόσμον ἀναπλήσαντες, ἵνα τὴν τοῦ ἑνὸς καὶ ὄντως ὄντος ὑπόληψιν ἐκ τῆς ἀνθρώπων διανοίας ἐκτέμωσιν.", "st": "331"}, {"sp": "N", "t": "οὗτοι δ’ εἰσὶν οἱ συμβολικῶς “ἐκ πόρνης” ὑπὸ τοῦ νόμου προσαγορευόμενοι· καθάπερ γὰρ ὧν μητέρες πόρναι τὸν μὲν ἀληθῆ πατέρα οὔτε ἴσασιν οὔτ’ ἐπιγράψασθαι δύνανται, πολλοὺς δὲ καὶ σχεδὸν ἅπαντας τοὺς ἐραστὰς καὶ ὡμιληκότας, τὸν αὐτὸν τρόπον καὶ οἱ ἀγνοοῦντες τὸν ἕνα καὶ ἀληθινὸν θεὸν πολλοὺς καὶ ψευδωνύμους ἀναπλάττοντες περὶ τὸ ἀναγκαιότατον τῶν ὄντων τυφλώττουσιν, ὅπερ ἢ μόνον ἢ πρώτιστον ἐξ αὐτῶν σπαργάνων εἰκὸς ἦν ἀναδιδάσκεσθαι· τί γὰρ μάθημα κάλλιον ἢ τοῦ ὄντως", "st": "332"}, {"sp": "N", "t": "ὄντος θεοῦ; τετάρτους δὲ καὶ πέμπτους ἐλαύνει πρὸς μὲν τὸ αὐτὸ τέλος ἐπειγομένους, οὐ μὴν ἀπὸ τῶν αὐτῶν βουλευμάτων· ἀμφότεροι γὰρ ζηλωταὶ μεγάλου κακοῦ, φιλαυτίας, ὄντες ὥσπερ τινὰ κοινὴν οὐσίαν διενείμαντο τὴν ὅλην ψυχὴν ἐκ λογικοῦ καὶ ἀλόγου μέρους συνεστῶσαν· καὶ οἱ μὲν τὸ λογικόν, ὃ δὴ νοῦς ἐστι, διεκληρώσαντο, οἱ δὲ τὸ ἄλογον, ὅπερ εἰς τὰς αἰσθήσεις τέμνεται.", "st": "333"}, {"sp": "N", "t": "οἱ μὲν οὖν τοῦ νοῦ προστάται τὴν ἡγεμονίαν καὶ βασιλείαν τῶν ἀνθρωπείων πραγμάτων ἀνάπτουσιν αὐτῷ καί φασιν ἱκανὸν εἶναι καὶ τὰ παρεληλυθότα μνήμῃ διασῴζειν καὶ τῶν παρόντων ἐρρωμένως ἀντιλαμβάνεσθαι καὶ τὰ μέλλοντα εἰκότι στοχασμῷ φαντασιοῦσθαί τε καὶ λογίζεσθαι.", "st": "334"}, {"sp": "N", "t": "οὗτος γάρ ἐστιν ὁ γῆν τὴν βαθύγειον καὶ ἀρετῶσαν τῆς ὀρεινῆς καὶ πεδιάδος κατασπείρας καὶ καταφυτεύσας καὶ τὴν βιωφελεστάτην γεωργίαν εὑρών· οὗτος ὁ ναῦν κατασκευάσας καὶ τὴν χέρσου φύσιν ἐπινοίαις παντὸς λόγου κρείττοσι πλωτὴν ἀπεργασάμενος καὶ ὁδοὺς ἐν θαλάττῃ πολυσχιδεῖς ἄχρι λιμένων τῶν κατὰ πόλεις καὶ ὑποδρόμων λεωφόρους ἀνατεμὼν καὶ γνωρίσας ἠπειρώτας νησιώτας οὐκ ἄν ποτ’ εἰς ἑαυτοὺς ἐλθόντας, εἰ μὴ σκάφος ἐναυπηγήθη· οὗτος ὁ καὶ τῶν βαναύσων καὶ τῶν γλαφυρωτέρων τεχνῶν λεγομένων εὑρετής·", "st": "335"}, {"sp": "N", "t": "οὗτος γράμματα καὶ ἀριθμοὺς καὶ μουσικὴν καὶ τὴν ἐγκύκλιον ἅπασαν παιδείαν ἐπενόησε καὶ συνηύξησε καὶ πρὸς τὸ τέλος ἤγαγεν· οὗτος καὶ τὸ μέγιστον ἀγαθόν, φιλοσοφίαν, ἐγέννησε καὶ δι’ ἑκάστου τῶν μερῶν αὐτῆς ὠφέλησε τὸν ἀνθρώπινον βίον, διὰ μὲν τοῦ λογικοῦ πρὸς ἀνεξαπάτητον ἑρμηνείαν, διὰ δὲ τοῦ ἠθικοῦ πρὸς τὴν τῶν τρόπων ἐπανόρθωσιν, διὰ δὲ τοῦ φυσικοῦ πρὸς ἐπιστήμην οὐρανοῦ τε καὶ κόσμου. καὶ ἄλλα μέντοι παμπληθῆ λέγουσιν ἐγκώμια νοῦ συμφορήσαντές τε καὶ ἀγείραντες ἔχοντα τὴν ἀναφορὰν ἐπὶ τὰ λεχθέντα ἤδη, περὶ ὧν οὐ καιρὸς ἐνοχλεῖν.", "st": "336"}, {"sp": "N", "t": "οἱ δὲ τῶν αἰσθήσεων προστάται τὸν ἔπαινον αὐτῶν εὖ μάλα σεμνοποιοῦσι διανέμοντες τῷ λόγῳ τὰς ἀπ’ αὐτῶν ἐγγινομένας χρείας καί φασιν, ὅτι δύο μὲν αἴτια τοῦ ζῆν ἐστιν, ὄσφρησις καὶ γεῦσις, δύο δὲ τοῦ καλῶς ζῆν, ὅρασις καὶ ἀκοή.", "st": "337"}, {"sp": "N", "t": "διὰ μὲν οὖν γεύσεως αἱ τῶν σιτίων τροφαὶ παραπέμπονται, διὰ δὲ μυκτήρων ὁ ἀήρ, οὗ πᾶν ζῷον ἐξήρτηται· τροφὴ δ’ ἐστὶ καὶ οὗτος ἡ συνεχὴς καὶ ἀδιάστατος, ὃς οὐκ ἐγρηγορότας μόνον ἀλλὰ καὶ κοιμωμένους διατρέφει τε καὶ διασῴζει· σαφὴς δὲ πίστις· εἰ γὰρ κἂν βραχύτατον ὁ τῆς ἀναπνοῆς δίαυλος ἐπισχεθείη κατὰ τὴν τοῦ πεφυκότος ἔξωθεν ἐποχετεύεσθαι πνεύματος ἀποκοπήν, θάνατος ἀπαραίτητος ἐξ ἀνάγκης ἐπακολουθήσει.", "st": "338"}, {"sp": "N", "t": "τῶν γε μὴν φιλοσόφων αἰσθήσεων, δι’ ὧν περιγίνεται τὸ εὖ ζῆν, ὅρασις μὲν φῶς τὸ κάλλιστον ἐν τοῖς οὖσιν ὁρᾷ, ὁρᾷ δὲ διὰ φωτὸς τἄλλα πάντα, ἥλιον, σελήνην, ἀστέρας, οὐρανόν, γῆν, θάλατταν, φυτῶν καὶ ζῴων ἀμυθήτους διαφοράς, καὶ συνόλως πάντα σώματα καὶ σχήματα καὶ χρώματα καὶ μεγέθη, ὧν ἡ θέα περιττὴν φρόνησιν ἐξειργάσατο καὶ πολὺν ἵμερον ἐπιστήμης ἐγέννησε.", "st": "339"}, {"sp": "N", "t": "παρέχεται δὲ καὶ ἄνευ τούτων ὠφελείας ὅρασις ἡμῖν τὰς μεγίστας, εἴς τε τὴν οἰκείων καὶ ἀλλοτρίων καὶ φίλων καὶ ἐχθρῶν διάκρισιν καὶ βλαβερῶν μὲν φυγήν, αἵρεσιν δὲ τῶν ἐπ’ ὠφελείᾳ. γέγονε μὲν οὖν καὶ τῶν ἄλλων ἕκαστον τοῦ σώματος μερῶν πρὸς ἁρμοττούσας χρείας καὶ σφόδρα ἀναγκαίας, ὡς βάσεις μὲν πρὸς περίπατον καὶ δρόμον καὶ τἄλλα ὅσα διὰ σκελῶν ἐνεργεῖται, χεῖρες δὲ πρὸς τὸ πρᾶξαί τι καὶ δοῦναι καὶ λαβεῖν· ὀφθαλμοὶ δὲ ὡσπερεί τι κοινὸν ἀγαθὸν τὴν τοῦ δύνασθαι κατορθοῦν αἰτίαν καὶ τούτοις καὶ τοῖς ἄλλοις ἅπασι παρέχουσιν.", "st": "340"}, {"sp": "N", "t": "ἀψευδέστατοι δ’ οἱ πεπηρωμένοι μάρτυρες, οἳ μήτε χερσὶ μήτε ποσὶ δύνανται χρῆσθαι κατὰ τὸ βέλτιον τὴν πρόσρησιν ἐπαληθεύοντες, ἣν οὐκ ἐπ’ ὀνείδει μᾶλλον ἢ οἴκτῳ θέσθαι φασὶ τοὺς πρότερον ἀδυνάτους ὀνομάσαντας· ἅμα γὰρ τῇ τῶν ὀμμάτων φθορᾷ καὶ αἱ τοῦ σώματος δυνάμεις οὐχ ὑποσκελίζονται μόνον ἀλλὰ καὶ φθείρονται. θαυμασιώτατον δὲ καὶ ἀκοὴ χρῆμα, δι’ ἧς μέλη καὶ μέτρα καὶ ῥυθμοί,", "st": "341"}, {"sp": "N", "t": "ἔτι δὲ ἁρμονίαι καὶ συμφωνίαι καὶ τῶν γενῶν καὶ συστημάτων αἱ μεταβολαὶ καὶ πάνθ’ ὅσα κατὰ μουσικὴν ἐπικρίνεται, καὶ λόγων [τε] τῶν κατὰ διεξόδους [καὶ] παμπληθεῖς ἰδέαι δικανικῶν συμβουλευτικῶν ἐγκωμιαστικῶν, ἔτι δὲ τῶν ἐν ἱστορίαις καὶ διαλόγοις καὶ τῶν ἐν ὁμιλίαις ἀναγκαίαις περὶ τῶν ἐν βίῳ πραγμάτων πρὸς τοὺς ἀεὶ πλησιάζοντας· συνόλως γὰρ διὰ φωνῆς διττὴν ἐχούσης δύναμιν, εἴς τε τὸ λέγειν καὶ τὸ ᾄδειν, ἑκάτερα ταῦτα διακρίνει πρὸς ὠφέλειαν ψυχῆς·", "st": "342"}, {"sp": "N", "t": "ᾠδὴ γὰρ καὶ λόγος ὑγιεινὰ καὶ σωτήρια φάρμακα, ἡ μὲν τὰ πάθη κατεπᾴδουσα καὶ τὸ ἄρρυθμον ἐν ἡμῖν ῥυθμοῖς, τὸ δ’ ἐκμελὲς μέλεσι, τὸ δ’ ἄμετρον μέτροις ἐπιστομίζουσα — ποικίλον δ’ ἐστὶ καὶ παντοδαπὸν ἕκαστον, ὡς μουσικοὶ καὶ ποιηταὶ μαρτυροῦσιν, οἷς πιστεύειν ἀναγκαῖον ἐπιτήδευμα τοῖς εὖ πεπαιδευμένοις —, ὁ δὲ λόγος ἐπέχων καὶ ἀνακόπτων τὰς ἐπὶ κακίαν ὁρμὰς καὶ τοὺς κεκρατημένους ἀφροσύναις καὶ ἀηδίαις ἐκνοσηλεύων, μαλακώτερον μὲν τοὺς ὑπείκοντας, σφοδρότερον δὲ τοὺς ἀφηνιάζοντας, αἴτιος γίνεται τῶν μεγίστων ὠφελειῶν.", "st": "343"}, {"sp": "N", "t": "τοιαῦτα συνείροντες οἵ τε τοῦ νοῦ θιασῶται καὶ οἱ τῶν αἰσθήσεων οἱ μὲν ἐκεῖνον οἱ δὲ ταύτας θεοπλαστοῦσιν ὑπὸ φιλαυτίας ἐκλαθόμενοι τοῦ πρὸς ἀλήθειαν ὄντος θεοῦ. διὸ πάντας εἰκότως ἀπήλασεν ἱεροῦ συλλόγου, τούς τε τὰς ἰδέας ἀναιροῦντας, “θλαδίας” ὑπειπών, καὶ τοὺς κατὰ τὸ παντελὲς ἀθέους, οἷς ὄνομα οἰκεῖον τὸ “ἀποκόπων” ἔθετο, καὶ τοὺς ἐξ ἐναντίας εἰσηγητὰς θεογονίας, οὓς ἐκάλεσεν “ἐκ πόρνης”, καὶ ἐπὶ πᾶσι τοὺς φιλαύτους, ὧν οἱ μὲν τὸν λογισμόν, οἱ δ’ ἑκάστην τῶν αἰσθήσεων ἐξεθείωσαν· ἐπείγονται γὰρ πάντες οὗτοι πρὸς τὸ αὐτὸ τέλος, εἰ καὶ ἀπὸ διαφερόντων ἄγονται βουλευμάτων, τὸν ἕνα καὶ ὄντως ὄντα θεὸν παρησυχάζοντες.", "st": "344"}, {"sp": "N", "t": "ἀλλ’ ἡμεῖς γε οἱ φοιτηταὶ καὶ γνώριμοι τοῦ προφήτου Μωυσέως τὴν τοῦ ὄντος ζήτησιν οὐ μεθησόμεθα, τὴν ἐπιστήμην αὐτοῦ τέλος εὐδαιμονίας εἶναι νομίζοντες καὶ ζωὴν μακραίωνα, καθὰ καὶ ὁ νόμος φησὶ τοὺς προσκειμένους τῷ θεῷ ζῆν ἅπαντας, δόγμα τιθεὶς ἀναγκαῖον καὶ φιλόσοφον· ὄντως γὰρ οἱ μὲν ἄθεοι τὰς ψυχὰς τεθνᾶσιν, οἱ δὲ τὴν παρὰ τῷ ὄντι θεῷ τεταγμένοι τάξιν ἀθάνατον βίον ζῶσιν.", "st": "345"}], []);})();
